WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[50328] = { title = "Unconventional Aromatics", description = "A deal's a deal. You got the stingers for me, so here's that big batch of honey I promised.\n\nI hope you and Rhan'ka enjoy it... slowly. Seriously, do not eat this all at once.\n\nOh, and I'm always looking to trade. Swing by anytime you got something to sell or want to pick up some more honey!", objectives = "" }
WordHunterWoW_QuestEN[50329] = { title = "Matrons of the Crimsonwood", description = "The witches in charge, the matrons...\n\n<Ashton shudders for a moment then composes himself.>\n\nThe matrons are the ones leading the Grand Rite. They are fearsome but not invulnerable. Removing some of them from the equation will bolster our chances of stopping this. \n\nTake this potion. It will be able to weaken the matrons so you might have a better chance of dispatching them.", objectives = "" }
WordHunterWoW_QuestEN[50331] = { title = "A Different Outcome", description = "There is no way to know when these orders were sent, or received.\n\nRokor took some Seekers north some time ago. They must be in that region by now. \n\nIf the temple still stands, warn Gral and his followers.\n\nIf it is lost, we must do what we can.", objectives = "" }
WordHunterWoW_QuestEN[50332] = { title = "Big Hunter Mon", description = "In these valleys, the Mon be kepin' beasts alive only to serve as sport. For his entertainment.\n\nThe lives of others not be so cheap. Even the smallest creature can cause a whole lotta trouble. The Mon gonna be learnin' to respect that.\n\nI think this be a good time to teach this Big Hunter Mon a lesson, don't you? Be you my faithful messenger?", objectives = "" }
WordHunterWoW_QuestEN[50335] = { title = "Grant Me Revenge", description = "I don't care who you pledge allegiance to, {race}. I need Hogger dead!\n\nHe--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.", objectives = "" }
WordHunterWoW_QuestEN[50336] = { title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nLet's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably....", objectives = "" }
WordHunterWoW_QuestEN[50337] = { title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", objectives = "" }
WordHunterWoW_QuestEN[50338] = { title = "The G-Team", description = "How did you get in here, {name}?\n\nI'm Murd Doc of the G-Team and we could use the help of a {race} like you.\n\nHelp us defeat the irradiated inhabatants that now call Gnomeregan home, and I'll make you an honorary G-Team Commando!\n\nTake this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", objectives = "" }
WordHunterWoW_QuestEN[50340] = { title = "Steal Them Back", description = "<This empty crate of supplies is clearly marked with Kul Tiran signage. These must be the spoils of their raids on the farms of the valley.\n\nThe citizens would probably like their supplies back if there are any left.>", objectives = "" }
WordHunterWoW_QuestEN[50343] = { title = "Mayhem at Mildenhall Meadery", description = "Ahhhh! Sir, please, I need some help!\n\nMy dad hasn't come back from the meadery and, and... well, when I went to look, there were giant globs of honey everywhere. \n\nBut... but, somehow, they were moving on their own. I even saw one eat a bunny, I swear!\n\nI'm scared to go back by myself, but I think dad is in trouble.\n\nCan you go with me?", objectives = "" }
WordHunterWoW_QuestEN[50349] = { title = "An Overrun Mine", description = "It was horrible! I was in the mine nearby, just picking away at a rock and it jumped up and bit me in the neck! Since when can rocks walk around and bite people?\n\nI hightailed it outta there, but some crazy fools are sticking around trying to take the mine back. If you're eager to punch rocks you can find them down the road to the south.", objectives = "" }
WordHunterWoW_QuestEN[50350] = { title = "We Need a Chemist", description = "All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine.\n\nFirst, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.", objectives = "" }
WordHunterWoW_QuestEN[50351] = { title = "Miner Operation", description = "The mine is in real trouble. We've been excavating for a short while, but never seen anything like this. Azerite doesn't just get up and walk around.\n\nIf we are going to take the mine back, we're going to need more help. We'll need an engineer and an explosives expert. I have two in mind, sisters actually, but they are caught behind the river in all the chaos.\n\nLocate the sisters and they'll help you with the next phase of the plan.", objectives = "" }
WordHunterWoW_QuestEN[50352] = { title = "Pinch of Azerite", description = "I don't have time for idle chit chat! If you haven't noticed, rocks are running around doing who knows what?!\n\nHow about you help out and retrieve my chemistry kit. While you're out, smash some of those creatures and collect their dust. Prim will need both of those for the next step of the plan.\n\nMaybe we can figure out what has animated the Azerite.", objectives = "" }
WordHunterWoW_QuestEN[50353] = { title = "Boaring Company", description = "I don't see her body anywhere. That means she could still be alive.\n\nThe Briarback have been taking prisoners, and anyone who has ever been taken by them was never seen again.\n\nWe have a single chance here and we need to take it!\n\nCome with me into the kraul and free as many of the survivors as you can. And if you can, find Farmer Deal. See if she's still alive.", objectives = "" }
WordHunterWoW_QuestEN[50354] = { title = "Look Out!", description = "Some of these quilboar are clearly lookouts. Those horns make it obvious, almost like I could see their task floating above their heads.\n\nI was able to kill one, but not before he blew that horn of his and summoned backup. I suggest you keep them silent before they do the same with you.\n\nIf we're going to get anywhere in there, you'll need to do it quietly. Here, Hobbs gave me a few of his sleeping darts. That should keep them quiet.", objectives = "" }
WordHunterWoW_QuestEN[50356] = { title = "Rock Meet Dynamite", description = "Thanks for your help out there, but we have to ask another favor from you.\n\nThese elementals must be coming from somewhere in the mine and we need you to locate that source. \n\nYou seem more than capable of handling yourself in there, but just for extra security I am going to send you with some of Prim's special dynamite. It has an extra kick from the Azerite dust that you gathered.\n\nGet in. Find the source. Put a stop to these elementals.", objectives = "" }
WordHunterWoW_QuestEN[50358] = { title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nIf it were up to me, I'd burn those wretched hives once and for all! However, it is not up to me.\n\nThe Dark Lady wants the surviving silithid dissected and studied. \n\nPixni Rustbomb is conducting the research and is in need of a \"collector.\"", objectives = "" }
WordHunterWoW_QuestEN[50359] = { title = "Cleanup Duty", description = "Wh...why, why is all of the honey alive and what happened to everybody?\n\nYou don't think... oh no! Please, {name}, tell me they haven't been eaten!\n\nAhhhh! That would be terrible. Please don't let me be eaten too!", objectives = "" }
WordHunterWoW_QuestEN[50360] = { title = "Khadgar's Request", description = "Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, {name}.\n\nHurry and see what it is that he wants. I want him gone as soon as possible.\n\nThe last thing we need is a human nosing around in Horde business!", objectives = "" }
WordHunterWoW_QuestEN[50363] = { title = "War Pigs", description = "They look cute enough now, but that's a new herd of battleboars in training.\n\nFarmers don't like waste, and it would be a shame to get rid of such useful creatures.\n\nEither way, we could use those pigs, and I'd rather have them with us rather than face a bloodthirsty one in a few years. You should find them up on top of the cliffs overlooking the center of the kraul. Go round up as many piglets as you can take with you and we'll make good use of them.", objectives = "" }
WordHunterWoW_QuestEN[50364] = { title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Horde. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", objectives = "" }
WordHunterWoW_QuestEN[50365] = { title = "Run For the Hills", description = "The quilboar are up to something, something big. You need to stop it!\n\nThey've been busy bringing supplies up to the caves above their sanctum. Preserved thorns, cauldrons of venom, giant totems...\n\nThey're preparing for war.\n\nGet up there and destroy those stockpiles before they can be used against the citizens of the valley!", objectives = "" }
WordHunterWoW_QuestEN[50367] = { title = "Anger in a Bottle", description = "<The bottle the quilboar was carrying contains a foul-smelling, orange liquid. You're not sure if it's safe to drink, but it can't hurt to gather some samples to bring back to the citizens of Brennadam.\n\nMaybe their alchemist can come up with an antidote to counter its effects.>", objectives = "" }
WordHunterWoW_QuestEN[50368] = { title = "Terror of the Kraul", description = "By all the gods of the sea, what a monster!\n\nI can barely believe what I am seeing, {name}. This ettin has undergone the same ritual that the brutes do, and it seems even angrier! If he gets out of here, we won't stand a chance.\n\nI know I ask the impossible, but I must: kill this monstrosity and save the whole valley from its wrath! Here, take one of the potion samples you brought me. It's probably dangerous, but you might need it to defeat this beast.", objectives = "" }
WordHunterWoW_QuestEN[50370] = { title = "Deeper into the Woods", description = "We need to go deeper into the forest. The witches are clearly up to something even worse than I'd imagined.\n\nAs much as I have a duty to return to Lady Lucille with Master Ashton, I also have a duty to find out more about this threat to our people, and stop it if I can.\n\nGoing further into the forest is not without risk, but I believe it is one worth taking.", objectives = "" }
WordHunterWoW_QuestEN[50372] = { title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nWe need to find out how the silithid avoided destruction and what effect the blade is having on their hives.\n\nThe crown wants the surviving silithid dissected and studied. \n\nTammy Tinkspinner is conducting the research and is in need of a \"collector.\"", objectives = "" }
WordHunterWoW_QuestEN[50373] = { title = "A Recent Arrival", description = "The situation in Silithus appears to be gaining more attention.\n\nArchmage Khadgar just arrived while you were away. It seems that he is here to speak with you, {name}.\n\nIt appears urgent. I would speak with him as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[50374] = { title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Alliance. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", objectives = "" }
WordHunterWoW_QuestEN[50375] = { title = "Ride With Me", description = "I have hunted many powerful foes, {name}. My pack has defended this island and its people from countless outside threats and foreign invaders.\n\nBut there is a darkness growing in Zandalar. A corruption so deep and relentless that it consumes the minds of the Zandalari.\n\nI cannot hunt intangible darkness, but I can hunt those who wield it against my people.\n\nCome, ride with me and my pack. I smell the foul stench of blood trolls nearby. We will see how well you hunt with the pack.", objectives = "" }
WordHunterWoW_QuestEN[50376] = { title = "Deadliest Cache: Reel Big Fish", description = "Can ye believe the nerve of these scallywags? Questioning the very Coxswain of this here wharf?\n\nBah!\n\nLend me your ear for a moment or three. I've got a tale that'll put brew in your mug and a quiver in your boots!\n\nIt was the biggest, deadliest cache I ever did loot on these seas...", objectives = "" }
WordHunterWoW_QuestEN[50377] = { title = "Strength of the Pack", description = "It's time to prove your worth to the pack, {name}.\n\nThe blood trolls of Nazmir have invaded this land. My people here have suffered greatly.\n\nLead the pack. Find survivors. Make the blood trolls pay for what they've done. Wipe their corruption off this land.\n\nYou will have every opportunity to prove yourself, but remember, we hunt as a pack. You must accept that others have strengths you do not. Allow them to lead when the time is right and the pack will be stronger.", objectives = "" }
WordHunterWoW_QuestEN[50381] = { title = "The Great Hat Robbery", description = "Along this road the merchants ride. Taking dere wares from one place to another and lining them own pockets. \n\nOne Big Mon named Tik'su be the worst of all. He charge arms and legs outright and it even take trolls some time to regrow them parts.\n\nHis biggest pride? His hat. \n\nGo be my messenger, Rich-mon. Scare his burdened beast and knock off Tik'su. Then bring me his hat.", objectives = "" }
WordHunterWoW_QuestEN[50384] = { title = "[DNT] Test Quest", description = "{name}, while you were out being one hell of a {class}, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", objectives = "" }
WordHunterWoW_QuestEN[50385] = { title = "Indefatigable Purpose", description = "Its grip weakens, if only briefly. We must claim this place anew!\n\nFlopping, nightmarish horrors have infested the caves amongst the cove. Take the sacred blessings. Venture forth into the dark and find their altars. \n\nPurge their blasphemous constructions from our lands!", objectives = "" }
WordHunterWoW_QuestEN[50386] = { title = "Flush Them Out", description = "They lurk in the shadows, in the salt-soaked caverns. The dark brine beneath the pure gleam of the surface.\n\nI have seen them. They plague my dreams, their whispers are maddening. They speak of their master, clawing at the barrier...\n\nSearch the cliffs for their warrens. Find what lurks within and obliterate them all.", objectives = "" }
WordHunterWoW_QuestEN[50387] = { title = "Trinkets and Baubles", description = "Beneath the tides, these terrors do not see fit to stay within their warrens.\n\nThey have emerged in the night, stealing away to the villages and indulging in their avarice. They will use the provisions against us, to serve in their rituals. Rituals of summoning and communion with powers too terrible to comprehend. \n\nThe populace is no concern of mine anymore, but I would not see these briny thieves to have their way. Relieve them of their plunder, and let them learn a bitter lesson.", objectives = "" }
WordHunterWoW_QuestEN[50388] = { title = "The Weight of My Ambition", description = "As with the other settlements, I too relied on the services of sailors and watercraft to deliver supplies. They proved very useful in their diligence, and their silence.\n\nPredictably, they drew the attention of enemies, including those below the waves. Their anchor was hexed, dragging them beneath the ocean before they could so much as cry out.\n\nI have seen them, hoisting ethereal sails and singing shanties of the damned. If these waters are to be safe again, they must be silenced again. For good.", objectives = "" }
WordHunterWoW_QuestEN[50389] = { title = "Malign Inspiration", description = "A long time ago, there was a maiden.\n\nA precocious child fond of song, she made it her hobby to shadow my every move. Charming at first.\n\nWalking on the pier's edge, she became entangled within the ropes surrounding a leering idol. At that time a tremor ran through the waves, giving the small push needed to send them both beneath the surface.\n\nI can hear her song still. At first I thought it a passing fancy, music upon the waves. I realize now the voice comes with sinister purpose.\n\nShe must die.", objectives = "" }
WordHunterWoW_QuestEN[50391] = { title = "Deadliest Cache: Gun Fishin'", description = "Hook's got a screw loose in her head, I tell ya. Sharks workin' together on somethin'... phooey!\n\nIt does remind me of one of my favorite tales, though. Have I ever told ya 'bout the time I caught THE single largest, deadliest, most tentacled beast in all o' Azeroth?!\n\nAye, I thought not. It's not a story I'd tell ya sober. It was a day unlike any other...", objectives = "" }
WordHunterWoW_QuestEN[50393] = { title = "A Child of Pa'ku", description = "<The pterrordax egg is warm and trembling. It will hatch soon.>\n\nPerhaps a certain pterrordax loa can help you.", objectives = "" }
WordHunterWoW_QuestEN[50394] = { title = "Your Problem Now", description = "Hm. This egg does not belong to one of my brood, and I have no broodlings that need another sibling.\n\n<Pa'ku might be smiling or snarling. She is showing an awful lot of teeth.>\n\nYou will care for this little one. And you had better hurry.\n\nIt will hatch very soon.\n\nOh, and a little advice. If you want the little one to like you, you had better be the first thing it sees upon hatching.", objectives = "" }
WordHunterWoW_QuestEN[50395] = { title = "The Call of the Skies", description = "<Kua'fon turns his head toward the cliff and chirps eagerly. He spreads his tiny wings and flaps vigorously.>\n\nIt is time to leave the nest.", objectives = "" }
WordHunterWoW_QuestEN[50396] = { title = "A Pterrible Fate", description = "<Kua'fon peers longingly toward the horizon and gives a keening cry.\n\nYou can take the pterrordax from the sky, but not the sky from the pterrordax. It's time to do something.\n\nPerhaps Pa'ku could offer some advice.>", objectives = "" }
WordHunterWoW_QuestEN[50397] = { title = "Aerial Aspirations", description = "<Kua'fon studies you intensely. One single golden eye is trained on you, unwavering.>\n\nSkree.\n\n<He then turns his maw toward the horizon and spreads his wings wide.>\n\nSkree!\n\n<Is it finally time?>", objectives = "" }
WordHunterWoW_QuestEN[50401] = { title = "Fear of Falling", description = "Some young find their wings sooner than others. At least yours had the sense to keep them open.\n\nI would not worry too much about its safety- little ones tend to bounce.\n\nAs for this failure... the young must keep trying, and they must learn not to fear falling. It is now your task to teach it.\n\n<The loa smiles at you, all teeth.>\n\nIf it is reluctant to learn, you might consider bribery.", objectives = "" }
WordHunterWoW_QuestEN[50402] = { title = "SKREEEEE!", description = "<Kua'fon stares at you for a moment, then opens his maw and unleashes a continuous screech.\n\nYou need help.>", objectives = "" }
WordHunterWoW_QuestEN[50412] = { title = "Back to the Nest", description = "<Kua'fon peers up at you trustingly.>\n\nNow would be a good time to take him back to the nest.", objectives = "" }
WordHunterWoW_QuestEN[50417] = { title = "Ruin Has Come", description = "There is a terror beneath the waves. It seeks to destroy my family, my house, and my legacy.\n\nYou must come, claim your destiny and deliver us from the terrors of the deep!\n\nFind our estate to the east, among the isles. We lived opulently in the shadow of the great fortress. We believed the priests would deliver us from the darkness below. Now that darkness has bubbled to the surface, whispering madness in our dreams.\n\nHurry. The air turns the darkest I have seen in my cursed existence.", objectives = "" }
WordHunterWoW_QuestEN[50418] = { title = "Deadliest Cache: Sink and Swim", description = "Mph mph!\n\nMph mph mph mph mph. Mph mph mph.\n\nMph.\n\nMph mph? Mph!", objectives = "" }
WordHunterWoW_QuestEN[50420] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[50432] = { title = "Titanic Innovation", description = "", objectives = "" }
WordHunterWoW_QuestEN[50433] = { title = "Zanchuli Disbanded", description = "I would like to say we are doing well, but we are not.\n\nDe Zanchuli Council is broken. Raal and I are all dat remain who are still loyal to King Rastakhan. You best bring news to your Horde and tell dem what transpired here.\n\nRaal and I will rally what support we can and head for de Zocalo.\n\nAnd hero, thank you for saving my life and my loa.", objectives = "" }
WordHunterWoW_QuestEN[50444] = { title = "Taking the Loa Road", description = "This road not be traveled much anymore. Except by those that serve the blood Loa. They be fools.\n\nI be wantin' my fun from those fools. Go to the spot I be markin' for you and plant this cursed coin. The silly blood trolls be seein' it and give us a laugh when they try to pick it up.\n\nJust be makin' sure that no other creature see you. Or else it be a quick trip back to the arms of Jani.", objectives = "" }
WordHunterWoW_QuestEN[50445] = { title = "Controlling the Situation", description = "I have been observing this macabre army of, wood, flesh, and bone and how the witches and servitors control the lesser creations with charms. I believe I can craft an even more powerful charm - one we can use.\n\nIn the hearts of the servitors are the very strongest charms. They are used to anchor the Ancient Drust into their physical forms. They are precisely what we need.\n\nGood luck. It is doubtful that they will part with them easily.", objectives = "" }
WordHunterWoW_QuestEN[50446] = { title = "Witchrending", description = "A blunderbuss? I'd have to say, I wasn't quite expecting that.\n\nNonetheless, now that we have a weapon, we have an advantage. I think it's time we take the fight directly to the coven.\n\nMarshal Reade informed me that several of their Matrons have been spotted throughout Corlain. Let's show them what happens to an enemy of House Waycrest.", objectives = "" }
WordHunterWoW_QuestEN[50447] = { title = "Remembering the Fallen", description = "<This villager died clutching a brooch with what looks like a family crest. It looks like several villagers didn't survive the coven's occupation of Corlain.\n\nIt might be possible to identify the fallen by the keepsakes they carried. The survivors would likely be grateful to learn the fate of their loved ones.>", objectives = "" }
WordHunterWoW_QuestEN[50449] = { title = "Reeking Refuge", description = "Oh good, maybe you can make sense of this.\n\nI was just carving through a swath of the coven's lackeys when I stumbled across this field. Something here has knocked these guys completely out of commission!\n\nI can't seem to find the source, but maybe you'll have better luck. I'm more used to hitting things than investigating them.", objectives = "" }
WordHunterWoW_QuestEN[50450] = { title = "An Offensive Harvest", description = "So you're takin the fight to the coven with the Waycrest girl, eh?  Ya might just be able to take advantage of their apparent onion aversion.\n\nWhile you're out rootin' in the field, keep an eye out for any onions bulging out of the ground. Those ones should be particularly aromatic, and should cause some fits in the coven's minions if you keep it on ya.\n\nJust try not to take too much, right? I need enough left in the fields to keep the farm safe.", objectives = "" }
WordHunterWoW_QuestEN[50451] = { title = "Eating Through the Defenses", description = "Not sure why and don't rightly care, but for some reason the coven can't come near my onion field. So long as my crop doesn't give out, I can hole up in here as long as it takes.\n\nUnfortunately, those boars got the same idea and now they're eatin' up my harvest! If they keep that up, soon there'll be nothin' keepin' the coven at bay!\n\nIf you can do me a favor and thin them out, I'd be happy to let you take some of these onions with you.", objectives = "" }
WordHunterWoW_QuestEN[50452] = { title = "Potent Protection", description = "Here ya go, I got them onions bundled up nicely for ya.\n\nGive my regards to Miss Waycrest, will ya? Her allies are welcome on my farm anytime.", objectives = "" }
WordHunterWoW_QuestEN[50453] = { title = "Barrier Buster", description = "Oy, {name}! I think I might have a solution te that pesky barrier keepin ye out of Corlain proper! \n\nI took the silver we had left 'ere an' doctored up one o' these cannonballs. The walls surroundin' Corlain are festooned with defensive cannons. Get one pointed at the gate, ye can send this beauty right into the barrier!\n\nYe'll need a hefty pinch of powder te get this thing movin', though - it's a bit on the heavy side. Ye can likely find some in the camp outside the walls.", objectives = "" }
WordHunterWoW_QuestEN[50454] = { title = "A Traitor's Death", description = "It has come to my attention that you intend to assault the camp outside of the walls. If this is so, I have a request.\n\nThough most of the guardsmen who fight against us were turned to the coven against their will, Captain Goodspeed and his brigade of halberdiers gave their souls willingly to the Heartsbane. They are traitors and an affront to the Waycrest Guard.\n\nYou will find Goodspeed and his men stationed at the camp.  I would consider it a personal favor if you would cut them down to the last.", objectives = "" }
WordHunterWoW_QuestEN[50455] = { title = "Leaving the Nest", description = "It looks like the coven hasn't managed to enthrall all of our falcons. I can see some untainted ones still in cages in the training yard.\n\nOur falcons are well trained, and should know to fly to one of our other yards if something happens to their handlers. \n\nIf you can just release them from their cages, they should be able to make it to safety.", objectives = "" }
WordHunterWoW_QuestEN[50456] = { title = "Hexed Hatchlings", description = "I've found where those evil witches have been tainting our falcons! You see those charms? \n\n<Notley motions toward the high perches and roofs nearby.>\n\nThey're using those to infect our flock with their evil magic as they hatch.  I think Winston can get up there to take out the charms, but someone will need to direct him.\n\nI'm not quite healed up enough to take on a whole camp of falconers. Can you help?", objectives = "" }
WordHunterWoW_QuestEN[50457] = { title = "Break On Through", description = "Cannon's ready, boss.\n\nCare to do the honors?", objectives = "" }
WordHunterWoW_QuestEN[50466] = { title = "He's Gone Mad!", description = "Ol' Wildtusk has withstood years of attacks by young hunters that are overeager and underskilled.\n\nNone could take him.\n\nHis wounds have finally done him in. He just won't go down. Find that crazy riverbeast bull, and help him let go of his mortal shell.", objectives = "" }
WordHunterWoW_QuestEN[50476] = { title = "The Warchief Awaits", description = "{name},\n\nThere are important matters I would like to discuss with you, but discretion is of the utmost importance. \n\nMeet me in my chambers in the Undercity where I can assure our privacy has not been compromised. \n\nEnsure that you are not followed; Orgrimmar has become riddled with SI:7 spies. It would seem that that King Anduin and Mathias Shaw are desperate to know what our next move is. How admirable.", objectives = "" }
WordHunterWoW_QuestEN[50481] = { title = "In the Hall of the Drust King", description = "I've been watching a lot of activity going on at the ruins at the base of the massive tree by the lake. What Master Ashton reported is accurate - something important is going on down there. \n\nWe've disrupted their rituals but I worry we might have been too late.\n\nWe need to go over there. If there is anything remaining, we must destroy it.", objectives = "" }
WordHunterWoW_QuestEN[50493] = { title = "Fetching Wrex", description = "When all the commotion started, Ancel's pup ran off. The poor thing was terrified!\n\nA couple farmhands went to look for him, but with all of these monsters terrorizing the farm, I fear the worst!\n\nCan you keep an eye out for Wrex while you're up in the hills? He might have gotten trapped in the honey too.", objectives = "" }
WordHunterWoW_QuestEN[50504] = { title = "Honey Glazed Sam", description = "Think I heard someone shouting down yonder.\n\n{name}, there might be trouble. Let's go!", objectives = "" }
WordHunterWoW_QuestEN[50520] = { title = "Where's Sam?", description = "", objectives = "" }
WordHunterWoW_QuestEN[50530] = { title = "Witch Way Out?", description = "There are other Falconhurst citizens to be freed before they become sacrifices.\n\nFree anyone you come across.\n\nThe key used to free Master Ashton should still work. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[50531] = { title = "Under Their Noses", description = "Figures they wouldn't just put the destination on the crates for us. \n\nNothing's ever easy, is it?\n\nIf the weapons aren't moving on Cagney's ferry, they must be passing through Bridgeport, the shipping hub just up the road.\n\nBridgeport is protected by a garrison of Proudmoore marines. The Ashvane Company has a lot of nerve moving illegal weapons right under their noses.\n\nCome on, let's check it out.", objectives = "" }
WordHunterWoW_QuestEN[50533] = { title = "Stick It To 'Em!", description = "We have been able to stop the Grand Rite but the witches will try again unless we act.\n\nWe have to destroy them. Utterly.\n\n<Cleardawn smiles.>\n\nHow kind of them to give us the means.\n\nYou've helped us get this far, {name}. You control the Demolisher. Destroy everything you see! \n\nOnce we've finished we can signal for help out of here!", objectives = "" }
WordHunterWoW_QuestEN[50534] = { title = "Wendigo Away", description = "If the unearthly howls coming from the Highlands at night are any indication, the wendigos must have some sort of leader or alpha.\n\nI tell you, it's the sort of sound that could only come from some sort of massive, hulking, flesh-eating abomination.\n\nDefinitely something that could tear us limb from limb, and munch on our frail bones, all without breaking a sweat. How exhilarating!\n\nI'm sure it'll be no problem for us to handle though.", objectives = "" }
WordHunterWoW_QuestEN[50535] = { title = "Power of the Overseer", description = "Overseer Nerzet is very cruel, and oh so easy to provoke!  \n\nIt makes her very angry when things go missing, or move, or change... my crew and I are having a yip of a time! That you got this device to work was certainly a bonus!\n\nIt will be much easier for us to finish up what we need to do here, with her out of the way. \n\nUm, and maybe go ahead and grab that neat power rock she carries. It could come in handy.", objectives = "" }
WordHunterWoW_QuestEN[50536] = { title = "Magic Decoder Device", description = "We retrieved this device from the sethrak in the ruins to the east, but have not been able to use it.\n\nWhen you approached, it started to glow. Something about you...\n\n<Maaz pauses and eyes the stone on your neck.>\n\n...or on you... is waking it up!\n\nPlease, {class}, use the scepter and examine the statues of the Keepers, in the central courtyard of the ruins. Something there got their overseer very excited.", objectives = "" }
WordHunterWoW_QuestEN[50538] = { title = "The Missing Handler", description = "I just received word from Warbeast Kraal dat one of their handlers is missing.\n\nDis is not usually a problem, but dey are expecting a large hatching dis year. Dey will need all de hands dey can get!\n\nGo on and see if you can find de handler, name of Bazo or something, and tell him to get back to de Kraal.", objectives = "" }
WordHunterWoW_QuestEN[50539] = { title = "The Secrets of Zul'Ahjin", description = "You're not the only one who came to Zul'Ahjin looking for answers. The place is crawling with looters and assassins, all searching for something... \n\nSo far, they've come up empty handed, but that's because they don't know where to look.\n\nI do. \n\nInvestigate the statue at the center of the ruins. It is the key to uncovering the city's ancient secrets.", objectives = "" }
WordHunterWoW_QuestEN[50542] = { title = "An Explosive Opportunity", description = "You there!\n\nDo I have the most AMAZING opportunity for you? A gnome named Wulferd Fizzbracket is on the eve of a breakthrough and could use an intrepid business partner that's on the brawnier side. Such as a {class} like yourself.\n\nJust follow the road east until you reach Fizzsprings Resort, the most fantastical wonder of nature. Wulferd is the type that stands out from the crowd.", objectives = "" }
WordHunterWoW_QuestEN[50544] = { title = "The Hunters of Kennings Lodge", description = "HELP WANTED!\n\nAs we turn into the busy season, Kennings Lodge is looking for recreational hunters to assist with fulfilling the ever growing list of orders from Boralus. These are short term positions which will be paid relative to performance. \n\nKennings Lodge can be found by following the south road past the mining yard. Report to Alanna Holton on arrival.", objectives = "" }
WordHunterWoW_QuestEN[50550] = { title = "The Fall of Emperor Korthek", description = "Korthek finally approaches.\n\nIt's been many years since I've faced him in battle. When he first rose to power, I failed my people. I will not falter again.\n\nI am prepared to do what must be done. What I should have done long ago.\n\nWe must kill Korthek and take his key to prevent him, Jakra'zet, or anyone else from ever resurrecting Mythrax.\n\nWhen you are prepared, we will face him together.", objectives = "" }
WordHunterWoW_QuestEN[50551] = { title = "Temple of Sethraliss: Avatar of the Loa", description = "We cannot let Mythrax bring his destruction upon this world once more. \n\nWe need our loa now more than ever, but she has yet to return to us.\n\nThe time of her rebirth has passed. Someone, or something, must be preventing her awakening.\n\nEnter her resting place and see what you can uncover.", objectives = "" }
WordHunterWoW_QuestEN[50553] = { title = "Back to the Lab", description = "Our work here is done!\n\nWell, at least until another one of my humble experiments goes horribly awry, rapidly spiraling out of control into a chain reaction of catastrophic failures.\n\nBut, let's worry about that another time, {name}.\n\nI'll meet you back at my lab!", objectives = "" }
WordHunterWoW_QuestEN[50561] = { title = "Sulthis' Stone", description = "<The ancient reliquary contains a single stone, humming with magic. Perhaps Serrik will know what it is?>", objectives = "" }
WordHunterWoW_QuestEN[50573] = { title = "Message from the Management", description = "<This letter from Priscilla Ashvane to her employees appears to be posted all over the foundry.\n\nIt sounds like Cagney's information was accurate, Ashvane is working their people around the clock.\n\nPriscilla mentions a Forgemaster Farthing and a Taskmaster Williams. They may have more information about her plans.>", objectives = "" }
WordHunterWoW_QuestEN[50583] = { title = "To the Other Side", description = "It looks like the coven is using Corlain as a base of operations. There's no way we'll be able to cut through this many of them without the rest of the Inquisitors.\n\nThey must still be stuck behind the wall. \n\n{class}, there are three smaller footmen gates along the walls into Corlain. See if you can get them open so our allies can make their way through.", objectives = "" }
WordHunterWoW_QuestEN[50584] = { title = "Ruinous Rituals", description = "Take a look in the city square, {class}.\n\n<Marshal Reade gestures toward a ritual being performed by some disciples in the distance.>\n\nIt appears the coven has gone beyond dark constructs, and are now conjuring creatures of nightmare with their rituals. Let us not wait to see what these monsters are capable of. We should put an end to them right here.\n\nFortunately, the disciples seem too focused on their spell to notice us. Maybe you can use that to your advantage.", objectives = "" }
WordHunterWoW_QuestEN[50585] = { title = "Hexecutioner", description = "It would appear that this is where the coven is training their new acolytes. Our efforts may be for naught if they continue to expand their numbers.\n\nI cannot leave Lucille's side in this place, but you have already shown yourself a formidable combatant. \n\nCut them down.", objectives = "" }
WordHunterWoW_QuestEN[50586] = { title = "The Fall of Corlain", description = "<This discarded journal looks like it belonged to one of the residents of upper Corlain. Within it details some early signs of the Heartsbane's appearance in Corlain.\n\nIf you can find more writings like this, you might be able to piece together the events that led to Corlain's current state.>", objectives = "" }
WordHunterWoW_QuestEN[50588] = { title = "Storming the Manor", description = "Now is our chance. Waycrest Manor is just up that hill, and hopefully inside we'll find my mother and father. \n\nIf we also manage to find the \"Mother\" that's leading this horrible coven, then we will make her regret the day she ever set foot in Drustvar.\n\nAre you with me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[50593] = { title = "A Bloody Mess", description = "<The vial is filled with a viscous, bubbling substance. It bears a striking resemblance to the animated horrors around you.\n\nIt struggles against the container, as if trying to escape. Pike would surely be interested in more samples.>", objectives = "" }
WordHunterWoW_QuestEN[50594] = { title = "Beneath the Veil", description = "We must board the Abyssal Melody and save the myriad souls in her decks before they too disappear into the Shrine. We will not be able to enter so long as the barrier surrounding it stands.\n\nThe tidesages are using forbidden magic to summon extensions of their will. It is these grasps that maintain the barrier.\n\nTake my beacon and mark each grasp. I will rain vengeance down upon them from here.", objectives = "" }
WordHunterWoW_QuestEN[50595] = { title = "No Quarter", description = "We arrived just in time. These abominations have already taken control of the docks; we're all that's left to keep them at bay!\n\nYou need to cull their numbers before we're overwhelmed. We don't exactly have an army here!", objectives = "" }
WordHunterWoW_QuestEN[50596] = { title = "Exterminate the Vermin", description = "On top of the fury of the overseer, and this \"key\" not being here, we have a pest problem.\n\nSneaky little vulperan thieves keep ransacking our site. We have taken some prisoner.\n\nWe have them around the upper level of the dig site, working off their misdeeds. However, I believe a more permanent solution would be preferred. \n\nPlease, oh mighty cobra, give us the honor of getting rid of our prisoners with your most potent venom!", objectives = "" }
WordHunterWoW_QuestEN[50608] = { title = "Forbidden Rites", description = "These k'thir have been hiding among us, sowing the seeds of their dark masters with us none the wiser.\n\nWith the barrier around the Abyssal Melody lowered I can peer within; its bowels toil with my own people giving themselves to the shadow!\n\nTake my tidal kris; its blade is now coated in purified tideblood. Put an end to these fiends and their foul rituals.", objectives = "" }
WordHunterWoW_QuestEN[50609] = { title = "From the Maw of Madness", description = "Sam is still out there somewhere. We can't just leave him to die!\n\nIf he wasn't in the assembly yard, he must be on that ship. You have to find him!", objectives = "" }
WordHunterWoW_QuestEN[50610] = { title = "Gathering Storm", description = "This depravity goes against every oath we take as tidesages. To protect our people... to guide and sustain them... to make our ships strong.\n\nThis is nothing but darkness. It must all be destroyed.\n\nBoard the Abyssal Melody and place these focusing rods at any critical points you find. I will prepare the ritual.", objectives = "" }
WordHunterWoW_QuestEN[50611] = { title = "Storm's Vengeance", description = "I know not what horrors await us ahead, but the Abyssal Melody must never follow its sister into the Shrine of the Storm.\n\nWe will deny these monsters all that they have wrought here by burning it with the very magic they seek to corrupt.\n\nThe ritual is ready, but requires a conduit to stabilize. If you are willing, I would have you guide my magic.", objectives = "" }
WordHunterWoW_QuestEN[50612] = { title = "A House Divided", description = "Not all of House Stormsong have followed my Lord down this dark path. They know not - I knew not - the truth of his depravity.\n\nSagehold looms above us. It is where all tidesages study to wield the sea's power.\n\nWe will build upon the Storm's Wake and make my shattered home whole once more. We will save all who are willing. \n\nThe rest will perish.", objectives = "" }
WordHunterWoW_QuestEN[50614] = { title = "Freedom for the Sea", description = "The naga along this coast appear to be trying to push the shoreline up the hill here. We've been able to keep them back at the beach so far, but they've been binding more elementals than we can keep up with.\n\nWithout a tidesage, we have no way to free the elementals from their bindings, but we cannot allow them to push forward anymore. The spirit of the sea should not be contained by anything. Slay them, and let them return to the ocean.", objectives = "" }
WordHunterWoW_QuestEN[50616] = { title = "A Bit of a Bind", description = "The naga sorceress leading this excursion seems to be in the process of binding a larger elemental. If she succeeds, we will no doubt lose our foothold here.\n\nStrike out at her, perhaps you can catch her off guard and interrupt the ritual. Remove the head from these snakes.", objectives = "" }
WordHunterWoW_QuestEN[50617] = { title = "Atul'Aman", description = "Jakra'zet and his troops attacked while we were away. \n\nSerrik fought well, but it wasn't enough. The keys are gone, and it's only a matter of time before the barrier is broken.\n\nYour friends have already given chase. \n\nJakra'zet must not be allowed to resurrect Mythrax the Unraveler. He must be stopped before it's too late!\n\nWe don't have much time. \n\nMeet me at Atul'Aman! We must catch up with Kaja and Rakera and stop the ritual!", objectives = "" }
WordHunterWoW_QuestEN[50621] = { title = "Caught in the Net", description = "When the naga force first arrived, there were a handful of the local fishermen out on boats. One of our scouts reports that most of them have been captured and are currently being kept in cages around the beach.\n\nFree any of them you happen to find and point them back here. We'll get them armed and remind the naga that you don't mess with sailors!", objectives = "" }
WordHunterWoW_QuestEN[50622] = { title = "Deal's Off", description = "There's one more farm left, far to the west. They're real close to the kraul.\n\nDeal works the land by herself. If anyone got hit bad, it'd be her. It's just past the worst part of the collapse, so keep an eye out for the quilboar.", objectives = "" }
WordHunterWoW_QuestEN[50632] = { title = "Battlefield Scavenging", description = "The battle rages on, but our inventory suffers.\n\nScavenge the camps for supplies. I'll make use of what you find.", objectives = "" }
WordHunterWoW_QuestEN[50635] = { title = "The Shifting Tides", description = "I'm no tidesage, but even I can tell that whatever you have there is probably not a good sign for the bastion. \n\nThere's one of those Tortollans, Rikal, who's been helping us figure out a solution to whatever the naga are planning in front of the levee. He'd probably like to see this.", objectives = "" }
WordHunterWoW_QuestEN[50639] = { title = "Waycrest Manor: The Fallen Mother", description = "This is all a lot to process...\n\nThe Marshal... gone? My mother... the leader of the coven? It's just too much...\n\n...but we have come too far to turn back now. It is clear that my mother and father, as I knew them, are gone.  It is time we cleansed the taint from this land.\n\nWe must take the inquisitors and find them in Waycrest Manor. We will end this, once and for all.", objectives = "" }
WordHunterWoW_QuestEN[50640] = { title = "A Question of Quillpower", description = "I can't believe you managed to kill that thing. You're quite impressive, you know that?\n\nEither way, we should be getting back to Roz with our report. We're stuck in the middle of the kraul, surrounded by angry quilboar. But I have a plan!\n\nSome of the boars seem reasonable enough. I gave them a bit of my rations and they've been following me around. I bet we can use them to hitch a ride out of this place. You in?", objectives = "" }
WordHunterWoW_QuestEN[50641] = { title = "Break Their Ranks", description = "This temple is our last bastion against the Faithless. We need every able fighter to defend its walls. \n\nIf you're offering to help, we won't turn you away. \n\nHead into battle and do what you can to break their ranks!", objectives = "" }
WordHunterWoW_QuestEN[50642] = { title = "The Warchief Commands", description = "Silithus. That has been the name of the game... or rather, that is what I wanted the Alliance to believe. \n\nMake no mistake, Azerite is just as powerful as it is rumored to be but I have bigger plans in mind.\n\nHigh Overlord Saurfang is leading an army towards Silithus. By now, he should be in the Northern Barrens. I want you to intercept him and notify him that the preparations are complete.\n\nPreparations for what, you ask? Why, we are going to capture the World Tree.", objectives = "" }
WordHunterWoW_QuestEN[50644] = { title = "Facing the Invaders", description = "While we try to figure out what to do with those channelers, we'll have to take shots where we can get them.\n\nOur men could use some assistance retaking parts of the lower walls. Kill some naga for me, would you?", objectives = "" }
WordHunterWoW_QuestEN[50645] = { title = "Eeling in a Big One", description = "If you are up to it, I have an idea to give the naga an amusing surprise.\n\n<Rikal slowly pulls out a scroll and waves it in your face.>\n\nI need some teeth from marine predators to cast the spell though. Luckily, the naga brought some disgusting eels with them. Go gather their fangs, and bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[50646] = { title = "A Quick Diversion", description = "I have halted our march until I received word that we were ready to divert.\n\nWhat comes next will be a coordinated, synchronized attack on key outposts in Ashenvale. If we act quickly, we will destroy the kaldorei's defenses and clear a path all the way to Darkshore. \n\nStormwind will surely send reinforcements to stop us. We have to conquer Teldrassil before they arrive.\n\nI will divert the troops. Meet with our operative, Lorash, outside Astranaar for further instruction.", objectives = "" }
WordHunterWoW_QuestEN[50647] = { title = "Everybody Has a Price", description = "Hundreds of rogues have already attacked kaldorei outposts in Ashenvale. On my signal, they will begin the next phase of this war: sowing chaos.\n\nMy colleague died not far from here, {name}, so I could use your help. If we stay out of sight, the town won't even know it's under attack before we have all of its guards down.\n\nI have a poison that will kill them quickly and silently. If you signal to me which targets are safe to attack without being noticed, I will put them down.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[50649] = { title = "Filching from Thieves", description = "The naga oft take what they want with little care for who they are taking it from. Perhaps we should do the same for them.\n\nThe sorceresses use powerful beacons to assist with their spellcasting. I could use these relics to strengthen my own ritual.", objectives = "" }
WordHunterWoW_QuestEN[50653] = { title = "Reclaiming our Defenses", description = "We were holding off the naga up until the latest attack. A few of our forces are still out there.\n\nThe tidemaidens seem to be slowly torturing them to death. If you could save as many as you can find, we'd be one step closer to gaining the upper ground again.", objectives = "" }
WordHunterWoW_QuestEN[50656] = { title = "Risky Rescue", description = "The Faithless incursion is just up ahead. \n\nWe tried to get ahead of the siege by attacking their camp in the dead of night, but they knew we were coming. \n\nOur troops were quickly overwhelmed. \n\nWe called for a retreat, but only a few of us made it out. The fate of those that didn't is unknown...\n\nWe don't have the numbers to attempt a rescue ourselves. We can't afford to lose any more fighters. \n\nYou're their only hope.", objectives = "" }
WordHunterWoW_QuestEN[50668] = { title = "Battle for Azeroth: Tides of War", description = "Champion, the Horde is now at open war with the Alliance.\n\nOur success in this conflict may depend on your skills.\n\nI require your immediate presence in Orgrimmar for a mission of the utmost urgency. Do not keep me waiting.", objectives = "" }
WordHunterWoW_QuestEN[50672] = { title = "Any Ammo Will Do", description = "I'll have some men move some cannons down to the sea wall in preparation of whatever ritual is going on down in that delta.\n\nWe could use some extra ammo before we spread ourselves too thin though. Luckily, those naga harpoons work well enough with our mortars. Take down those lances and bring back any harpoons that you find.", objectives = "" }
WordHunterWoW_QuestEN[50674] = { title = "Two-Faced Pirate Scum", description = "We've been holding the Irontide off for days, but now they've brought in an ettin for reinforcements. We can't let him attack the town. \n\nA few of my best men just went up the hill to try and kill him. You look pretty capable, they could sure use your help?", objectives = "" }
WordHunterWoW_QuestEN[50675] = { title = "Treasure Hunting", description = "The workers are digging day and night out there to find the lost treasure. You'd get an equal share like everyone else, if ya wanna help out.\n\nTalk to Nedly about joining up.", objectives = "" }
WordHunterWoW_QuestEN[50679] = { title = "Piercing the Shield", description = "I've been talking with Rikal, and the tortollan says that our problem in the delta can probably be solved by turning the naga's magic back on them.\n\nA few of the sorceresses on the south coast have a channeling wand that we may be able to use to break the head priestesses' ritual channeling. Find one, and bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[50690] = { title = "A Flickering of Hope", description = "This pervasive darkness continues to cast shadows over our fields, hindering our harvests.\n\nCheck with Keyrra Flamestonge and see if you can help restore some order.", objectives = "" }
WordHunterWoW_QuestEN[50691] = { title = "Not On Our Payroll", description = "The workers are complaining about elementals coming into the area while they're digging for treasure.  \n\nJust this morning, I had two people crushed to death! It's slowing down the hunt! \n\nYou can earn your share by getting rid of those elementals!", objectives = "" }
WordHunterWoW_QuestEN[50694] = { title = "A Bloody Mess", description = "My order blesses every Kul Tiran ship within the halls of the Shrine of the Storm. Our blessings make our ships the strongest in all of Azeroth; the fleet of legend.\n\nThe ritual requires a substance known as tideblood. It is a viscous, powerful substance dredged from the depths of the sea and infused into the very hull of each ship.\n\nSomething has caused the tideblood here to become animate. Studying it may help us better understand our enemy.", objectives = "" }
WordHunterWoW_QuestEN[50696] = { title = "Fun With Magnets", description = "My last time in Tol Barad I had to leave in a big hurry, but I grabbed a few gadgets on the way out.  \n\nThis device is one of my favorites, so don't break it! It'll suck the treasure right out of the mud. It may make you tingle some, that's just the radiation.\n\nFind lost coins using the metal collector near the signs I've placed.", objectives = "" }
WordHunterWoW_QuestEN[50697] = { title = "Bomb Beats Rock", description = "I stole an old treasure map off an Irontide pirate. The map marks several caves on it with circles. \n\nThe caves are blocked by boulders, but now that you're here, we're going to open them up.\n\nYou get to do all the dangerous stuff, plant explosives, kill things, and cave exploring.  I'll supervise.", objectives = "" }
WordHunterWoW_QuestEN[50698] = { title = "Problem Solving with Gunpowder", description = "Fort walls only go so far when it comes to defense. We've got cannons in position to fire if the naga get too close, but we need some fortifications further out.\n\nThere should be a few good areas to set up some traps further down the beach. Those naga will never know what hit them!", objectives = "" }
WordHunterWoW_QuestEN[50699] = { title = "Worker's Rights", description = "Hey, you! You lookin' for work?\n\nI ain't got a job for ya, but I can tell ya to stay away from Algerson Lumber!\n\nAlgerson'll promise ya some solid labor work and decent pay, but it's a lie I tell ya!\n\nThe conditions are terrible, we're gettin' attacked, and Algerson ain't even battin' an eye!\n\nHe don't care 'bout us little people. I'd stay away if I were you!", objectives = "" }
WordHunterWoW_QuestEN[50700] = { title = "Drust in Time", description = "A few days ago, a band of Alliance researchers that called themselves the \"Explorers' League\" took a contingent of Kul Tiran soldiers to the old Drust ruins down the road.\n\nWe haven't really heard from them since, and I'm growing a bit concerned. I can't leave my post, so can you check up on the team?", objectives = "" }
WordHunterWoW_QuestEN[50702] = { title = "Defeat Jakra'zet", description = "Jakra'zet is summoning Mythrax the Unraveler!\n\nWe cannot allow the ritual to continue. Jakra'zet must be stopped before it's too late!\n\nLead the way, {name}. We'll be right behind you.\n\nLet's go!", objectives = "" }
WordHunterWoW_QuestEN[50703] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "" }
WordHunterWoW_QuestEN[50704] = { title = "Anchors Aweigh Too Much", description = "I got a little deal on the side, selling used ship parts to Addington Shipyards.\n\nWhile you're out looking for the treasure, see what sort of useful parts you can salvage from the mud: anchors, cannons, whatever!\n\nWe'll sell them to Addington and cut you in for a share of the profits.", objectives = "" }
WordHunterWoW_QuestEN[50705] = { title = "A Snake with Three Heads", description = "Now that all of the preparation has been done, it's time to tackle the main threat.\n\nYou can use the channeling rod you just found in conjunction with this scroll I got from Rikal to break the shields around the naga leaders in the delta.\n\nHurry! Stop them before they finish their summoning!", objectives = "" }
WordHunterWoW_QuestEN[50706] = { title = "Clearing the Delta", description = "The greatest of the Zeth'jir offensive sits within the delta as we speak, waiting for the summoning ritual to be finished. If we can clear out a number of them, we'll finally have the upper hand.\n\nGet down there and cause as much chaos as you can!", objectives = "" }
WordHunterWoW_QuestEN[50709] = { title = "Resourceful Recon", description = "We received word an Alliance surveyin' party was spotted leavin' Drywhisker Mine in a hurry. Now I don't know what they was up to, but I'll bet ya they didn't gather all their belongings before headin' out.\n\nHurry on over and see what you can find.\n\nI'll talk it over with Pixy and see what materials we can shore up in case ya stumble upon something particularly interesting.", objectives = "" }
WordHunterWoW_QuestEN[50733] = { title = "A New Dawn", description = "House Stormsong may be lost, but this valley still holds so much hope. \n\nSam knew that from the beginning.\n\nWe have to continue to help the Storm's Wake in any way we can. There are still remnants of the fallen house everywhere, and whoever turned them to this darkness is out there as well.\n\nCyrus and the others will want to hear about everything that happened. We should tell them together.", objectives = "" }
WordHunterWoW_QuestEN[50738] = { title = "A Timely Arrival", description = "My end of the bargain is done, {race}. \n\nI am going to check on the other outposts to make sure none of my brothers and sisters are in trouble. Meet with the Warchief and inform her that Astranaar has been secured. If everything has gone according to plan, she should be well on her way.\n\nOh, and try not to hog all the glory, yeah? \n\n<Lorash smirks at you>.", objectives = "" }
WordHunterWoW_QuestEN[50739] = { title = "Missing Business", description = "Poor little Coda has been in quite the tizzy since his friends vanished. \n\nI found him here, out cold, after a sting from one of those awful wasps. Just a tiny bit of our sandstinger remedy got Coda right up, though!\n\nTake some with you, and keep an eye out for other little ones out there.", objectives = "" }
WordHunterWoW_QuestEN[50740] = { title = "Zoram'gar Outpost", description = "Saurfang shall establish our troops here, now that Astranaar is ours. I shall continue my hunt for the only creature that can stop our march to victory: Malfurion Stormrage.\n\nOur next order of business will be to establish a foothold at the base of Darkshore. Commander Grimfang of the Zoram'gar Outpost should be able to accommodate an incoming army.\n\nInform him of our arrival and ensure the necessary preparations are made.", objectives = "" }
WordHunterWoW_QuestEN[50741] = { title = "Don't Turtle", description = "There's a Tortollan who's trying to get our treasure! He's over on the west side of town.  He's nosey and he may have found something!\n\nTalk to Moxie. Come up with a plan to get rid of him.", objectives = "" }
WordHunterWoW_QuestEN[50742] = { title = "All Laid Out For Us", description = "<This is all the treasure Calico McGee's found so far. Packed up and ready to move out. More like all laid out for you to take!\n\nYou'll need a few extra hands to carry this much loot. There should be some Treasure Hunters from Deadwash around.\n\nAsk Big Find Balor, Toothless Eddard, and Chopper Darry to help.>", objectives = "" }
WordHunterWoW_QuestEN[50743] = { title = "The Immediate Problem", description = "I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction.\n\nWe need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.", objectives = "" }
WordHunterWoW_QuestEN[50745] = { title = "Infiltrating the Empire", description = "The heart of the Faithless empire rests just beyond this ridge. We will need to move swiftly and quietly to avoid detection once inside.\n\nThankfully, my former dwelling is nearby. I know a passage that should allow us to advance into the fortress with minimal resistance. When you are ready, speak with me and I will show you the way.\n\n<Vorrik looks around suspiciously.>\n\nI expected the Faithless to patrol this area... Keep your eyes open for anything suspicious along the path.", objectives = "" }
WordHunterWoW_QuestEN[50746] = { title = "Crater Conquered", description = "I can take it from here, {name}. I'll rally these vulpera and march through the trenches creating chaos. Korthek and his armies will be forced to deal with us!\n\nIf you and Vorrik are going to make a move, you should do it now.", objectives = "" }
WordHunterWoW_QuestEN[50748] = { title = "Don't Drop It... Yet", description = "The Faithless are training pterrordaxes as mounts so that they can rain down death from the skies.\n\nTheir skycallers have developed a means of storing volatile lightning magic into fragile crystals. Lightning bombs, in the simplest sense. The magic behind it is quite brilliant, really.\n\nThe bombs will be exceptionally useful if we can secure the aid of Rakjan, the powerful and fierce pterrordax at the top of this mountain.\n\nAcquire as many as you can carry, while I will do my best to recruit Rakjan.", objectives = "" }
WordHunterWoW_QuestEN[50749] = { title = "Free Ride", description = "One thing I've learned during my time in Vol'dun is to not stay in one place for too long. And doubly so when the Faithless are involved.\n\nWe've done our damage here. Let's move before we get caught.\n\nI procured a mount to take us back to Meerah and the others in Vorrik's Sanctum quickly. Don't worry, this Faithless won't be needing it anymore.", objectives = "" }
WordHunterWoW_QuestEN[50750] = { title = "Infuriating the Emperor", description = "It seems I underestimated Korthek's cowardice. I expected him to be behind the barrier, ready to ambush us. Yet, still he hides.\n\nThat allows us a few moments to prepare. We musn't waste them.\n\nWhile I siphon power off of these immense crystals, you must thin the numbers of the Faithless here. I will grant you a powerful boon to speed you in your task.\n\nWhen Korthek arrives, he will require our full attention.", objectives = "" }
WordHunterWoW_QuestEN[50751] = { title = "Sanctuary Under Siege", description = "I fear that Emperor Korthek was not lying when he boasted of his foolish plan.\n\nIf General Jakra'zet attacked the Sanctuary of the Devoted while we were away, there is a good chance that he now has everything needed to resurrect Mythrax.\n\nWe must hurry to the Sanctuary and stop Jakra'zet. Mythrax must not be reborn!", objectives = "" }
WordHunterWoW_QuestEN[50752] = { title = "Relics of Sethraliss", description = "It may surprise you to learn that the Faithless hoard ancient relics of Sethraliss. I assure you that they do not do so out of reverence or respect, as is proper.\n\nKorthek's brood is driven only by greed and an insatiable lust for power. They rip whatever magic they can from the relics, even if it means destroying them in the process.\n\nRescue the ancient artifacts of Sethraliss in the Sacred Sands nearby. We will honor and preserve them in the Sanctuary of the Devoted.", objectives = "" }
WordHunterWoW_QuestEN[50753] = { title = "Earl-E Bot Gets the Worm", description = "It could take you days to get that much meat, and I don't want to wait around. So, we'll use a Bot as bait!  \n\nYou send EARL-E towards any disturbances you see in the mud. He'll make enough noise to scare any worms out.  \n\nThen kill the worms, get the meat. I'll watch from here.", objectives = "" }
WordHunterWoW_QuestEN[50754] = { title = "To Have Loved and Lost", description = "I have a favor to ask you of a... personal nature.\n\nWhitegrove Chapel lies to the north, just past the town of Corlain. Someone... important to me rests in the graveyard on its grounds.\n\nI've been unable to visit his grave for some time, and I would like to pay my respects. If you come upon Whitegrove Chapel, could you lay these flowers next to his headstone?\n\nJust look for the most recent grave there...", objectives = "" }
WordHunterWoW_QuestEN[50755] = { title = "A Meal for Birds", description = "I don't know why I agreed to this. We weren't supposed to be scavenging. \n\nKiro gave me specific instructions to head to the basin and feed the buzzards.\n\nI can't go back to camp until they eat, but I'm not heading into that basin while the sethrak are still swarming. \n\nHave you ever fed a buzzard? It's easy, I promise. \n\nYou kill it, they eat it. That simple.", objectives = "" }
WordHunterWoW_QuestEN[50757] = { title = "Untame Slaughter", description = "The Faithless rely on their krolusks for everything. They are mounts, battle companions, beasts of burden, and often even food to fuel the sethrak empire.\n\nIf we can disrupt their krolusks, we'll disrupt their whole empire. One broken wheel stops the caravan, eh?\n\nTake out as many of their krolusk tamers as you can. That'll have a longer impact than just killing the krolusks.", objectives = "" }
WordHunterWoW_QuestEN[50758] = { title = "Painful Memories", description = "A terrible thing happened in this place, and it has doomed me to an eternity of walking these grounds.\n\nAll I remember is that Lucille and I were to be wed, but instead I met my end.\n\nIf you have an ounce of sympathy in your heart, then I beg you to help me. Find out what happened that night, so I might leave here.\n\nI know my strongest memories are tied to the ring I bore for Lucy that day. Find it among my bones, and maybe it will lead you to the answer.", objectives = "" }
WordHunterWoW_QuestEN[50759] = { title = "Running Late", description = "I beg your pardon, but I am a little concerned at Lord Waycrest's tardiness.\n\nI'd hate to be a bother, but would you mind checking on him? The ceremony awaits his presence.\n\nYou can find him in the bride's room, at the top of the tower.", objectives = "" }
WordHunterWoW_QuestEN[50760] = { title = "From This Day Forward", description = "Lord Waycrest is on his way? Excellent!\n\nYou have my thanks, sir. Please, take a seat.", objectives = "" }
WordHunterWoW_QuestEN[50761] = { title = "Blood in the Chapel", description = "Sir, you have helped me before and I beseech you to do so again.\n\nMy guards are clearly outnumbered by these brigands. I must stay here to protect Lucille, so I will need you to assist in protecting the guests.\n\nAre you able?", objectives = "" }
WordHunterWoW_QuestEN[50762] = { title = "The Lady's Fate", description = "Meredith never joined the ceremony. She might be in trouble!\n\nLucy is in shock, and I cannot leave her here. You must go in my stead to the tower, and ensure the safety of your Lady.\n\nDo this for me, and you will be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[50763] = { title = "One Last Request", description = "I can feel my bonds to this place slipping, and I have you to thank.\n\nI would like to ask one more favor of you though. Please bring the ring you found to Lucille. It was meant for her to hold, not my dusty bones.\n\nAnd {class}, do not tell her what has transpired here. She has enough tragedy weighing down her heart. I do not wish to add to it.", objectives = "" }
WordHunterWoW_QuestEN[50764] = { title = "Redemptive Refurbishment", description = "Looks like our boys took down a few of those pesky flying machines.\n\nIf ya stumble across any spare parts while you're out I can continue my work on our secret weapon.", objectives = "" }
WordHunterWoW_QuestEN[50769] = { title = "The Stormwind Extraction", description = "My lady is shrewd indeed. If we are to infiltrate Stormwind City, we will need the very best the Horde has to offer, and yet a team so small as to be able to infiltrate the heart of Alliance territory unseen.\n\n<Nathanos peers at the gathered group, stroking his chin.>\n\nYes, I see.\n\nThe path ahead is clear. Speak to me when you are ready to undertake the Warchief's mission, {name}.", objectives = "" }
WordHunterWoW_QuestEN[50770] = { title = "Effective Antivenom", description = "The salve is ready. \n\nI work fast. Hopefully faster than the scorpid poison. \n\nTake this antivenom to your friend and see that he swallows every last drop. \n\nYou should know within moments if it's been effective.", objectives = "" }
WordHunterWoW_QuestEN[50771] = { title = "Calldown: Cleaner", description = "With these dust blowin' siro-ma-whosits all over this beach front, it's a pain to get our cleaners out onto the nodes.\n\nSome of the crew wanted to check somewhere else, but no way we're leaving without those rocks for Gallywix. \n\nBetween you and me, {class}, we're gonna be gettin' some serious hazard pay for this gig.", objectives = "" }
WordHunterWoW_QuestEN[50772] = { title = "On The Prowl", description = "Do you see all of the wisps about? I have seen this once before, when the demon Archimonde was felled by the sting of hundreds - no - thousands of wisps.\n\nThis can mean only one thing. Malfurion is beckoning the aid of his ancestors.\n\nThe Warchief has already taken a scouting party ahead to Darkshore to intercept him. Please, {name}. Find the Warchief and see if she has yet caught her prey. \n\nWe have secured all of Ashenvale, but we must keep the pressure on.", objectives = "" }
WordHunterWoW_QuestEN[50773] = { title = "You're a Shark", description = "Have you ever been bitten by a shark? I have, numerous times. It stings.\n\nMurlocs don't usually survive shark attacks.\n\nThe ritual I had in mind is ready to cast. Let me know when you're prepared.", objectives = "" }
WordHunterWoW_QuestEN[50774] = { title = "No Bot Left Behind", description = "You left Earl-E behind, and a giant worm ate him! He's got sentimental, uh... monetary value. \n\nWe don't leave any bots behind!\n\nKill that worm and get Earl-E back.", objectives = "" }
WordHunterWoW_QuestEN[50775] = { title = "Get Us Some Beach", description = "These guys are running out of \"ammo\" faster than we can replace it! \n\nI tells 'em, we're on a beach, you're in a sandblaster, suck it up!\n\nThey says it's against the cleaner driver rules for their local chapter.\n\nI'm not buyin' it.\n\nGrab us some more sand. Them sand monsters have gotta be full of the stuff!\n\nWe'll make it worth your time.", objectives = "" }
WordHunterWoW_QuestEN[50777] = { title = "The Storm Awakens", description = "I must watch over Samuel for now. I fear for the darkness assaulting his mind.\n\nThe fallen men and women around us were defectors from the house. There will be more like them within Sagehold. \n\nFind them, and tell them 'the storm awakens'. Knowledge of our cause has spread; we need to bring all we can to our side.", objectives = "" }
WordHunterWoW_QuestEN[50778] = { title = "Twisted Intentions", description = "Sails... in the fog...\n\nA light below... in the darkness.\n\nWater rising... given form... the pain... \n\nAHHHH, THE PAIN!\n\nMake it stop. Make it stop. Make the pain stop!", objectives = "" }
WordHunterWoW_QuestEN[50780] = { title = "Oathbound", description = "I took oaths, damn it. We all did.\n\nWhen Lord Stormsong sent the first orders... well, you saw what happened. What matters is that our oaths are to our people, not Lord \"Sells His Soul\".\n\nYou won't find him here - he's deep in the Shrine by now, and no outsider will make it across the channel alive...\n\nNot without a Tideguard to open the way.\n\n<Victoria locks eyes with you.>\n\nThe Rod of Tides is the key to the front door, and it's kept here. Retrieve it and I can get you to him.", objectives = "" }
WordHunterWoW_QuestEN[50781] = { title = "A Bridge Too Far", description = "The bridge that once crossed this span is the only land route to the Shrine. \n\nIt appears Lord Stormsong has sealed it to buy himself more time. We have been attempting to reopen the way to no avail.\n\nHowever, the Rod of Tides you recovered may prove our solace. Veteran tideguards use it as a key of sorts to maintain the Path of Storms across these dangerous waters.\n\nWe will begin the ritual once more... if you will wield the rod.", objectives = "" }
WordHunterWoW_QuestEN[50783] = { title = "The Abyssal Council", description = "The tidesages have a leading council beneath Lord Stormsong. They each oversee a different aspect of the order's work.\n\nWavespeaker Reid trains initiates here in the oldest form of tidesage magic: communing with the sea.\n\nThese deaths are on his hands. It's up to us to take him down.", objectives = "" }
WordHunterWoW_QuestEN[50784] = { title = "Eye of the Storm", description = "If Lord Stormsong wasn't aware of you yet, he is now. Your best shot is to reach him at the Shrine of the Storm before more of his followers fall back to his defense.\n\nI can get you in, but you'll have to protect me. I'm in no shape to take down any more of these fiends.\n\nAnd try to keep a low profile. The closer we get to the Shrine, the more power Lord Stormsong has at his disposal.", objectives = "" }
WordHunterWoW_QuestEN[50787] = { title = "Make Our Case", description = "Katherine has trusted Priscilla Ashvane as an advisor and a close friend for many years, even before they both lost their husbands at Theramore.\n\nShe's heard the rumors about Ashvane, just like anyone. Whether by fear or loyalty, she's chosen to ignore them.\n\nIt's time to finally open her eyes.", objectives = "" }
WordHunterWoW_QuestEN[50788] = { title = "Enemies Within", description = "We need to get Katherine to safety.\n\nHelp us take out some of these traitors!", objectives = "" }
WordHunterWoW_QuestEN[50789] = { title = "Clear the Air", description = "Looks like Priscilla had a backup plan. Her goons set off some kind of smokescreen to cover her escape.\n\nClear out that smoke so the civilians can evacuate and we can secure the area!", objectives = "" }
WordHunterWoW_QuestEN[50790] = { title = "Hot Pursuit", description = "Priscilla's escaping on horseback! Grab one of our chargers and chase her down!", objectives = "" }
WordHunterWoW_QuestEN[50791] = { title = "Skree...", description = "<Kua'fon rests with his head under his wing.>\n\nSkree...\n\n<Perhaps the little guy could use a display of affection to raise his spirits.>", objectives = "" }
WordHunterWoW_QuestEN[50793] = { title = "Cave Commotion", description = "Killing that worm stirred up a commotion in the caves below. The Irontide seem pretty excited. We better check it out.\n\nNedly's on his way, meet us near the caves.", objectives = "" }
WordHunterWoW_QuestEN[50794] = { title = "Seeking Shelter", description = "I must head back to de arena. Razgaji will want to know what happened here. \n\nIf you seek shelter, you will find it at de outpost not too far from here.\n  \nI will let our leader know you're coming.\n\nBe safe, {name}.", objectives = "" }
WordHunterWoW_QuestEN[50795] = { title = "Prepare for Trouble", description = "With the evidence you've gathered, we can prove that the Ashvane Company was behind the attack.\n\nI would have preferred to do this in private, but I don't think we'll have the luxury. Look around - company men everywhere. \n\nPriscilla's got something up her sleeve...\n\nLet's get some backup before we go in there and cause a scene.", objectives = "" }
WordHunterWoW_QuestEN[50796] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEEEEEE!!!\n\n<You know what to do.>", objectives = "" }
WordHunterWoW_QuestEN[50797] = { title = "A Turtle's Invitation", description = "You have been most helpful {race}. Please visit me and the other Tortollans along the Jeweled Coast.  \n\nWe'll discuss soup and other pressing matters.", objectives = "" }
WordHunterWoW_QuestEN[50798] = { title = "Out on a Limb", description = "Ah, there you are.\n\nKua'fon ran off into de jungle. I saw him head down de western path out of the Kraal but beyond that I could not say where he may have gone.\n\nThis kind of thing happens with the young. Our winged companions have a keen sense of adventure!\n\nIt would be helpful if yours could fly, but it is not yet time. I would check any reasonably high place that he could climb to, as a start.", objectives = "" }
WordHunterWoW_QuestEN[50800] = { title = "Into the Woods", description = "Careful, {name} -- the forest is still brimming with Stormrage's forces...\n\nLook out behind you!", objectives = "" }
WordHunterWoW_QuestEN[50801] = { title = "A Nose for Ptrouble", description = "Ah, yes, I was wondering when you would come to check on your little one.\n\nAs you have likely noticed, he is not here. Little ones are very curious and often seek to leave the nest before they are ready. It is often the brooding mother's job to keep them from wandering.\n\nWhat, did you think I was going to stop him?\n\n<Wingminder Goja laughs.>\n\nI heard some screeching to de west. Best hurry, or you may not have a hatchling to look after!", objectives = "" }
WordHunterWoW_QuestEN[50802] = { title = "Iron Low Tide", description = "A few years ago I tried to join the Irontide. They said I wasn't \"Irontide material\", not cruel or heartless enough! \n\nSo I teamed up with Nedly and Moxie here in Deadwash, and we started looking for treasure on our own.  \n\nLet's show these Irontide they're not \"Deadwash material\".", objectives = "" }
WordHunterWoW_QuestEN[50803] = { title = "I Want It All Now", description = "These Irontide Raiders think they can just come in and take the treasure we've been hunting for months!\n\nBy rights, that treasure is ours! Get in there and get our share of it, before it's gone.  \n\nBy share, I mean all of it!", objectives = "" }
WordHunterWoW_QuestEN[50808] = { title = "Halting the Empire's Fall", description = "Nazmir be havin' problem after problem, {name}. I not be knowin' how it can get much worse dan an Old God tryin' ta take over.\n\nI be makin' me way back ta Zul'jan ta lead our efforts ta keep Nazmir safe.\n\nYa should return ta Zuldazar and let Baine know what be goin' on here. Maybe he be likin' dis here underrot, who knows?\n\nI can get ya outta here and back ta Zul'jan, if ya be needin' it.", objectives = "" }
WordHunterWoW_QuestEN[50810] = { title = "Break 'Em Out", description = "An Irontide captain \"Calico McGee\" has been trying to scare us off for days now, but it's not working.\n\nHe's ordered his men to lock everyone up and sell us as slaves! They've brought enough chains for everyone!\n\nBreak the chains and set our workers free.", objectives = "" }
WordHunterWoW_QuestEN[50812] = { title = "Awakened Elements", description = "It seems that all of this infernal blasting and hammering has stirred up... something.\n\nI heard some screaming from over in that direction.\n\n<He gestures vaguely to the north.>\n\nIf you could go take care of the situation, that would be most appreciated.", objectives = "" }
WordHunterWoW_QuestEN[50814] = { title = "A Horrible Place", description = "This town is a horrible place full of bad people. All they care about is money! No one cares about the turtles!\n\nThe turtles are out there, thirsty, drying up, and getting stepped on by monsters!\n\nYou have to save the turtles for me!", objectives = "" }
WordHunterWoW_QuestEN[50817] = { title = "A Charming Tail", description = "I think they would make great guardians, when they get older... with the proper training.\n\nHowever, it seems some of my trainees have wandered off. There are so many things nearby that could harm them!\n\nBetween the walking sandstorms and angry plants... it's been safer to hide out here and look at night.\n\nI'm so exhausted! \n\nCould you take this flute with you and play them a little tune? It will remind them to come back to me.", objectives = "" }
WordHunterWoW_QuestEN[50818] = { title = "A Lost Flute", description = "<This little flute, while dusty, appears to be well cared for.\n\nIts owner can't be too far away.>", objectives = "" }
WordHunterWoW_QuestEN[50823] = { title = "Ripe for the Picking", description = "The kaldorei have finally halted our progress. In a perfect world, we could have marched all the way to Auberdine and taken Teldrassil before they could even slow us down - but it matters little.\n\nMalfurion will try to hold us back until his fleet returns from Silithus. Until then, his army is too small - if only we could find a path through these damned wisps.\n\nI have an idea. Let's have a chat with Saurfang.", objectives = "" }
WordHunterWoW_QuestEN[50824] = { title = "Storm's End", description = "I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. \n\nWe have him surrounded, cornered like the rat he is. We must end this together.", objectives = "" }
WordHunterWoW_QuestEN[50825] = { title = "Shrine of the Storm: Whispers Below", description = "We must not let Lord Stormsong finish his work.\n\nIf he delivers the fleet to Azshara, all of Kul Tiras will be vulnerable. Countless innocents will perish -- or worse.\n\nThere is no time to wait for more of the Storm's Wake to arrive. We finish this now, for the good of all who call this valley home.\n\nWe finish this for Samuel.", objectives = "" }
WordHunterWoW_QuestEN[50834] = { title = "Keep It Down!", description = "There is a lot of noise and light coming from those filthy mechs down by the shore. No wonder my  little hatchlings get so cranky!\n\nThey are shaking up a coast that is already unstable. You never know what one might wake up that way! \n\nLet them know they should be careful.", objectives = "" }
WordHunterWoW_QuestEN[50835] = { title = "The Port of Zandalar", description = "King Rastakhan has given me orders to investigate de Harbor of Zandalar. De claim Princess Talanji has levied against General Jakra'zet for failing to maintain de safety of our kingdom is a serious accusation.\n\nFor dis task, I would have you join me so dat I might have an outside perspective. When you are ready, meet me in de Grand Bazaar.", objectives = "" }
WordHunterWoW_QuestEN[50837] = { title = "A Quick Flyover", description = "Malfurion knows that his wisp wall is a temporary measure. He is buying time for reinforcements to arrive in Teldrassil.\n\nIt is imperative that we find a way through that wall, and quickly.\n\nI want you to take our explosive reserves and apply pressure. You will not be able to bring it down, but you may be able to find us an opening. I will have a squadron ready to strike once you break ground.\n\nZarvik Blastwix should have a few bombardiers for the job.", objectives = "" }
WordHunterWoW_QuestEN[50838] = { title = "A Nose for Ptrouble", description = "Ah, so you noticed he is missing again.\n\nI would check de east this time. I heard some screeching from that direction.\n\nI am sure he will be fine- after all, what sort of trouble could he get in with you looking after him?\n\n<Wingminder Goja smiles just a touch sarcastically.>\n\nBest find out.", objectives = "" }
WordHunterWoW_QuestEN[50839] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", objectives = "" }
WordHunterWoW_QuestEN[50841] = { title = "SKREEEEE!", description = "<Kua'fon opens his maw and issues a continuous screech.>\n\nSKREEEEEEEEE!!\n\n<You know what to do.>", objectives = "" }
WordHunterWoW_QuestEN[50842] = { title = "Mast Effect", description = "Kua'fon was peering over de edge and managed to fall off de cliff again.\n\nNormally he gets back up here on his own, but it be taking too long this time.\n\nBest go down to de beach and find him. He is probably stuck up one of de ship masts out there.\n\nIf he will not come down, you can try bribing him with more fish.", objectives = "" }
WordHunterWoW_QuestEN[50860] = { title = "A Nose for Ptrouble", description = "Kua'fon is getting very large. Perhaps he thinks himself equal to de beasts of this jungle.\n\nHe may well learn that he is not. You should find him before that lesson costs him his life.\n\nI heard a commotion to de north. Start there.", objectives = "" }
WordHunterWoW_QuestEN[50878] = { title = "Blurred Vision", description = "Look up.\n\nSee them, scattered among the trees? Those brightly glowing owls are not living, breathing denizens of the forest... they are Kaldorei magic. Sentries. A ruse -- reporting everything they see back to Malfurion.\n\nWe can't have that, now can we?\n\nDeal with them, {name}. But take care -- they aren't the only enemies in the forest.\n\nWe cannot allow anything or anyone to stand in our way.", objectives = "" }
WordHunterWoW_QuestEN[50879] = { title = "The Trees Have Ears", description = "With the eyes of the forest shut, one thing remains: the ears. Ancients. \n\nThey feel the vibrations of our footsteps and report our every move to Malfurion.\n\nGot that torch handy?", objectives = "" }
WordHunterWoW_QuestEN[50880] = { title = "An Unstoppable Force", description = "Now is the time to strike, {name}. \n\nPassing through the wall will not be easy, but I think it's something you can handle. Do what you must to prevail, and meet me on the other side. I will lead a squad of sturdy soldiers and as many demolishers as can survive the passing.\n\nWe may not make it to Darnassus today, but the outcome of this war does not rest on one victory alone -- it will come as the result of a thousand small victories.\n\nSo let's get started, shall we?", objectives = "" }
WordHunterWoW_QuestEN[50881] = { title = "Royal Report", description = "Blood magics practiced in de city, guards missing, and our chief spy, Yazma, is acting suspicious. We must present dis to Rastakhan, but without Yazma interfering.\n\nLuckily, Rastakhan is a clever king, which is something his opponents often forget.\n\nI have prepared a report in a code made by King Rastakhan and known only to myself and my brother, Habutu. Bring it to Habutu and he will see dat it gets to de king's ear.", objectives = "" }
WordHunterWoW_QuestEN[50882] = { title = "All to Ash", description = "All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity.\n\nWith Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood.\n\nBut this... this will unite them. They will come for us. All of them.\n\nReturn to the Undercity, {name}. Speak to the warchief. We must make ready for what is to come.", objectives = "" }
WordHunterWoW_QuestEN[50886] = { title = "Surrogate Wings", description = "It is not my way to coddle the young of my brood. But I think I will make an exception for your little one.\n\nAfter all, I have seen you tend to him. It would be cruel to let your... efforts... go to waste.\n\nVenture into Zuldazar city proper and find something that can act as a surrogate wing for your young one.\n\nWingminder Goja will know what to do next. Speak to him once you have it.", objectives = "" }
WordHunterWoW_QuestEN[50887] = { title = "Ptrust Fall", description = "I just want you to know how unusual this is for Pa'ku. She prefers to teach on the fly.\n\nWhat? It's true.\n\nThis method might work. Sometimes when young pterrordax are not eager to fly, their mother will drag them from the nest and hold them in her claws until they are comfortable enough to spread their wings.\n\nSeeing as this little one has no mother, you will use the kite to act as one.\n\nPa'ku has placed a trail for you to follow.\n\nGo and glide carefully- you may frighten your pterrordax more!", objectives = "" }
WordHunterWoW_QuestEN[50897] = { title = "Turn the Heat Around", description = "<In standard goblin fashion, the Horde forces seem to be using flamethrowers to clear out the snow.>\n\n<This one is still usable despite being beaten on, you could use it to destroy some of the goblin mining machinery.>", objectives = "" }
WordHunterWoW_QuestEN[50900] = { title = "Maybe When You're Older", description = "<Pa'ku squints down at the young pterrordax.>\n\nWell, I am out of ideas. My son will take you back to the nest. Do not worry, this one can fly.\n\nYOUR little one will need to get back on his own. It builds character.\n\nMaybe he will grow out of this absurd deficiency in time.", objectives = "" }
WordHunterWoW_QuestEN[50901] = { title = "Saurid Surprise", description = "Da sands of Vol'dun be full of harsh creatures, but none so harsh as dey dat da Zandalari send.\n\nOne of dese criminals be right here in da Scorched Sands. His name be Sezahjin, and he be da former chef ta da king. Did he tell ya dat he be famous for a dish called \"Saurid Surprise?\" Guess what da main ingredient be.\n\nHe be fallin' far, but not far enough for Jani. It be time ta take his pride.\n\nJust be makin' sure dat da creatures of da sand not be seein' ya.", objectives = "" }
WordHunterWoW_QuestEN[50903] = { title = "A Missing Master", description = "Master Ashton had me grab some healing supplies and run to Mayor Royston when those things attacked town. He didn't make it behind the barricade.\n\nBut if he's alive--and he's just crazy enough he might be--he's probably holed up in his cottage. With caustic compounds. And explosives.\n\nLook, why don't you go check out his basement and I'll stay out of the blast radi- I mean I'll go see if the garden can be salvaged.\n\nTry not to look flammable.", objectives = "" }
WordHunterWoW_QuestEN[50904] = { title = "The Abandoned Passage", description = "My people have known about this ancient passageway for generations, but none have dared enter before now.\n\nThe tunnel leads to the tomb of Mythrax the Unraveler and it is said that his power still radiates within the cavern. Who knows what horrors await us inside...\n\nIt appears that your friends have already gone inside to face Jakra'zet and stop him from raising Mythrax from the dead.\n\nWe don't have time to waste. We must find Kaja and Rakera before they confront Jakra'zet on their own!", objectives = "" }
WordHunterWoW_QuestEN[50908] = { title = "Smells Like Trouble", description = "The Horde spilled a lot of blood in Brennadam. Now it's time to spill some more.\n\nThe scent of blood makes predators in these hills go crazy. We use it to lure animals when hunting.  \n\nThe Horde forces are occupying caves up in the hills. Toss these scent vials into the caves where the Force Commanders organize the attack. The smell should bring all the hills down upon them!", objectives = "" }
WordHunterWoW_QuestEN[50909] = { title = "Never Outgunned", description = "This is our new home now, and we will fight to keep it!\n\nWe may be outnumbered here, but we aren't going to be outgunned.\n\nFind us every axe, sword, spear, crossbow, and gun for our rebellion!", objectives = "" }
WordHunterWoW_QuestEN[50910] = { title = "Dangerous Game", description = "Most of these Horde don't scare us, but we lost two people today to a group of forsaken keenblades. We've had trouble tracking them down, we could really use your help.\n\nThey're stealthy and dangerous fighters, so show no mercy.", objectives = "" }
WordHunterWoW_QuestEN[50911] = { title = "One Man Against the Horde", description = "Me an' a few friends were trying to help some of the folks from Corlain flee safely to Arom's Stand after things started gettin' weird. I noticed some movement up the hill so I decided to come back and check it out. If the town goin' mad wasn't bad enough, now we have another problem to deal with.\n\nThe Horde.\n\n<McKellis spits.>\n\nThose fools have no place on our lands. Wash the snow with their blood.", objectives = "" }
WordHunterWoW_QuestEN[50912] = { title = "Remix to Ignition", description = "<A goblin mining machine is halfway sticking out of the snow.\n\nDespite being buried, it seems to be in working condition. If only you had a key.>", objectives = "" }
WordHunterWoW_QuestEN[50913] = { title = "Akunda's Blessing", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine to receive my gift.\n\nKnow that whatever you choose, you will always be welcome within these walls.", objectives = "" }
WordHunterWoW_QuestEN[50929] = { title = "Powder to the People", description = "The Horde filth up on that hill seem to be mining some kind of ore I've not seen before.\n\nIf they've come all the way out here to find it, it must be valuable. Take what you can find!", objectives = "" }
WordHunterWoW_QuestEN[50930] = { title = "Falling With Style", description = "<Kua'fon looks to the kite, then back at you. He looks to the kite again, poking his head forward deliberately. He slowly pans his gaze back to you.>\n\nSkree.\n\n<Time for another flight!>", objectives = "" }
WordHunterWoW_QuestEN[50933] = { title = "An Unfortunate Event", description = "<You have no means of identifying the corpse, but the clothing appears to be that of an imperial guard from Zuldazar.\n\nA quick search of the area reveals a trail of blood that heads off to the west. Perhaps if you follow it you can discover the cause of death.>", objectives = "" }
WordHunterWoW_QuestEN[50934] = { title = "A Chance Sighting", description = "One of the lookouts said he saw a bunch of blood trolls chasing after a Zandalari on the other side of the river.\n\nHe seemed to be dressed like your group. Why do you people keep running into trouble in this place?\n\nI'll mark on your map where he was last seen. Just don't bring a horde of blood trolls over here, alright?", objectives = "" }
WordHunterWoW_QuestEN[50940] = { title = "Wisdom of the Wingless", description = "<Kua'fon wheezes and quivers, exhausted.>\n\nIt's not going anywhere. Maybe it's time to seek someone without wings for advice.", objectives = "" }
WordHunterWoW_QuestEN[50942] = { title = "Dress for the Slide, Not the Ride", description = "If Kua'fon is serious about flying, we're going to need to protect him.\n\nGo get a berserker skull and some armor for it. Meet me down in Talanji's Rebuke and we'll get him dressed for success.", objectives = "" }
WordHunterWoW_QuestEN[50943] = { title = "The Joy of Flight", description = "You be ready, {name}?\n\nKua'fon is ready to fly. Whether or not he can is another question, but all the same I will see you two back to the roost.\n\nClimb aboard and guide him. I can't imagine he can see very well through that skull.\n\nAta and I will lead the way.", objectives = "" }
WordHunterWoW_QuestEN[50944] = { title = "Down, But Not Out", description = "<Kua'fon wiggles happily in his new armor. He starts to pace restlessly back and forth. A taste for adventure has surely awakened in this flightless creature.>\n\nSkree! Skree!!", objectives = "" }
WordHunterWoW_QuestEN[50953] = { title = "Greenstalker", description = "The mighty wolf Greenstalker was once a protector of these forests. He has fallen under the sway of dark forces. My brother and I attempted to calm his spirit, but he is too far gone.\n\nUse the charm I have constructed to weaken him. I ask you {class}, please, end his suffering.\n\nMy brother is still weak and I must stay to protect him. Go now before the wolf consumes us all!", objectives = "" }
WordHunterWoW_QuestEN[50954] = { title = "Zandalar Forever!", description = "Bwonsamdi has whispered a warning to me: the enemy is on the move.\n\nI have gathered what defenses I could in the time allowed but we are dangerously under powered. \n\nI can only hope that, thanks to your efforts, the loa will be with us this day.\n\nAre you ready to defend Zandalar?", objectives = "" }
WordHunterWoW_QuestEN[50955] = { title = "We're Not Friends", description = "I did some time in Tol Dagor with the captain of this crew, Calico McGee. He likes to hang back and direct his men from afar.\n\nI just happened to have spotted him across the flats. You and I should go pay him a visit!", objectives = "" }
WordHunterWoW_QuestEN[50956] = { title = "Walking-Around Money", description = "This is a lot of gold! It's gonna take me a while to split this up. I can give you some walking-around money to hold you over until I am done.\n\nCome back tomorrow, maybe I will have it figured out.", objectives = "" }
WordHunterWoW_QuestEN[50960] = { title = "Sweete's Orders", description = "<Tucked into the pages of the captain's logbook is a letter bearing the seal of Harlon Sweete.\n\nIt looks like these pirates have been ordered by Sweete to cause further disruption to House Waycrest. \n\nLucille should be notified of this immediately!>", objectives = "" }
WordHunterWoW_QuestEN[50963] = { title = "Of Dark Deeds and Dark Days", description = "I should have known better, and now Rezan is dead, and my own power is barely holding on. Soon Bwonsamdi himself will be coming to collect me.\n\nTalanji... she must know what has happened here. Go to her, tell her. Aid her where you can.\n\nI followed a god of strength and yet I have not de strength to face her with dis shame.\n\nFor now, I must gather our forces and pursue Zul.", objectives = "" }
WordHunterWoW_QuestEN[50965] = { title = "Those Who Remain", description = "<The runes on the wooden plaque glow faintly with an ancient magic. It looks like it is a small piece of a larger record.>\n\n<One of the Thornspeakers at the Teller Farm would probably recognize what this is.>", objectives = "" }
WordHunterWoW_QuestEN[50967] = { title = "Lost in the Woods", description = "My student, Amalie, and I have taken it upon ourselves to act as the keepers of these woods. We were away from Drustvar briefly, and upon our return, found the grove infested and the surrounding land corrupted.\n\nAmalie decided that she could deal with the grove infestation alone.\n\nIt's been some time since she ran off, could you look for her while you're in the Ashenwood?", objectives = "" }
WordHunterWoW_QuestEN[50970] = { title = "A Farmer's Fate", description = "Old Jakob here was one of the few folks who were never wary of us. I have, on occasion, even helped him around his farm in return for supplies. It is an injustice just to ignore his plight even amidst our own problems.\n\nThe corruption which holds him seems to be early in form. I believe I can cleanse it.\n\nTake this branch, and bring it to the three shrines around the Ashenwood. That should allow it to gather enough energy for the ritual.", objectives = "" }
WordHunterWoW_QuestEN[50972] = { title = "Proudmoore's Parley", description = "So, we meet again.\n\nI... apologize for how you were treated last time. I trusted Priscilla like a sister and-- \n\n<Katherine chokes up for a moment before regaining her composure.>\n\nLet us keep this brief, for I will make no promises nor any formal accords in this state.\n\nReturn to your leaders. Tell them I wish to parley.\n\nThat is all for now. My people have suffered a great deal today and I have much to reflect upon.", objectives = "" }
WordHunterWoW_QuestEN[50976] = { title = "An Ancient Curse", description = "<The harsh conditions of Nazmir have not been kind to the stone tablet.\n\nMost of the inscriptions have been worn away but you are able to make out a picture that shows a chest surrounded by glyphs. Above the chest you noticed what appears to be a large floating skull.\n\nBelow the images you find a single word \"Aiji\".\n\nThe ruins ahead seem foreboding, and you may want to bring some friends to help you.\nWith their help, perhaps you can find the secret of this \"Aiji\" and its treasure within.>", objectives = "" }
WordHunterWoW_QuestEN[50978] = { title = "Out With the Old Boss", description = "Right so I talked to some people. You talked to some people. No one likes the Irontide. They're cutting in to profits and scaring off good, honest scoundrel- er customers! \n\nWe take out the guy in charge and we'll be able to run the rest outta town! So a little change of management is in order.\n\nI'm not usually one for stabbin' people, I'm a lover not a fighter, but I can pay. You do this for me and I'll make sure you're welcome here whenever ya want? Sound good?", objectives = "" }
WordHunterWoW_QuestEN[50979] = { title = "Just a Nip", description = "My tough-guys-in-training are quick learners! \n\nThey do seem to get a bit... bitey... when they're grouchy, though. Too many, and I start to get a little light-headed.\n\nThe nearby atrivax plants have a medicinal gel. It is great to treat fresh wounds and nullify venom.\n\nThey don't like sharing it. Could you harvest a bit for me?", objectives = "" }
WordHunterWoW_QuestEN[50980] = { title = "My Hungry Neighbor", description = "There is an angry hydra that has decided to make a nearby ridge his home.\n\nHe keeps getting bigger, and meaner, and hungrier!\n\nMy cobras are terrified. \n\nPlease, {name}, take care of him before he comes after us!", objectives = "" }
WordHunterWoW_QuestEN[50988] = { title = "An Economic Opportunity", description = "You look savvy enough to jump on an opportunity when one comes by and, pal, do I have one for you.\n\nSee that cove down there? It's run by entrepreneurs with an eye towards meeting the logistical shortfalls that might come up in your typical city or town situation. Well, it's normally run by them.\n\nWe have a bit of an infestation by folks who are more mercenary minded if you catch my meaning.\n\nYou help me win back control of the cove and I'll see you're treated well. Sound good?", objectives = "" }
WordHunterWoW_QuestEN[50990] = { title = "Cutting Edge Poultry Science", description = "<Before you is a delicious chicken... And yet, despite everything, there is something a little bit... lively about this creature.\n\nWith a judicious application of science, there might be something that can still be done for this poor bird.\n\nYou resolve to bring the chicken to Dr. Oglethorpe in Booty Bay with all haste.>", objectives = "" }
WordHunterWoW_QuestEN[51001] = { title = "Every Day I'm Smugglin'", description = "Hey! Wanna make some quick gold?\n\nSee, I had a mishap a few weeks ago with a shipment. Too much grog, dark seas, sudden rocks. You know, that old story.\n\nAnyway, my cargo's been floating out there and no one will get it back for me. Can you believe it? You bring my cargo back and I'll pay you a generous recovery fee.\n\nWe got a deal? Great!\n\nOh, uh, watch out for the sharks. Did I forget to mention the sharks?", objectives = "" }
WordHunterWoW_QuestEN[51016] = { title = "Seeking More Knowledge", description = "It pains me to admit that I don't know everything about plants.  I've taught you everything I know about Anchor Weed, but I think I know where you could look to learn more.  Unfortunately, it's in Waycrest Manor, and that whole area's been crawling with monsters as of late.\n\nIf you find yourself inside that manor, keep an eye out for a book called, \"The Treatise on Anchor Weed\".  Its author spent decades studying that forsaken weed.", objectives = "" }
WordHunterWoW_QuestEN[51018] = { title = "Asking for a Friend", description = "Hey! Since you helped Cesi I thought maybe you might do a favor for me.\n\nWell, uh, y'see Miss Sweetflower over there? Sweet as honey, sharp as a tack, and cooks like a goddess.\n\nI'm not much to look at, but the lady might think kindly on me if I could surprise her with a gift. A really great gift! But I can't leave m'post or these red-coated jerks might run off with the merchandise. \n\nThis is where you come in. Find out what Miss Sweetflower wants, get it and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[51019] = { title = "She's Got it Where it Counts", description = "Word is you're looking to drum up support for Loosecannon. Well I'll buy in if you help me. They took my poor Miranda! \n\nBoss Tornsail says I had too much to drink and bet her in cards. I don't really remember what happened last night, but I can hold my liquor and I'd never bet my bird! I suspect funny business. She might not look like much, but Miranda's the fastest damn falcon you'll ever see.\n\nThey're watching me, so you go free her. She'll fly someplace safe and I'll get her later. We got a deal?", objectives = "" }
WordHunterWoW_QuestEN[51020] = { title = "Cutthroat Business Practices", description = "I used to run the inn here. Was a nice gig. I got first crack a lot of good stuff and all the best gossip and information came through my place.\n\nAnd then that jerk, Gary Cofferdam, came in and kicked me out! The new Boss laughed! \n\nI'm lookin' at my last few silvers here. Business is not good!\n\nTell ya what, you remove my problem and I'll side up with Cesi. She'd never kick me out.", objectives = "" }
WordHunterWoW_QuestEN[51053] = { title = "The Day the Port Fell", description = "Dis be a cursed land, {race}. Feel it in your bones: de cold chill of death... and undeath.\n\nDe Pirate-King Zem'lan rules dis port, with his crew of de eternal damned.\n\nIf you be lookin' for honor or noble adventure, you won't find it here. But if you can settle for vengeance and treasure, I got an offer for you.\n\nBut you should know who you be allying with. My hands are not clean in dis.\n\nTake de medallion from my cloak and use it to reveal a vision of my past at de end of de dock.", objectives = "" }
WordHunterWoW_QuestEN[51054] = { title = "Overdue Mutiny", description = "I used to be a Zandalari, {name}.\n\nLong ago, before dis curse. We were all Zandalari pirates, proudly sailing under de black flag of our captain, Zem'lan.\n\nNow look at us... undead monsters, forced to serve our eternal captain like slaves.\n\nWell, I be done with dis. De curse can't be broken, but we can still mutiny!\n\nWhat say you? It gonna be tough, but I promise treasure and a chance to kill de notorious Pirate-King Zem'lan who murdered your vulpera friend.\n\nHelp me down, and we be gettin' started.", objectives = "" }
WordHunterWoW_QuestEN[51055] = { title = "The Yard Arm of the Law", description = "I'm not de only pirate Zem'lan has had strung up around de port. Hangin' on de yard arm is his favorite form of punishment for de crew.\n\nWe can't feel pain and don't stay dead, so his options are limited.\n\nLook for more crewmates hangin' around town. Tell dem to meet me here after you free dem.\n\nAfter weeks of hanging helplessly while being mocked and abused by de rest of de crew, I bet dey be willin' to discuss mutiny.", objectives = "" }
WordHunterWoW_QuestEN[51056] = { title = "My Last Day Alive", description = "De curse came one fateful day, in ages past, when de sethrak attacked. Dere was no end to dem.\n\nIn our desperation, I helped Pirate-King Zem'lan do de unthinkable.\n\nWe became monsters. Even worse, we became eternal slaves to Zem'lan.\n\nDe curse weighs heavy on me, but my guilt is heavier. I led me crew into dis.\n\nBefore we confront de Pirate-King himself, you need to understand what we be up against.\n\nYou need to see what happened de day dat de Port of Zem'lan fell.", objectives = "" }
WordHunterWoW_QuestEN[51057] = { title = "Maroon 'em with Fire", description = "We gonna have to sail out to de Golden Isle to face Pirate-King Zem'lan.\n\nLet's make sure de rest of de crew can't follow us once we go. Burn their boats in de harbor.", objectives = "" }
WordHunterWoW_QuestEN[51059] = { title = "The Golden Isle", description = "Pirate-King Zem'lan don't stay in de port with de rest of us. Too good to crack a jug with his crew no more.\n\nWe gotta sail out to de Golden Isle to find him. That be de forbidden island where Zem'lan hoards all of de treasure we've pillaged and plundered, so only he can enjoy dem.\n\nHop in my boat and we'll row out dere together.", objectives = "" }
WordHunterWoW_QuestEN[51060] = { title = "Our Share of the Plunder", description = "Dis treasure belongs to de crew! We've fought every battle for Zem'lan, but he hoards all de booty for himself.\n\nAnd if ya try to take some for yourself, he turns ya into one of his goldslaves. Those be de mindless drones ya see tendin' to de treasure out here.\n\nWe ain't leavin' here empty-handed after de mutiny. Collect all de treasure ya can!\n\nBeware de cursed bits. It don't hurt us, but I'm guessin' it'll hurt you.", objectives = "" }
WordHunterWoW_QuestEN[51061] = { title = "The First Time I Died", description = "Dis be it. Where Zem'lan cursed us all.\n\nIt began with me death. De first of countless deaths I've had since. Each of dem spent fighting and dying for Pirate-King Zem'lan and his selfish treasure hoard.\n\nI don't know if de idols he used to curse us can even be destroyed, but we gotta try. Let's take dem to de altar where de ritual occurred and try to smash one.", objectives = "" }
WordHunterWoW_QuestEN[51062] = { title = "Escaping Zem'lan", description = "Pirate-King Zem'lan was right about one thing: he won't stay dead for long.\n\nWe gotta take our treasure and get out of here while we got de chance.\n\nWe can take de boat, but we'll need a place to hide out for awhile. Are your vulpera friends open to housin' a few stowaways?\n\n<First Mate Jamboya motions to the piles of treasure in his boat.>\n\nClearly, we can pay dem for their trouble.", objectives = "" }
WordHunterWoW_QuestEN[51068] = { title = "Raiding Their Stores", description = "We're low on food supplies.\n\nHit up Newstead and bring us whatever you can find.", objectives = "" }
WordHunterWoW_QuestEN[51069] = { title = "WANTED: Darkspeaker Jo'la", description = "Wanted for atrocious crimes against the Zandalari: Darkspeaker Jo'la\n\n Defeat this powerful adherent of Zul, and a great reward shall be yours.", objectives = "" }
WordHunterWoW_QuestEN[51070] = { title = "Raiding the Boulderfist", description = "The Boulderfist have recently raided Drywhisker Mine, and are sitting on a large amount of iron ore.\n\nWe want it back.", objectives = "" }
WordHunterWoW_QuestEN[51071] = { title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "" }
WordHunterWoW_QuestEN[51072] = { title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "" }
WordHunterWoW_QuestEN[51082] = { title = "Iron Stores", description = "While the mine is under Horde banners our peons ensure the iron supply never runs dry.\n\nThis key provides access to the chest. Make sure it still works.", objectives = "" }
WordHunterWoW_QuestEN[51085] = { title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", objectives = "" }
WordHunterWoW_QuestEN[51086] = { title = "Break's Over", description = "It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low.\n\nTake this club and get those lazy peons back on track.", objectives = "" }
WordHunterWoW_QuestEN[51087] = { title = "WANTED: Dark Chronicler", description = "Champion wanted for an expedition into the depths of Xibala. \n\nStrange noises and wails come from the bones at night and our workers are terrified. \n\nSeek out the source of the strange noises and destroy it, and a reward will be yours.", objectives = "" }
WordHunterWoW_QuestEN[51088] = { title = "Heart of Darkness", description = "We sent troops with Captain Conrad ahead to Nazmir to gain a foothold in that hellish jungle.\n\nThe reports we've been receiving of the local troll population are... disconcerting.\n\nThey're in over their heads, {name}. I have Brann Bronzebeard prepped and ready to head out.\n\nAccompany Brann to Nazmir so we can secure our position. The Wind's Redemption is at your disposal.", objectives = "" }
WordHunterWoW_QuestEN[51089] = { title = "WANTED: Tojek", description = "<This appears to be a list of threats in the immediate vicinity, a angry scribble grabs your attention.>\n\nA reward of gold be promised to de one dat slays da creature Tojek. You know what dey say, an eye for an eye! \n\n-Rovash", objectives = "" }
WordHunterWoW_QuestEN[51091] = { title = "WANTED: Ten'gor and Nol'ixwan", description = "To any hunters worthy of the challenge: \n\nFind and defeat the dueling giant direhorn and devilsaur, named Nol'ixwan and Ten'gor. \n\nTheir never-ending battle has disrupted travel throughout Zuldazar. \n\nGlory for any that succeed!", objectives = "" }
WordHunterWoW_QuestEN[51101] = { title = "The Wounded King", description = "I have things under control here... for now, at any rate.\n\nIf we want to salvage this situation, Rastakhan must survive. Habutu is gone, but his other guardian, Zolani, has sent word.\n\nShe is protecting the King at a small fishing village called Zeb'ahari. Find Zolani and do what you can to ensure Rastakhan lives.\n\nBe careful, {name}.", objectives = "" }
WordHunterWoW_QuestEN[51111] = { title = "King or Prey", description = "My loa has seen fit to question my resolve.\n\nFor my people, my pride, and my faith, we will correct dis. Return to your Horde. Ready your forces, and I will ready mine.\n\nWhen de time comes, we will strike back against de traitorous snake, Zul.", objectives = "" }
WordHunterWoW_QuestEN[51129] = { title = "Dubious Offering", description = "Cannae be sure o' the wisdom o' this Captain Conrad.\n\nSendin' our own on these blood troll bats with offerin's?\n\nSomethin' about this stinks more'n an armpit after a bar fight.", objectives = "" }
WordHunterWoW_QuestEN[51134] = { title = "If Bones Could Talk", description = "<These skeletons appear to be rising out of the ancient ruins that dot the land here. Their bones are covered with what looks like runes, but time has worn away all but fragments of the markings.\n\nIf you could find some of these runes intact, Lucille might be able to decipher them to find out where these skeletons come from...\n\n...and why they are no longer at rest.>", objectives = "" }
WordHunterWoW_QuestEN[51139] = { title = "WANTED: Tojek", description = "<The tattered paper appears to include a list of known threats in the area.\n\nThe top of the list reads: \"Tojek - Direhorn - Responsible for damages to 3 vehicles, 6 supply crates, and the tragic loss of Garrick Blacksteel's mole machine, avoid at all costs.\"\n\nPerhaps you can hunt down this creature to prevent further attacks.>", objectives = "" }
WordHunterWoW_QuestEN[51140] = { title = "Share the Wealth", description = "<Though old and mud covered, this is still gold, lots of it! It's not enough to be Nedly's legendary lost treasure, but it's still several thousand in gold coins.\n\nIt's a significant find, and should be returned to Shealds to be split among all the workers.>", objectives = "" }
WordHunterWoW_QuestEN[51142] = { title = "Pests", description = "Confound it all! These rat-faced thieves keep getting into all of our supplies! I swear, anything that's not tied down, and even some things that are, they nip off with'.\n\nYou want to make a difference for the war effort in Zandalar? Pop off as many of those buggers as you can find. \n\nOtherwise, get on with it!", objectives = "" }
WordHunterWoW_QuestEN[51144] = { title = "A Bundle of Furs", description = "You there! Would you happen to be passing by Hatherford?\n\nI have a delivery to make there, but my normal delivery person fell ill after a trip to Anglepoint. \n\nWould you mind taking this bundle of furs to Dandy Jones in Hatherford for me? I would go myself, but I must hold down my stall.", objectives = "" }
WordHunterWoW_QuestEN[51145] = { title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", objectives = "" }
WordHunterWoW_QuestEN[51146] = { title = "Kua'fon's Day Off", description = "You know, I think Kua'fon might be lonely when you are not here.\n\nWhat makes me say that? Well, I got a very angry scroll from a Tortollan indicating he was stealing shiny things from their stalls, but that could mean anything.\n\nYou should probably stop him before he damages your reputation, hm?\n\n<Wingminder Goja cackles.>", objectives = "" }
WordHunterWoW_QuestEN[51147] = { title = "Kua'fon's Day Off", description = "A messenger came from de Terrace of de Chosen. Your companion is at it again.\n\n<Wingminder Goja chuckles.>\n\nNot even de priests of Pa'ku seem to be able to convince him to leave. You should go and send him back home, where he belongs.", objectives = "" }
WordHunterWoW_QuestEN[51149] = { title = "Left at the Port", description = "There was a mishap when we were loading the most recent shipment for the Southwind Station. Apparently some paperwork meant for the dockmaster was left behind.\n\nHe can't hand over deliveries to the couriers without it, but the next cargo ferry won't be departing any time soon. Do you think you could deliver it by foot? The ferry dock is just a short ride down the road.", objectives = "" }
WordHunterWoW_QuestEN[51150] = { title = "Honoring the Fallen", description = "This is a shameful situation. Unforgivable! The soldiers weren't carryin' offerrin's to the blood trolls, they WERE the offerin'!\n\nIt'd be right difficult to bury 'em proper in this hole. Best we can do is get their dog tags.\n\nPoor lads an' lassies.", objectives = "" }
WordHunterWoW_QuestEN[51151] = { title = "A Letter to the League", description = "A researcher at the Resort up the hill was hoping to get a letter out to a group called the \"Explorers' League\". He claims that they have a camp set up near some old Drust ruins on the other side of the sound.\n\nThere's no official station so it will have to be delivered by hand. If you happen to head in that direction, can you take it with you?", objectives = "" }
WordHunterWoW_QuestEN[51159] = { title = "Bring out the Big Gun", description = "<The cannon here is still in good condition. It's a lot of firepower to slow down the Horde.\n\nTaking this to Lea Martinel at Eckhart Lodge would really help their defenses.>", objectives = "" }
WordHunterWoW_QuestEN[51161] = { title = "WANTED: Za'roco", description = "To any with honor and a sharp blade: \n\nFind and kill the thief, Za'roco. \n\nThose that betray their fellow exile don't deserve to live. \n\nAny who can cross his name off this list will earn a fitting reward.", objectives = "" }
WordHunterWoW_QuestEN[51162] = { title = "WANTED: Taz'raka the Traitor", description = "To all caravans and travelers:\n\nBeware Taz'raka the Traitor, a skeleton ambushing travelers on the road near Port of Zem'lan. If you must travel on that road, move quickly, and avoid entering any of the ruins.\n\nSeveral caravans have combined resources to offer a reward for Taz'raka's death.\n\nTo collect, speak with Norah in Camp Lastwind.", objectives = "" }
WordHunterWoW_QuestEN[51164] = { title = "WANTED: Cobra Excursion Participants", description = "Attention guests of the Goldtusk Inn:\n\nWe're proud to announce a surprise new addition to our lineup of excursion activities!\n\nThe new Giant Deadly Unstoppable Killer Cobra Experience is now available!\n\nThere's no need to sign up, you've all been automatically volunteered for this activity.\n\nTo participate, simply travel into the dunes north of the inn and try not to be killed by the massive cobra now patrolling the area.\n\nWe are not currently offering guided tours for this activity. Have fun!", objectives = "" }
WordHunterWoW_QuestEN[51165] = { title = "WANTED: Sandscout Vesarik", description = "To any and all who wish to see the Faithless empire fall: \n\nSandscout Vesarik was spotted patrolling the dunes to the east. Gather a formidable force and strike him down!\n\nThose who succeed will be granted a fitting reward.", objectives = "" }
WordHunterWoW_QuestEN[51167] = { title = "Blood of Hir'eek", description = "Spooky chantin' in the next room can only mean one thing: someone's askin' for the ol' what-fer!\n\nI'd give ya a hand but I gotta drink a couple-a potions before I'm back on me feet.\n\nTake out that blood witch and I bet the magic'll dissipate.", objectives = "" }
WordHunterWoW_QuestEN[51168] = { title = "Zealots of Zalamar", description = "We're surrounded by the enemy, {name}, and it's got me blood ragin'!\n\nI'm fit as a fi... instrument... and ready to help get us outta this forsaken cavern.\n\nLet's show 'em the end o' their miserable lives, eh?", objectives = "" }
WordHunterWoW_QuestEN[51169] = { title = "Flight from the Fall", description = "Let's get outta this hole! Hairs on the back o' me neck won't settle down. Was hopin' I'd find some artifacts, or treasures, or haggis, or at least a few worthwhile trinkets down here.\n\nThose bats look like the ones that we came on... hopefully they'll take us back to Fort Victory and not some rotten grotto with no valuables inside.", objectives = "" }
WordHunterWoW_QuestEN[51170] = { title = "Ooh Rah!", description = "We're going to need a harbor for our base of operations. Those ruins across the way should be perfect for our needs.\n\nUnfortunately, it looks to be occupied by a hostile force so I'm sending the marines to secure the shore. As the most experienced soldier here I want you to go with them. \n\nI don't want to see a single hostile remain when our engineers arrive.\n\nNow, go take that harbor in the name of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[51177] = { title = "Lessons of the Damned", description = "When I arrived here in disguise, the blood trolls thought me some sort of messenger of their Blood God.\n\nI seized the advantage and played into their primitive beliefs.\n\nI came here intending to open trade and learn how we can work with them against the Horde.\n\nWhat I discovered was altogether more compelling. I will show you.", objectives = "" }
WordHunterWoW_QuestEN[51190] = { title = "Granting a Reprieve", description = "Now, on to more pressing matters.\n\nThe Forsaken have shown up and are preventing us from saving our people. All my soldiers are either injured, exhausted, or in no shape for fighting.\n\nIt seems these trollish natives have joined them as well. I am spread too thin.\n\nKill the Horde. Kill the Zandalari. Kill them all.", objectives = "" }
WordHunterWoW_QuestEN[51191] = { title = "Save Them All", description = "Reinforcements? Ah thank tha Light!\n\nWe done the best we can triaging the injured, but we need help. We need more hands that can heal wounds or at the verra least apply bandages.\n\nHow are yer hands? Here, take these bandages and do what ye can tae treat tha injured.", objectives = "" }
WordHunterWoW_QuestEN[51192] = { title = "A Lack of Surplus", description = "Food, wood, cloth... we're short on everything. Of course, I'm always short, but that donna stop me.\n\nHeh.\n\nSee what ya can salvage from tha shipwrecks.", objectives = "" }
WordHunterWoW_QuestEN[51193] = { title = "That One's Mine", description = "Yer here to help? I donna have anything... Well, maybe I do.\n\nI know it's just a simple hammer. I know it's not special. But it's mine.\n\nThat disgustin undead, Alan Hawkins, is taunting me wi'it. I promised Feorea I wouldna run off tae fight him, but ye made no such promises.\n\nKill him and retrieve me hammer.", objectives = "" }
WordHunterWoW_QuestEN[51199] = { title = "The Glory of the Hunt", description = "You here for the festival, friend?\n\nWe're still settin' up here, but the hunt should've started by now!\n\nIf ya want to take part, go meet Abbey in Foxhollow Woods. She'll get you all set up.\n\nHappy huntin'!", objectives = "" }
WordHunterWoW_QuestEN[51200] = { title = "The Black Sheep", description = "I'll admit, Millie has never really been one to follow the herd. Usually, it's no problem. She'll wander off for a bit, do her own thing and eventually make her way back to the flock.\n\nThe hills have grown increasingly more dangerous lately, especially with the wolves and giants about. She's been gone awhile and I'm starting to worry.\n\nCould you please help me look for her?", objectives = "" }
WordHunterWoW_QuestEN[51201] = { title = "The Troll's Tale", description = "You've arrived at an... interesting time, {class}. All of my ships have been destroyed. Half of my men are feeding the fishes, and the rest aren't doing much better. We're as good as doomed.\n\nAnd still, the Alliance prevails.\n\nThese Zandalari trolls are to blame for this carnage. I need to know how they did it before we kill them all and escape from this Light-forsaken island.", objectives = "" }
WordHunterWoW_QuestEN[51203] = { title = "Cry Wolf", description = "Lately, the wolves have been terrorizing my flock. They weren't an issue until the giants moved in and pushed them out of their normal hunting grounds.\n\nI feel bad asking you to do this, but could you thin their ranks a bit? If there are fewer wolves competing for food, maybe they'll leave us alone.", objectives = "" }
WordHunterWoW_QuestEN[51204] = { title = "WANTED: Razorclaw Alpha", description = "Adventurers Needed!\n\nThe wolves have been attacking my flock! I don't have the means to fight them back.\n\nI've seen one, much larger than the rest, leading a few of the attacks.\n\nPlease, if anyone can help, I'll gladly offer whatever reward I can muster.\n\n- Shepherd Mary Ann Milbrooke", objectives = "" }
WordHunterWoW_QuestEN[51205] = { title = "Aww, Rats!", description = "I didn't sign up for this! I just want to get back to the simple things, like grinding wheat and drinking mead.\n\nAs if things couldn't get any worse around here, there's an army of rats ransacking the shed and I don't have the stomach to exterminate them.\n\nHere, I got this off some crazy gnome that stopped into port recently. I thought maybe it'd help with the bees. Maybe you can try it on the rats?", objectives = "" }
WordHunterWoW_QuestEN[51207] = { title = "Ettin It Done", description = "Okay, now here's a little something I whipped up for you with those extra ingredients.\n\nWe don't have much around here in the way of weapons, but we've got gunpowder and plenty of flour. A surprisingly explosive combination!\n\nToss one of these goodies at those nasty ettins, should disorient them long enough to give 'em a good whack upside the head!\n\nYou thought I was just a sweet old lady, baking delicious cookies for any ol' passerby? Hah, I'll have you know I was quite the firecracker in my day.", objectives = "" }
WordHunterWoW_QuestEN[51208] = { title = "Wheat A Minute", description = "With the storage shed ransacked by rats and the giants pillaging our shipments, we've been running low on food.\n\nWhen I was making my way out here, I saw a bunch of grain sacks littered about, near the wrecked wagons.\n\nI'd appreciate it if you could retrieve whatever you find while you're out here.", objectives = "" }
WordHunterWoW_QuestEN[51209] = { title = "Mighty Grokkfist", description = "Grandma is always telling me I need to toughen up a little... how easy we've got it these days.\n\nI read a story about giants that are terrified of rats, so I thought, \"Hey Charles, here's a great idea, let's take all those rats {name} gathered and let 'em loose on the ettins.\"\n\nI tried to be tough for once, but look how it turned out. Now, I'm stuck out here, just hoping I don't get squashed.\n\nTheir leader is just up the hill there. Here, take the rats with you and let's hope I was right!", objectives = "" }
WordHunterWoW_QuestEN[51211] = { title = "The Heart of Azeroth", description = "Our world's dyin', {name}. Sargeras's sword has cut deep. Her pain is drivin' the elements into a frenzy!\n\nI can hear Azeroth's voice, but she needs more than her speaker.\n\nShe needs her champion.\n\nFar below us lies an ancient titan vault called the Chamber of Heart. I sense she wishes tae speak tae ye there.\n\nCome with me into the chamber. It may be our only chance tae save her!", objectives = "" }
WordHunterWoW_QuestEN[51214] = { title = "Be A Dear", description = "As you can plainly see by the rocks falling from the sky, we are under siege by those terrible ettins!\n\nIf you could be obliged to lend us a hand, I'd be most grateful. We can't possibly hope to defeat them unless we properly prepare you first.\n\nCould you be a dear and fetch a few things for me from around the Hamlet? Some water, a sack of flour, and a bundle of logs should help.\n\nI've already sent my grandson, Charles, off to fetch a few other items. I've not seen him for quite a while though.", objectives = "" }
WordHunterWoW_QuestEN[51215] = { title = "Milking Goats", description = "Unfortunately, Milbrooke's flock hasn't been producing lately. What with all the wolves about, the poor things must be terrified.\n\nWild goats wander the hills, and they are quite fearless compared to the sheep. \n\nIf you can find a few with young ones about, you may be able to persuade them to offer some fresh, delicious goat milk!", objectives = "" }
WordHunterWoW_QuestEN[51217] = { title = "WANTED: Yarsel'ghun", description = "By the decree of the Storm's Wake.\n\nFind and kill the foreign spy, Yarsel'ghun. \n\nA foreigner agent hiding on our soil, she is responsible for acts of terrorism against the citizens of Stormsong.\n\nThe individual that ends her existence will earn a fitting reward.", objectives = "" }
WordHunterWoW_QuestEN[51218] = { title = "Undelivered Package", description = "< The ransacked cart has obviously seen better days. A single package remains, obscured by the spilled grain. It's addressed to Marie Davenport of Millstone Hamlet. >", objectives = "" }
WordHunterWoW_QuestEN[51220] = { title = "Deep Sea Venture", description = "As mighty as Ai'twen is, this Venture Company is still a threat to him. I need you to watch over Ai'twen and Toki as you continue your great adventure.  \n\nEliminate the Venture Company Seawrenches that lurk the waters you travel to.", objectives = "" }
WordHunterWoW_QuestEN[51221] = { title = "Response Required", description = "Time is short and more creatures will die without your help. The Venture Company prepares a huge digging machine to tear the reef apart and destroy this cave. They've assigned a special operative to be sure the job is done right.\n\nYou must act now, {name}. Take out the operative in charge of the camp; this should buy us some time.", objectives = "" }
WordHunterWoW_QuestEN[51222] = { title = "What's Yours is Mined", description = "During a visit to Pandaria, I witnessed the citizens of Halfhill defeat attacking hozen by flinging the hozen's excrement back at them.  \n\nThe hozen were unprepared to face the wrath of their own weaponry used against them. A similar strategy can be applied here. We will gather Venture Co. Sea Mines and use them against the invaders.  \n\nYou hook ropes to each mine, and Ai'twen and I will haul them up.", objectives = "" }
WordHunterWoW_QuestEN[51224] = { title = "Profit and Reconnaissance", description = "This was supposed to be a covert operation. Unfortunately, our Trade Prince insisted on coming along... with the loudest, most conspicuous vehicle the Horde has ever conceived.\n\nAt least you're here with me, {name}.\n\nLet's get going, then. We know next to nothing about the Drustvar territory. It's time to do some recon.", objectives = "" }
WordHunterWoW_QuestEN[51226] = { title = "Death from Two Sides", description = "The overgrown lizards from down on the beach decided to swarm the camp suddenly. \n\nWe're used to dealing with one or two each week, but it seems like the whole brood came up the cliff. Wonder if the smell of blood drew them in.\n\nThey're putting our remaining men at risk, wipe them out!", objectives = "" }
WordHunterWoW_QuestEN[51229] = { title = "Establish a Beachhead", description = "I won't allow Private Leonard's sacrifice to be in vain. Let's get our men out here and fortify this place up before those... \"sethrak\" decide to come back.\n\nHere, plant this banner somewhere visible so the ship knows its safe. That platform over next to the dock should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[51230] = { title = "Emergency Transplants", description = "Riverbud is a precious resource for us. Not only does it have potent magical properties, but it also feeds many of de beasts we train or eat ourselves.\n\nHowever, de Blood Trolls have been dumping a lot of cursed blood in de rivers. It may not be their goal, but if we do not act soon, de pollution may wipe out all de riverbud.\n\nI need you to take dis handful of seeds, and plant dem in de rivermud. In exchange, I will teach you how to harvest it more effectively.", objectives = "" }
WordHunterWoW_QuestEN[51231] = { title = "Wiccaphobia", description = "Do you see that... that shape up in the brambles up ahead? Is that... <Eitrigg shudders.>\n\nIs that goblin... wrapped up in that tree?", objectives = "" }
WordHunterWoW_QuestEN[51233] = { title = "I Hope There's No Witches in the Mountains", description = "<Gallywix looks flustered after his ordeal with the crone.>\n\nYou know, ah... I think maybe we better set up our foothold somewhere else. Maybe, up in the mountains? You know, like... not here, where the witches are?", objectives = "" }
WordHunterWoW_QuestEN[51234] = { title = "Krazzlefrazz Outpost", description = "I already did a bunch of the leg-work for settin' up our foothold. All we gotta do is finish deploying all the instant-base technology, and we'll be good to go here in Drustvar.\n\nWhy don't you go finish the base building. I'm gonna see if I can salvage any wolfercycle parts.", objectives = "" }
WordHunterWoW_QuestEN[51240] = { title = "WANTED: Anchorface", description = "Kill the blasted shark that ate me legs! And me crew! And me boat - even the anchor!\n\nHe's been swimming around in the sea, looking for his next meal. Kill 'im.\n\nI've left a reward with Cesi Loosecannon if you do.\n\n<The poster is signed 'Captain Slagbolt'>", objectives = "" }
WordHunterWoW_QuestEN[51243] = { title = "Breaking The Food Chain", description = "De extra riverbud you planted has helped, but it has not been enough.  Some of de local beasts are consuming de riverbud before dey can mature. We need dese plants to germinate, or we could risk losing it entirely.\n\nThe largest group of young riverbud consumers are de jacunda. If we are going to give de riverbud a chance to survive dis, you will need to thin their numbers.\n\nDo dat and I will teach you everything I know about riverbud.", objectives = "" }
WordHunterWoW_QuestEN[51244] = { title = "What Rots Beneath", description = "Good job killin' Ateena and sendin' whatever dat construct was down ta da bottom of... whatever dis ting be.\n\nMe scouts be seein' Titan Keeper Hezrel marchin' down to sometin' called da Altar of Rot.\n\nNow dat we got rid of dat construct, we can be flyin' down dere ta see what Hezrel be up to. \n\nDis be best handled by you and me. Da princess be havin' business back in da city.", objectives = "" }
WordHunterWoW_QuestEN[51246] = { title = "The Wreckoning", description = "I can't believe any of them survived the wreck. We were told to prevent any survivors from gaining a foothold.\n\nThere are far more of them than expected. We need to weaken their forces.\n\nWell? What are you waiting for? An engraved invitation?", objectives = "" }
WordHunterWoW_QuestEN[51247] = { title = "The Things They Carried", description = "We need to know more about these sailors before we report back.\n\nIdeally, we would invade their camp but there are too many for our small group to take on. Lucky for us, they are focused on their salvage operation over safety. See if you can find any intelligence on their leaders who are scavenging the derelicts.", objectives = "" }
WordHunterWoW_QuestEN[51248] = { title = "Productive Pests", description = "This jungle is a whole new habitat for creatures and critters. A shame we're here to deal with Alliance driftwood.\n\nI've got an idea and I think it's genius. Two words: Poison bugs.\n\nFirst, I need some bugs. Crawling and flying ones, just to be thorough for our test.", objectives = "" }
WordHunterWoW_QuestEN[51249] = { title = "Crabulous Feast", description = "The Forsaken didn't bring any food with them. I think they might be cannibals. At the very least, they don't need to eat!\n\nTeekay and I are going to starve out here! {name}, if you're not too busy, could you bring us something to eat?\n\nMaybe some fresh crab?", objectives = "" }
WordHunterWoW_QuestEN[51251] = { title = "Basement Dwellers", description = "Ever since the untimely passing of dear, sweet Lizzie, rest her soul, the pests have multiplied like crazy!\n\nIn recent days, giant spiders have begun crawling out of the cellar underneath the southern mill. \n\nNo one has been able to go down there, for fear of being wrapped in web and eaten alive!\n\nWould you mind squashing a few arachnids and collecting any silk you find?", objectives = "" }
WordHunterWoW_QuestEN[51278] = { title = "Lost and Forgotten", description = "We have seen firsthand the depravity that has taken hold of my former brethren. The time has come to put an end to it.\n\nThe path ahead is no doubt packed with Lord Stormsong's cultists and their soulwrought elementals. I will absorb their souls as they fall with the Dead Ringer, as you once did.\n\nHowever, there will be no release for these fiends... not this time. We will need them to pry open the final door to the Shrine.", objectives = "" }
WordHunterWoW_QuestEN[51279] = { title = "Nazmani Cultists", description = "The rumors o' the blood trolls from back in Boralus don't line up with the letters from Captain Conrad.\n\nOpen to trade? Willin' to work with us against the Horde? Ready to teach us their magic?\n\nHogwash.\n\nOnly time worth spendin' with these evil trolls is time killin' 'em.", objectives = "" }
WordHunterWoW_QuestEN[51280] = { title = "Offerings to G'huun", description = "Been watchin' these cultists with both good eyes.\n\nThose big glowin' jars o' theirs look important.\n\nOpened one up and it sent a shiver down me spine, but nothin' seemed worth the takin'.\n\nIf it ain't worth stealin', I guess it's worth smashin'.", objectives = "" }
WordHunterWoW_QuestEN[51281] = { title = "Zul'Nazman", description = "Not sure if I like this Harry fella. He's growin' on me, though. Got some wild ideas about the blood elves, but he's not all bad.\n\nWhat were we talkin' about? Ah, right.\n\nCaptain Conrad. He said the Captain went to Zul'Nazman ta commune with the blood trolls there. Seems... less than well planned.\n\nLet's go see what there is to see, shall we?", objectives = "" }
WordHunterWoW_QuestEN[51282] = { title = "Captain Conrad", description = "Looks like there's couple o' guards posted by this hut. If I had ta guess, Captain Conrad'll be in there.\n\nSomethin' still feels off about this place, though. Why don't ya go on ahead and I'll hang here in case things go south fast?\n\nI got yer back, {name}.", objectives = "" }
WordHunterWoW_QuestEN[51283] = { title = "Voyage to the West", description = "Reconnaissance reports that the Horde has made inroads into the desert of Vol'dun.\n\nWe can't allow the Horde to continue to work there unchecked, so we're preparing an expedition to establish a beachhead.\n\n{name}, as one of our most accomplished soldiers I'd appreciate if you joined us. Your help will be essential for the success of our mission.\n\nWrap up your affairs here in the harbor and report to Grand Admiral Jes-Tereth. We will set sail when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[51286] = { title = "Stop the Evacuation", description = "This is a complete disaster. The intelligence you gathered seems to indicate that they already have footholds on this island and this is just another one.\n\nThey have a boat and we need to stall them. Here's some seaforium. Plant it on their boat and sabotage their hopes of escape. If possible, take out their Captain leading the evacuation.", objectives = "" }
WordHunterWoW_QuestEN[51302] = { title = "The Underrot: Sealing G'huun's Corruption", description = "Massive leak of G'huun corruption located nearby. Substance surrounding us indicator of G'huun corruption, named underrot.\n\nInitial scans suggest a massive abomination composed of underrot is ahead, releasing more corruption into Nazmir.\n\nMust destroy Unbound Abomination, contain G'huun's corruption.\n\nFunction clear. Proceed inside.", objectives = "" }
WordHunterWoW_QuestEN[51308] = { title = "Zuldazar Foothold", description = "King Wrynn passed along orders to dispatch our finest to establish a foothold in Zandalar. That means you.\n\nFortunately, we have a few choices as to where we can set up camp.\n\nStick around. I'll go over the battle plan.", objectives = "" }
WordHunterWoW_QuestEN[51309] = { title = "Rocks of Ragnaros", description = "With me shaman still in their conveyances, a vital component o' our upcomin' ritual remains scattered among the supplies.\n\nI can only hope the Horde haven't taken 'em. They're rare an' precious...\n\nIf you see any glowin' objects out there, recover 'em. They're o' tremendous value.", objectives = "" }
WordHunterWoW_QuestEN[51310] = { title = "Raiders of the Lost Crop", description = "I could use a hand here!\n\nSo there I was, mindin' my own business and collectin' my harvest when these big galoots show up on their wolves and start torching the town! Luckily I was delivering a sack o' grain, or they'd have caught me and run me down!\n\nI won't stand for having these orcs or their dogs chewing up my fields or my crop.\n\nWhat do you say, friend? Help a farmer run some looters off his land?", objectives = "" }
WordHunterWoW_QuestEN[51312] = { title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead bug absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Declan about it, he might have an idea.", objectives = "" }
WordHunterWoW_QuestEN[51313] = { title = "Learn From the Best", description = "You want to learn how these bees are so good at harvesting pollen, but if you show up, they'll start swarming you.\n\nWhat you've got is a problem that can be solved with a little alchemy.  I just so happen to have this potion that, once drunk, will turn the imbiber into a plant.\n\nHere's the deal: you go out and drink the potion, and you'll see firsthand how the bees do what they do. After the potion wears off, you tell me what happened.\n\nOh, and don't ask why I have that potion on me.", objectives = "" }
WordHunterWoW_QuestEN[51314] = { title = "Grain Drain", description = "We've got to salvage what we can.\n\nThis valley is the breadbasket of Kul Tiras. We feed the citizens, the militia, the army, you name it! Perhaps you've heard of our famous Kul Tiran sourdough bread? Goes great with sausages.\n\nMore importantly, those blasted Horde are getting in the way of our harvest! Lucky for us, the golems work 'round the clock to package the grain.\n\nI just need you to go out to the fields and grab as many bags as you can carry. I'll pay you for your trouble, of course.", objectives = "" }
WordHunterWoW_QuestEN[51319] = { title = "The Final Ascent", description = "Beyond this gate lies Lord Stormsong... and our retribution. It seems he has sealed it tight, likely to buy himself time to finish whatever foul ritual awaits us.\n\nRelease the souls within the Dead Ringer when you are ready. I will direct them into the binding holding the gate shut.\n\nFrom there, we find Stormsong and end this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[51320] = { title = "Sealed Fate", description = "Three wards ahead threaten to block our entry into the Shrine. We call them the Tidemother's Wrath, Radiance, and Pride.\n\nLegends say the wards were gifts from the sea itself. They once protected our flagships against even the fiercest storms. Ever since we settled here they have instead kept the Shrine of the Storm safe.\n\nIt seems Lord Stormsong has turned their power against us. I can feel their energy radiating out even from here, protecting his forces from our magic.\n\nWe must destroy them.", objectives = "" }
WordHunterWoW_QuestEN[51331] = { title = "Mole Machinations", description = "Seems the enemy's anticipated our moves. While we developed our refinin' techniques for Azerite, the goblins 'ave done the same.\n\nIt wasn't five minutes after we established ourselves here that the Horde arrived to disrupt our progress.\n\nWe've got several shaman of great import waitin' impatiently in the mole machines on that beach.\n\nYou can take the key and clear the way so they arrive safely.", objectives = "" }
WordHunterWoW_QuestEN[51332] = { title = "A Trip Across the Ocean", description = "I understand you are to be establishing our foothold in Drustvar. You will be assisted on this mission by Trade Prince Gallywix.\n\nI know, a strange choice, but I am told that there is Azerite in Drustvar, and the Trade Prince was insistent.", objectives = "" }
WordHunterWoW_QuestEN[51335] = { title = "Cookies and Cream", description = "Thank you for helping me collect everything. \n\nI couldn't let you go out there and battle those mean ettins on an empty stomach. Now, I would be no better than those terrible monsters if I did that, would I?\n\n{name}, you just feel free to take a load off while I make you a fresh batch of cookies and some warm milk!", objectives = "" }
WordHunterWoW_QuestEN[51339] = { title = "Cleaning Bills", description = "The Venture Company contaminates our pristine waters with toxic oil.  \n\nMy people are strong and will endure this until the time is right to strike back. The creatures with soft skins cannot wait. We must act now and save them from this danger.\n\nCollect and scrub clean any oily sandbill pipers you see. Quickly, before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[51340] = { title = "Drustvar Ho!", description = "Azerite's in the air, {name}. Can ya smell it?\n\nDrustvar--way over in Kul Tiras--apparently has a real big seam o' Azerite beneath it. Azerite means profit, and profit means winning this war against the Alliance... which means even more profit.\n\nWe gotta get that Azerite!\n\nCheck in with Eitrigg an' Tattersail so we can get going soon. Time is money!", objectives = "" }
WordHunterWoW_QuestEN[51341] = { title = "Daughter of the Sea", description = "They're not letting us any closer to the keep. We'll have to walk from here.\n\nReturning to Boralus has stirred feelings I thought I'd left behind. Memories smoothed away by the years like stones in the tide.\n\nIt all feels raw again.\n\nI do not know how this will end--only that we must try.", objectives = "" }
WordHunterWoW_QuestEN[51343] = { title = "Swimming Lessons", description = "For millennia we have roamed Azeroth's depths, yet never has a land walker journeyed with us. In order to help us, you must learn to travel the waters as we do.\n\nThe three scrolls of the sea shall grant you the energies to travel and survive underwater as we do.\n\nBring me the Scrolls of Harmonious Fins, Endless Tides and Graceful Breaths.", objectives = "" }
WordHunterWoW_QuestEN[51344] = { title = "To Matters at Hand", description = "Ye need te get back te Zuldazar, Princess Talanji's people are in desperate need of help.\n\nNow that ye got the heart, ye can absorb Azerite from all kinds of sources.\n\nUse the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here.\n\nJust remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.", objectives = "" }
WordHunterWoW_QuestEN[51349] = { title = "Honor Bound", description = "Sergeant Ermey is a man of honor, he would never leave one of his men behind. But one of these days that sentiment is going to get himself killed. \n\nWe don't even know what threats we face in this land. We certainly don't have the resources to spend searching for a missing private.\n\nI want you to go after him. Do whatever it takes to give up this fool's errand and return to the camp. He was last seen headed to the south-east, I'd start your search there.", objectives = "" }
WordHunterWoW_QuestEN[51350] = { title = "Unexpected Aid", description = "I was shadowing those sethrak when I saw this one left for dead beside the trail. I don't think he's like the others. Looks like they roughed him up pretty bad.\n\nI made contact and before he passed out he said he knew where our man was being taken!\n\nWe need to find out what this thing knows!\n\nI'll need to make a salve for these wounds. There's some cactus I saw growing around here that should make a good base for it.", objectives = "" }
WordHunterWoW_QuestEN[51351] = { title = "Poisoned Barbs", description = "I'm surprised this snake-man is alive, let alone able to speak. Look at this! \n\n<Ermey holds up a needle-like barb.>\n\nIt looks like it came from one of those giant insects wandering about in the bottom of the gulch. I'll bet my stripes it's poisoned.\n\nYou know what they say, that which kills can also cure.\n\nGo get a few more of these barbs. I bet if I mix it in with that cactus he's wanting we will get a good antivenom to treat his wounds.", objectives = "" }
WordHunterWoW_QuestEN[51352] = { title = "Don't Play with Matches", description = "These Venture Co. thugs set flame to the very oils they harvest. They hope to drive us from this land.\n\nTheir plan has a flaw. If a great wave extinguished every torch, their oil could not be lit. You can be our great wave!\n\nExtinguish all the flames here, and we shall be victorious this day.", objectives = "" }
WordHunterWoW_QuestEN[51353] = { title = "Cave of Ai'twen", description = "Toki has researched a strategy that is historically sound. However to defeat the Venture Company, we will have to awaken Ai'twen from the bubble of tranquil waters.\n\nSeek out Loroja in the Cave of Ai'twen and we shall begin the process.", objectives = "" }
WordHunterWoW_QuestEN[51354] = { title = "Anger in a Bottle", description = "These quilboar are tougher than normal and I think I found out why.\n\nThey carry vials of some sort, filled with this nasty orange liquid. They'll quaff it and gain tremendous strength and stamina.\n\nI'll bet if we get some of it Hobbs could whip up a counter-agent, or whatever it is that alchemists do. Either way, deprive them of their strength potions and it'll make getting around here easier!", objectives = "" }
WordHunterWoW_QuestEN[51355] = { title = "Secretest Fish", description = "<Danielle Anglers in Mechagon may be interested in this fish.>", objectives = "" }
WordHunterWoW_QuestEN[51356] = { title = "WANTED: Sister Lilias", description = "The Waycrest Guard seeks an able-bodied soldier to eliminate a threat in Corlain.\n\nA witch by the name of Sister Lilias is wanted for the torture and killing of many of our townsfolk. Her end would prove a boon to all of Drustvar.\n\nPresent her head to claim your reward.", objectives = "" }
WordHunterWoW_QuestEN[51357] = { title = "Armed and Ready", description = "You must be special if the sethrak didn't kill you right away.\n \nEither that, or you'd fetch a good price at the slave market.\n\nDon't worry though. We're getting out of here.\n\nI have a wagon at the entrance, but no weapon to fight with.\n \nLuckily, it seems the sethrak have plenty.", objectives = "" }
WordHunterWoW_QuestEN[51358] = { title = "WANTED: Gryphon 'Nappers", description = "A warning to all gryphon owners!\n\nDo not let your feathered companions out of your sight. We have received numerous reports about gryphons in the area being stolen in the night.\n\nIf anybody can track down and stop these thieves, a reward awaits!", objectives = "" }
WordHunterWoW_QuestEN[51359] = { title = "Fragment of the Firelands", description = "The rumors o' yer capabilities seemed overblown, but it appears yer indeed a competent one, aren't ye?\n\nI underestimated ye, {name}. For that, I apologize. Don't tell Thaelin.\n\nThe components for the ritual are now prepared. All ye need to do is add the Firelands Slag to the Unstable Magma an' a great bein' from the Firelands will heed our call.\n\nYou'll gain control o' it and can eliminate the nearby goblin threat with nigh invincibility.", objectives = "" }
WordHunterWoW_QuestEN[51360] = { title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.", objectives = "" }
WordHunterWoW_QuestEN[51361] = { title = "More Anchor Pods", description = "Everyone in Kul Tiras knows that anchor weed is a blight that was brought here by merchants.\n\nIt thrives in this weather and it leechs nutrients from other plants, so we work to keep it from spreading, but it also has a strong magical essence, keeping us from just eradicating it.\n\nHowever, if it has mutated so it can disperse more seeds, we may need to finally purge it.\n\nBring me the biggest seed pods you can find, we need to see if this is a unique case. I'll dissect this one and learn what I can.", objectives = "" }
WordHunterWoW_QuestEN[51364] = { title = "An Explosive Exit", description = "Alright, {name}. I think it's time we make a run for it. \n\nHopefully my wagon's still nearby.\n\nI'll steer us to our hideaway. I just need you to lob explosives onto any sethrak who are brave enough to follow us.", objectives = "" }
WordHunterWoW_QuestEN[51365] = { title = "Cultural Significance", description = "I've noticed your skill with harvesting plants has improved, but I also noticed that you just treat each flower and leaf as a commodity.  The flora of these islands have a rich history, with a deep cultural significance to us.\n\nTake this sea stalk, go around town, and ask some of the men and women what it means to them.  Humor me, and I'll make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[51366] = { title = "Antidote Application", description = "The antidote's ready. \n\nIt smells like death and tastes worse, but it should be potent enough. Let's hope that we're not too late for it to do any good.\n\nHere, administer the salve to his wounds. It should work nearly instantly.", objectives = "" }
WordHunterWoW_QuestEN[51367] = { title = "WANTED: Raging Earthguard", description = "Be careful when traveling toward Anglepoint!\n\nAn immense creature of the earth has spawned on one of the hills, threatening all who go near.\n\nAny adventurers who take down this earthen guardian shall be rewarded greatly.", objectives = "" }
WordHunterWoW_QuestEN[51368] = { title = "WANTED: The Hornet", description = "That's it, I'm putting a bounty on that blasted hornet.\n\nEvery time I try to do some good old fashioned bare-handed fishing, that son of a bear comes after me.\n\nSomebody take that bug down!", objectives = "" }
WordHunterWoW_QuestEN[51369] = { title = "Friends in Strange Places", description = "I saw a creature like your friend here. We both were being held captive by my ruthless kin, the Faithless.\n\nBefore I was cast aside I gave him something to protect, something most precious. Naturally, I would also like to see your friend's safe return.\n\nMy people will lend you their aid.  Come, I will call for my pterrordax to take us. Together we shall find where your soldier friend was taken.", objectives = "" }
WordHunterWoW_QuestEN[51370] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[51371] = { title = "Flavorable Offering", description = "Ai'twen saved many Tortollans during the great purge of the Inky Grotto. He rests here in this tranquil bubble as a reward for his service.  To entice him back to our world we'll need a flavorful offering.\n\nThe seaweed that grows outside is Ai'twen's favorite meal. Its salty flavor will surely coax Ai'twen to leave the bubble for our world. Gather it from the creatures outside this cave, and where it grows wild on the reef.", objectives = "" }
WordHunterWoW_QuestEN[51376] = { title = "Can't Teach on an Empty Stomach", description = "I would love to teach you, but it's so hard for me to concentrate right now.  I haven't eaten anything all day, so it's all I can think about.\n\nHowever, if a helpful adventurer were to fish up some lane snapper from the ocean just behind me, I would owe them a something in return.  Perhaps something valuable, such as advice in regards to effectively picking the notorious winter's kiss.\n\nIf you don't feel like fishing, you could just buy some on the auction house, I don't mind.", objectives = "" }
WordHunterWoW_QuestEN[51380] = { title = "Back to Franklin", description = "Oh, good! You are still here!\n\nI heard you had built a rapport with Franklin. I'd be lying if I said talking about him didn't make me reminisce when we worked together.\n\nIf you're not busy, could you go talk to him? Ask him if he can show you anything else. I'm sure he remembers more, if you're still looking for more information.\n\nAnd tell him that if he were to get his life sorted out, I'd like to talk to him about working together again.", objectives = "" }
WordHunterWoW_QuestEN[51384] = { title = "WANTED: Quartermaster Ssylis", description = "Don't venture too far into the bay if you're not looking for a fight!\n\nA couple of Bilge Rats have taken up residence in a nearby cave, and they won't stand down from any challenge.\n\nThey ain't harming anybody, 'long as you stay away. But if somebody wants to go take care of their leader, they will be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[51386] = { title = "Battle Victorious", description = "We have everything necessary to strike a blow against this Venture Company. \n\nOur plan is sound, we are well prepared and we have the element of surprise.\n\nWe shall ride atop Ai'twen and reign chaos upon them with their very own weapons.", objectives = "" }
WordHunterWoW_QuestEN[51389] = { title = "Breaking Free", description = "Look, these guys are in a tough spot but let's not lose track of the mission. We've got to rescue Private James!\n\nI saw a bunch of cages down in the camp of those snakes that are besieging the temple. If James is going to be anywhere, then it'll be there!", objectives = "" }
WordHunterWoW_QuestEN[51390] = { title = "WANTED: The Crimson Cutthroats", description = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments.\n\nA reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", objectives = "" }
WordHunterWoW_QuestEN[51391] = { title = "Defang the Faithless", description = "Did you see them as we flew in? The Faithless are sieging the temple! \n\nFriend, I know we just met but I must ask for your aid once more. Please, help us break their ranks!", objectives = "" }
WordHunterWoW_QuestEN[51394] = { title = "Break the Siege", description = "This isn't the first time the Faithless have attacked us, nor will it be the last, but the temple must be protected!\n\nPlease, do whatever you can to destroy their siege equipment and push them back.", objectives = "" }
WordHunterWoW_QuestEN[51395] = { title = "The Keepers' Keys", description = "It's good to see that your companion is back unharmed.\n\nBut more importantly, let's see if he still has my stone hidden in his pockets.", objectives = "" }
WordHunterWoW_QuestEN[51398] = { title = "An Unusual Mentor", description = "Hey {name}, you look like you're ready to handle hostile territory.\n\nFar away in the desert of Vol'dun, on the continent of Zandalar, there grows a plant called akunda's bite. You couldn't pay me enough to go there myself, and there's almost no mention of them in any of the books I've read, but all is not lost.\n\nI know of an herbalist who lives there in the desert and studies that plant.  Find him, and I'm sure he'll be able to teach you a thing or two. Oh, and do be warned...\n\nHe is a bit... eccentric.", objectives = "" }
WordHunterWoW_QuestEN[51399] = { title = "Foul Harvest", description = "You have traveled far to find knowledge, but you have found me instead. I am curious though, how much further you would travel for it. I will teach you, if you do something for me first.\n\nIron sharpens iron, as they say, so too does adversity strengthen the seed.\n\nGo out and find seeds, ones that have been consumed by the wild beasts and have returned to the earth unscathed.\n\nOnly those seeds will be strong enough to survive the desert sands of Vol'dun.", objectives = "" }
WordHunterWoW_QuestEN[51401] = { title = "Carry On", description = "Let's get to Brennadam right away. We need to find Brother Pike and get to the bottom of all of this before things get any worse.\n\nThis road should take us right into town. Brennadam's the busiest market this side of Boralus, so there should be plenty of people there who can help us find Pike.\n\nReady when you are!", objectives = "" }
WordHunterWoW_QuestEN[51402] = { title = "Reporting In", description = "I can't believe what we got ourselves in the middle of here. Keystones, C'Thraxxi, there's even a snake-man civil war going on!\n\nAll I know is Wyrmbane is going to want a full report and if there's anything I hate more than inept privates getting themselves captured it's paperwork.\n\nLet's get going.", objectives = "" }
WordHunterWoW_QuestEN[51404] = { title = "What Happens Next", description = "After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it.\n\nIf you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.", objectives = "" }
WordHunterWoW_QuestEN[51407] = { title = "Find Their Words", description = "This portal will get you quickly back to the outpost.\n\nWhen there, present the orders to Akru. \n\nHer knowledge is vast, she will be able to discern the truth within.", objectives = "" }
WordHunterWoW_QuestEN[51408] = { title = "Giving Back to Nature", description = "Perform one additional task, and I will give you the knowledge you seek. The seeds you have are strong, but they need time until they are ready to grow. \n\nHowever, one must always be prepared in the desert. This sapling is mature enough to live on its own, but it is frail. It needs the dry desert winds to build static so it may bite, but until it does, it is as helpless as grass.\n\nPlant it in the desert sands, near the fallen beast south of the Brine Basin, and protect it until it can defend itself.", objectives = "" }
WordHunterWoW_QuestEN[51418] = { title = "Xibala", description = "{name}! How's things going over here?\n\nOh. Wow. There's Horde soldiers everywhere. And Zandalari trolls. And hardly any machines at all.\n\nWe should DEFINITELY head back to Xibala, with the dark iron dwarves. It's perfect for our foothold!", objectives = "" }
WordHunterWoW_QuestEN[51421] = { title = "Shiver Me Timbers", description = "It seems our resident shadow hunter has managed to seize a small pirate sloop.\n\nWe have sent him to Tiragarde Sound in a search for a foothold, and it seems that he has concocted a plan.\n\nTy'jin has requested your help, personally. Do not keep him waiting.", objectives = "" }
WordHunterWoW_QuestEN[51425] = { title = "There's No Place Like Home", description = "So, the Arathi Highlands. Quite a sprawl, isn't it?\n\nAt some point, you may wish to return to this fair Stromgarde with haste.\n\nMight I offer a suggestion as to how...?", objectives = "" }
WordHunterWoW_QuestEN[51426] = { title = "Inspection Gadget", description = "Some time ago, a good friend of mine who had a tinker shop in Boralus just stopped all correspondence. With the state of foreign affairs, I wasn't able to look for him myself until recently.\n\nIt's not just him. It seems that all of the gnomes that were living in the city just up and vanished.\n\nI've decided to start my search with these ruins, but the machines here have gone haywire. Could you go get a good magnetic reading on the place?", objectives = "" }
WordHunterWoW_QuestEN[51427] = { title = "I Like Turtles", description = "Excellent work, {name}.\n\nPresent the offering to Ai'twen.\n\nHe will accept it and come to our aid.", objectives = "" }
WordHunterWoW_QuestEN[51430] = { title = "Reverse Tinkering", description = "The sentry bots here are definitely of gnomish make. If the creator had any sort of proper education, each machine should have some sort of serial code on it.\n\nAnd if they've been properly documented, I might be able to use those codes to track that gnome down.\n\nDo you think you could bring a few of them back to me?", objectives = "" }
WordHunterWoW_QuestEN[51432] = { title = "An Unusual Mentor", description = "You have done well so far, {name}, but dere is still much more for you to learn. I think it is time for you to meet an old 'friend'.\n\nDere is no better person I know of to teach you about akunda's bite, as his knowledge and respect for de plant is unrivaled.\n\nHead North beyond the desert of Vol'dun. Dere you will find a tortollan who will teach you more about de desert flower.", objectives = "" }
WordHunterWoW_QuestEN[51435] = { title = "Swashbuckling in Style", description = "First ting's first, boss-mon. Ya can't parley with pirates unless ya got da appropriate clothes.\n\nI ain't big on fashion, mon, but what ya be wearin' won't work.\n\nLuckily I collected dis box of pirate clothes. No need ta ask how. Just need ta get piratey.", objectives = "" }
WordHunterWoW_QuestEN[51436] = { title = "Parleyin' Wit Pirates", description = "Some a dese pirates be unhappy wit' da leadership.\n\nI been hearin' dey're da last truly free pirates. Da rest be sellin' out ta some lady named Ashvane.\n\nI don' really care 'bout dat, but da captain of dese Fogsail Freebootas  is tinkin' 'bout sellin' out too.\n\nWe gonna help stop it, and in return build a foothold here.", objectives = "" }
WordHunterWoW_QuestEN[51437] = { title = "Spike the Punch", description = "Step one in causing a mutiny? Make it seem like leadership is incompetent.\n\nIf the captain wants to sell our souls to the Ashvanes, we're going to need to get dirty.\n\nI hate to say it... but we've got to muck up the booze.\n\nThat'll make the crew angry at the captain before you can even blink.", objectives = "" }
WordHunterWoW_QuestEN[51438] = { title = "Marking Our Territory", description = "Dis could turn out ta be quite da foothold, boss-mon!\n\nI will help wit' da settlin', turnin' da place into a good base.\n\nI tink we need some spikes.\n\nLet's be makin' tings official.", objectives = "" }
WordHunterWoW_QuestEN[51439] = { title = "Cannonball Collection", description = "Walkin' through da harbor gave me some ideas, boss-mon.\n\nYa see dem big guys wit' da cannonballs?\n\nCollect some a dat ammo and bring it ta me. I tink I be havin' a use for it.", objectives = "" }
WordHunterWoW_QuestEN[51440] = { title = "A Change in Direction", description = "Whispers of dissent have been spreading through the harbor, {name}.\n\nYou can hear the grumblings of pirates who do not want to give up their freedom!\n\nRumor holds that some of the other authority figures have goals that align with mine.\n\nI forged some letters in the captain's hand. Deliver them... see who bites.\n\nOr who gets in our way.", objectives = "" }
WordHunterWoW_QuestEN[51441] = { title = "Thar She Blows!", description = "Our goblin engineers been workin' on modifyin' some cannons for our uses.\n\nDa cannonballs you been collectin' be perfect ammo for dem.\n\nDere are rowboats in da harbor dat be readyin' ta bring loot to Owings's enemies. Take dis cannon and sink 'em before dey can get away!", objectives = "" }
WordHunterWoW_QuestEN[51442] = { title = "I'm the Captain Now", description = "Alright {name}... It's time to take the mutiny to the captain.\n\nRhenik sits in his cave, readying himself to sell our souls to the Ashvanes!\n\nDefeat him, and I will allow you to use my port as though it were your own.", objectives = "" }
WordHunterWoW_QuestEN[51443] = { title = "Battle for Azeroth: Mission Statement", description = "{name}! The Warchief has summoned you to undertake a mission of the utmost secrecy.\n\nThe very future of the Horde is at stake.", objectives = "" }
WordHunterWoW_QuestEN[51445] = { title = "Thros, the Blighted Lands", description = "The Blighted Lands... \n\nIf the legends are true then inside we will witness suffering and torment the likes of which we have never known. ..\n\n...but if that is what I must endure to right what I have wronged, then I will cross that threshold gladly.\n\nWill you join me, {class}?", objectives = "" }
WordHunterWoW_QuestEN[51446] = { title = "Meet Sweetflower", description = "You have seen and learned much from these islands, but Zandalar is not de only place where you can learn. I have heard of a flower dat cannot grow on dese islands.\n\nIf you want to know more about it, you will need to find someone more knowledgeable dan myself. Fortunately for you, I know of someone who may be able to help you.\n\nHer name's Xun Xun Sweetflower, and last I heard she set up shop on the outskirts of Anyport over on de human island of Drustvar.", objectives = "" }
WordHunterWoW_QuestEN[51447] = { title = "Aromatic Pollenator", description = "While gathering the pollen, you found a dead wasp absolutely covered in pollen.  You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp.\n\nMaybe if you ask Jahden about it, he might have an idea.", objectives = "" }
WordHunterWoW_QuestEN[51448] = { title = "Learn From the Best", description = "You want to learn how these wasps are so good at harvesting pollen, but dey will defend their territory once you set foot inside it. Dis would be a problem, but I think I have a solution.\n\nTake dis potion and go to Vol'dun, to de Prickly Grove, and drink it to turn into a plant.\n\nHere's the deal: you go out and drink the potion, you'll see firsthand how the wasps do what they do. After the potion wears off, you tell me what happened.", objectives = "" }
WordHunterWoW_QuestEN[51451] = { title = "Disgustingly Damp Flower", description = "Rummaging for pollen as usual, you use the harvesting technique you learned from the wasps.  However, when you pull your hand away from the flower, you find that there is no pollen to be seen.\n\nLooking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all.  Upon closer inspection you see that the flower is filled with a viscous liquid.  Could the flower have done this?\n\nWhile unpleasant to touch, you carefully pluck the flower to show Jahden.", objectives = "" }
WordHunterWoW_QuestEN[51452] = { title = "Pollen Punching", description = "It looks like some beast managed to lap up all de pollen with it's tongue. It is curious as to what creature could have done dis, I doubt it matters.\n\nYou should be able to do dis yourself without needing any sort of rare or dangerous reagents.\n\nNext time you find a siren's sting, wet your glove so the pollen will stick to it. Water, wine, blood... It should not matter.", objectives = "" }
WordHunterWoW_QuestEN[51464] = { title = "Here In Spirit", description = "If you are up to de challenge, I have a task dat I believe is up your alley.\n\nDe spirits of dis land are screaming out in anguish. However, dey are either unwilling or unable to talk to me in their current state.\n\nI need you to get some fresh star moss, which will help anchor and calm their spirits. Once dey are calm, we will be able to give dem de help dey need.\n\nDo dis, and I will teach you how to harvest star moss more effectively.", objectives = "" }
WordHunterWoW_QuestEN[51465] = { title = "A Load of Scrap", description = "Hey there stranger, you want the scoop on the latest invention of the century?\n\nIt's called the Shred-Master Mk1 and this baby can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other doohickeys you adventurers wander around with.\n\nHere, take these pants and use the Shred-Master on 'em. You'll get the gist of it.", objectives = "" }
WordHunterWoW_QuestEN[51472] = { title = "Life Preserver", description = "The Thornspeakers were assisting me but they have troubles of their own.\n\nI came in search of a powerful dragon who fell in battle many centuries ago. Melting snows have revealed Vadekius's final resting place.\n\nMy Queen has tasked me with ensuring his body cannot be reanimated and enslaved. The ritual will require my full attention and my druid friends aren't fit for combat.\n\nWatch my back while I ensure my cousin's soul flies amid the branches of G'Hanir, safe from undeath.", objectives = "" }
WordHunterWoW_QuestEN[51474] = { title = "Forged in Fire an' Flame", description = "Ye've done more than I had any right tae ask, {name}. Recovered Ironfoe from our enemy, retrieved a fragment o' the Molten Core, an' exposed the enemy within our ranks at the Firelands.\n\nIf ye'd do me the honor, would ye come with us tae Blackrock Depths one last time while we repair our most sacred anvil?", objectives = "" }
WordHunterWoW_QuestEN[51478] = { title = "Ghost Busting", description = "I have spoken with de spirits. Most of dem were willing to bare their souls, calling for help from de living as dey are under attack from de blood trolls evil magic.\n\nDere was one, however, who seemed more angry dan most. It was furious dat we had not acted yet, dat we allowed things to get dis bad.\n\nGo to de Spirits Be With You inn at de port north of here and put dis spirit down, and in return I will teach you everything else I know about gathering star moss.", objectives = "" }
WordHunterWoW_QuestEN[51479] = { title = "The Uncorrupted", description = "This world is... not what I expected.\n\nIt is time for us to meet your warchief, {name}.\n\nThere is no need to delay any further.\n\nWe can lick our wounds once we have a roof over our heads.", objectives = "" }
WordHunterWoW_QuestEN[51480] = { title = "Enormous Anchor Pod", description = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it.\n\nYour mind wanders back to Jahden, and if there is anything about it in the book you picked up earlier.", objectives = "" }
WordHunterWoW_QuestEN[51481] = { title = "More Anchor Pods", description = "I need you to bring me a handful of mature anchor pods.\n\nYou see, dis seed pod is massive, but it is still just a seed pod. If we dissect it and take careful notes, we can learn about de normal, smaller seed pods and easily see how de anatomy works.\n\nI need you to bring me more of dese mature anchor pods.  If my theory is correct, den we could actually have a factual record for de future.", objectives = "" }
WordHunterWoW_QuestEN[51482] = { title = "Seeking More Knowledge", description = "One of de most sacred plants on dis island is anchor weed. Legend says dat it was a gift from de Loa and it can do anything from regrow limbs to granting immortality.\n\nIf you are looking for facts as to what it can do or how to harvest it, you will need to go elsewhere. \n\nThe spirits tell me dat dere is a book, dat contains de information you seek. Look for it deep within the Waycrest Manor.\n\nDey ask dat in exchange for dis knowledge, you kill whatever is causing a rift in de spirit world.", objectives = "" }
WordHunterWoW_QuestEN[51483] = { title = "Heritage o' the Dark Iron", description = "Ye've done us proud, {name}. I've heard tales o' yer bravery during yer journeys across the surface o' Azeroth.\n\nReturn tae the mountain. We've got somethin' special fer ye.", objectives = "" }
WordHunterWoW_QuestEN[51484] = { title = "Heritage of the Mag'har", description = "You have fought countless battles across the face of Azeroth. You have shown both our allies and enemies what it means to be Mag'har!\n\nReturn to Orgrimmar that I may recognize your dedication to our people.", objectives = "" }
WordHunterWoW_QuestEN[51485] = { title = "For the Horde", description = "The Mag'har face a new future, {class}.\n\nDraenor has fallen. We cannot know if we will ever set eyes upon our homeland again. But this is not the time to wallow in past sorrows.\n\nDestiny is ours to decide. Orgrimmar is our home now, and we must make our mark upon this land!\n\nShow our allies in the Horde what it means to be Mag'har. Meet with the ambassador at the warchief's embassy, then go forth and claim victories across Azeroth.\n\nStrength and honor, {name}!", objectives = "" }
WordHunterWoW_QuestEN[51486] = { title = "Fer the Alliance", description = "The mountain will always be home, but there's a whole world o' adventure up there on the surface. Ye look like just the sort o' {class} to find it.\n\nFer a long time, the Dark Irons stood apart from the other kingdoms. The time has come tae show 'em that we fight fer Azeroth, too.\n\nThere's an ambassador in Stormwind waitin' tae speak tae ye. He can help guide ye along on yer journey.\n\nThe Alliance needs our strength, {name}. Get out there and show 'em the might o' the mountain!", objectives = "" }
WordHunterWoW_QuestEN[51487] = { title = "Searching for Answers", description = "There's a saying Cyrus always said when I was a kid: \"The best face is a friendly one.\" It's really helped me get to know the visitors from all over the world that come through Boralus.\n\nLet's ask some of the people in charge around here and see if they know anything about the fleet. Maybe it's just a matter of asking nicely!", objectives = "" }
WordHunterWoW_QuestEN[51488] = { title = "Archived Knowledge", description = "It seems like this Brother Alen we keep hearing about might have some answers. \n\nAt least, I sure hope so. Everyone here seems a bit... evasive.\n\nI think I saw some archivists heading into the southern cloister. If we follow them, I bet we'll find Alen too.", objectives = "" }
WordHunterWoW_QuestEN[51489] = { title = "Time to Leave", description = "I knew it! I knew the fleet wasn't just lost!\n\nWe may be a little in over our heads here. Let's leave before things get out of hand.\n\nGaleheart can take us to Stormsong Valley from here. No point in following tradition at this point, right?", objectives = "" }
WordHunterWoW_QuestEN[51490] = { title = "Border Issues", description = "They've closed off the entire valley! No wonder so many people have been complaining about trading with the Brennadam market.\n\nWe have to do something about this. These people need to make a living!\n\nYou're going to have to be an honorary cadet for me here, {name}. Tell these ruffians to clear the road!", objectives = "" }
WordHunterWoW_QuestEN[51492] = { title = "Gunpowder Plot", description = "Granny has everyone out running errands trying to put our hamlet back in order.\n\nI don't know what to do. The rats have gotten into our stores, they're eating everything in sight.\n\nI tried prodding one of them to get it to move along, it started foaming at the mouth, then it exploded! \n\nThink I know where all the gunpowder went...\n\nIf you recover any, can you please take it back to Marie?", objectives = "" }
WordHunterWoW_QuestEN[51498] = { title = "Cultural Significance", description = "I have noticed dat your skill with harvesting plants has improved, but I have also noticed dat you just treat each flower and leaf as a commodity. De flora of dese islands have a rich history, with a deep cultural significance to us.\n\nGo down to the Port of Zandalar, and ask some of the men and women what a sea stalk means to them.  Learn from us, and l will make it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[51503] = { title = "Gathering Mementos", description = "I have a task dat I can not really trust to anyone else, and I feel you could handle it with de reverence it deserves.\n\nAn old friend came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship off the coast of Nazmir. I am unsure if de ship went down because of de naga, de Alliance, or a squall, but she said she did not want revenge.  Only closure.\n\nIf you could go get her something to remember him by, I will tell you everything I know about sea stalks.", objectives = "" }
WordHunterWoW_QuestEN[51504] = { title = "Cookie Delivery", description = "Before you head out, dear, I have one more favor to ask of you.\n\nPlease take these cookies with you to Charles.\n\nWhat sort of grandmother would I be if I didn't bake some for him too!?\n\nA terrible one, that's what, and I've no wish to be accused of that!", objectives = "" }
WordHunterWoW_QuestEN[51513] = { title = "Zalazane Returns", description = "{name}, I have never needed your help as much as I do this day. My home be under attack.\n\nI only just heard myself. Master Gadrin be callin' for aid. Zalazane, an old enemy of da Darkspear, has returned to da Echo Isles and has brought with him an army of da dead.\n\nZalazane be a traitor who has slain many Darkspear and defiled their souls. Will you come with me to defeat him? We can take da ship dat departs da Port of Zandalar.", objectives = "" }
WordHunterWoW_QuestEN[51514] = { title = "Broken Bargain", description = "These mindless undead just keep coming. They be far stronger than they were the last time Zalazane walked this world.\n\nPlease, help us drive these undead back.", objectives = "" }
WordHunterWoW_QuestEN[51515] = { title = "Vengeance for Vol'jin", description = "If we mean to destroy Zalazane then we gonna need something that can damage that spirit.\n\nDa Glaive of Vol'jin might be what we need to do this.\n\nZalazane be hovering near where he fell so many years ago. Rokhan and Talanji have already gone to face him.\n\nGo, slay Zalazane, and then plunge da glaive into the spirit before it can escape. Let us hope de bargain Vol'jin made be powerful enough to destroy this enemy.", objectives = "" }
WordHunterWoW_QuestEN[51516] = { title = "Atal'Dazar: Ashes of a Warchief", description = "I have learned much of de Darkspear lately. Truth is, I have quietly admired dem since I was a little girl, hearin' of Vol'jin's defiance of Zul's reckless call to action.\n\nVol'jin was Warchief of the Horde, chieftain of de Darkspear, and more troll den most can claim to be.\n\nHis ashes should be honored in a place of kings and queens.\n\nTake de ashes to Atal'Dazar with my blessing and honor your former Warchief as he deserves.", objectives = "" }
WordHunterWoW_QuestEN[51517] = { title = "You Owe Me a Spirit", description = "Ya not leaving that here.\n\nOl' Vol'jin not be dancin' in my house. I not be seein' his spirit for a long time.\n\nIts absence has broken de bonds dat held Zalazane in my control.\n\nSo... I want you to lift dat heavy urn, and bring it to my necropolis.\n\nVol'jin and I gonna have a face to face on my ground.", objectives = "" }
WordHunterWoW_QuestEN[51518] = { title = "The Lost Spirit", description = "It high time you an' I had a talk about ol' Vol'jin's missin' spirit. \n\nDis goes beyond simple bargains and rights of passage. Spirits don' just go missin'.\n\nYou gotta few friends dat are gonna help ya track Vol'jin's spirit down. Dem who was friends to him in life should have da strength to find him in death. And if not, Talanji gonna help ya.  \n\nGo to Talanji's ship in da Port of Zandalar. It be dat banged up ship ya came in on. You gonna do a little seance.", objectives = "" }
WordHunterWoW_QuestEN[51519] = { title = "Spirit Call", description = "We gonna be reachin' far into de Shadowlands for this. If Vol'jin has gone beyond Bwonsamdi's vision than either he be lost somewhere or hiding.\n\nEither way, I am hoping the bond he shares with de gathered Darkspear here can help bring him to us.\n\nStay close and don't interrupt de ritual once it has begun.", objectives = "" }
WordHunterWoW_QuestEN[51520] = { title = "Justice for the Fallen", description = "Justice for da sons and daughters of lost loa. Justice for da heart of Zandalar. G'huun must be slain, and a symbol of his death displayed to those who need see it most.\n\nTake me glaive, drive it into da corpse of dat beast, and let Talanji show it to her people.\n\nLet peace be started in da hearts of da Zandalari.", objectives = "" }
WordHunterWoW_QuestEN[51521] = { title = "The True Leader of Zandalar", description = "Now, take me glaive and walk with Talanji. Let her present your victory to her people. Let da trolls know justice, and the strength of a leader.", objectives = "" }
WordHunterWoW_QuestEN[51526] = { title = "The Warlord's Call", description = "Warfang Hold is our best position on Kul Tiras. We can not allow it to fall!\n\nThe Warchief has placed High Warlord Cromush in charge of our reinforcement efforts, you are ordered to report to him as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[51532] = { title = "Storming In", description = "Front and center, {name}!\n\nAs of last night, we received word that Rexxar's force at Warfang Hold in Stormsong was surrounded by a Kul Tiran army and an attack is imminent.\n\nAs soon as you have your things packed, go speak with Dread-Admiral Tattersail and we'll get underway. There's no time to waste!", objectives = "" }
WordHunterWoW_QuestEN[51533] = { title = "The Glaive of Vol'jin", description = "When fighting someone who has escaped the grasp of Bwonsamdi, as Zalazane has, it is best to bring weapons that can hurt him.\n\nIn Darkspear Hold you will find the Glaive of Vol'jin.\n\nIt should have enough bond with Vol'jin's spirit to aid us in this fight.", objectives = "" }
WordHunterWoW_QuestEN[51535] = { title = "A Veteran's Summons", description = "{name}, we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you.\n\nI wouldn't keep him waiting or he might expire of old age before you find out what he wants.", objectives = "" }
WordHunterWoW_QuestEN[51536] = { title = "On the Hunt", description = "Looks like the magic the Kul Tirans used on our ships is beginning to dissipate, but I'm sure what happened to our ships here is only just the beginning.\n\nGet to the shore. We need to contact the survivors and find out just what we're up against.", objectives = "" }
WordHunterWoW_QuestEN[51538] = { title = "Word from the Deep", description = "A dark soul has infiltrated the Zanchuli Council, seeking an accord with Queen Azshara.\n\nSome followed, through greed or fear. Others were too trusting and believed his lies.\n\nWe fall, one by one. They will soon clear the path of resistance.\n\nAzshara's motives are hidden behind a vast darkness. She reaches into a place from where she cannot return.\n\nI would pity her, but she killed my followers...\n\nWhen the time comes, I will rip her apart.", objectives = "" }
WordHunterWoW_QuestEN[51539] = { title = "Inform the Horde!", description = "This was all perpetrated by someone on the Zanchuli Council. \n\nThey sacrificed their own people, Gral's followers, for Azshara. That is unconscionable!\n\nThey weaken the foundation, so the kingdom will fall.\n\nOne of your people must have direct access to the king. Anyone else could be the traitor.", objectives = "" }
WordHunterWoW_QuestEN[51540] = { title = "Explosive Situation", description = "<This crate has fallen into the water. It contains bombs built to take out large mechanical devices.>\n\n<If we had more of them, we could destroy the Venture Company's Reef Breaker.>", objectives = "" }
WordHunterWoW_QuestEN[51543] = { title = "Saplings in the Snow", description = "Be wary mainlander, dangers lurk nearby. \n\nOne such creature, Greenstalker, used to be an ally. In his corrupted, mindless rage he nearly killed my brother and I while we were trying to help someone in the wilds. There is something which might help but I must tend to my brother's wounds and cannot obtain the remaining item on my own.\n\nPlease go onto the mountainside and pull some saplings out of the earth for me. The plants here are healthy and their roots run deep so they won't come easily.", objectives = "" }
WordHunterWoW_QuestEN[51544] = { title = "Disarming the Cannons", description = "With your arrival, our salvation may have arrived. Your rowboats will serve as a way for us to evacuate the most critically injured.\n\nUnfortunately, the Horde have brought in a ship, and there's no way we can get our boats past their blockade.\n\nWhile the rest of us load our injured on the boats, we need you to infiltrate their ship and disable those cannons.", objectives = "" }
WordHunterWoW_QuestEN[51545] = { title = "Breaker Bad", description = "The combined fire power of all the bombs you have collected should be able to destroy the Venture Companies Reef Breaker.\n\nIt's time to act and protect the reef and this sacred cave.", objectives = "" }
WordHunterWoW_QuestEN[51547] = { title = "WANTED: Rindlewoe", description = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories.\n\nIf any adventurers are brave enough to vanquish this beast, the town of Fallhaven would gratefully proffer a reward.\n\nPlease report to Mayor White if you wish to help.", objectives = "" }
WordHunterWoW_QuestEN[51552] = { title = "The Days Are Just Packed", description = "Hello there! Would you mind checking on someone for me?\n\nSergeant Calvin was supposed to meet me here. We were going to go out looking for new alchemical reagents, but he hasn't shown up yet.\n\nI know the militia has been really busy lately so I guess he's busy, but he should still be in Brennadam Square. Would you mind checking in on him?", objectives = "" }
WordHunterWoW_QuestEN[51554] = { title = "Reloading", description = "Daryl's making every shot count, but there's just too many Horde. We're going to need more ammo soon!\n\nI need you to take this note to my uncle Leo at Deadwash, he'll be able to help.", objectives = "" }
WordHunterWoW_QuestEN[51555] = { title = "Keep Them On Task", description = "Princess Talanji's actions have thrown off our pursuers. Her loa is powerful indeed.\n\nWe need to be certain if there were survivors, they do not gain a foothold on Zandalar. I am concerned that our Forsaken compatriots might get... overzealous. Please keep an eye on them, and remind them of what is honorable.", objectives = "" }
WordHunterWoW_QuestEN[51557] = { title = "Irontide Warning", description = "Horde's taking this town! I'm not gonna stick around to watch!\n\nYou could help me out though. Go see Leo Shealds in Deadwash.  \n\nTell him, Irontide is still coming and we're taking the gold!", objectives = "" }
WordHunterWoW_QuestEN[51567] = { title = "Island Expeditions", description = "Welcome to the World of Warcraft: Battle for Azeroth PAX demo!\n\nThe table in front of you can be used to queue for Island Expeditons.\n\nGrab two friends and prepare for adventure!\n\nWe hope you enjoy your time in Azeroth today!", objectives = "" }
WordHunterWoW_QuestEN[51568] = { title = "Ritualistic Preparations", description = "Hey! I just got a request for a shipment of storm silver. Wanna help? \n\nAs you know, storm silver is lightweight and resists corrosion. What you may not know is that we use it throughout our ships. It's so light our marines and pirates use it for armor because they can swim in it!\n\nHowever, any parts that go onto a ship have to be blessed by a tidesage, or it'll be cursed to a watery doom!\n\nHarvest a bucketful of ore, smelt it, and get it blessed for me, and I will teach you how to mine it easier.", objectives = "" }
WordHunterWoW_QuestEN[51569] = { title = "The Zandalar Campaign", description = "It is time that we begin to think of our enemy, {name}. The Horde spreads its influence throughout Zandalar unchecked.\n\nKing Anduin has charged us with establishing footholds in the areas of Zuldazar, Nazmir, and Vol'dun.\n\nI have taken the liberty of deploying some of our forces in key locations, but each will need a firm hand--your hand--to direct our efforts.\n\nWhich location shall we secure first?", objectives = "" }
WordHunterWoW_QuestEN[51570] = { title = "Foothold: Zuldazar", description = "Zuldazar is the seat o' power fer the Zandalar empire.\n\nI've deployed some o' me mole machines in a place called Xibala. There's a nearby Azerite deposit that'll be o' great interest to the King. My lads say they're under attack.\n\n                 - Moira Thaurissan", objectives = "" }
WordHunterWoW_QuestEN[51571] = { title = "Foothold: Nazmir", description = "The swamp of Nazmir is home to the notorious blood trolls.\n\nCaptain Conrad has been dispatched to determine how we can use their hatred toward the Zandalari to our advantage. Reports from the jungle have proven disconcerting at best.\n\n                     - Mathias Shaw", objectives = "" }
WordHunterWoW_QuestEN[51572] = { title = "Foothold: Vol'dun", description = "The desert of Vol'dun has a promising harbor for our fleet.\n\nAn indigenous snake people known as the sethrak occupy the area. They are aggressive and cannot be negotiated with. We have little choice but to eliminate them.\n\n                    - Magister Umbric", objectives = "" }
WordHunterWoW_QuestEN[51573] = { title = "I've Got Your Back", description = "It's good to see a new face around here. I've got a problem and you look like you can handle a fight.\n\nDat group of murderous thugs over dere are looking for trouble and I need someone to back me up.\n\nDe truth is dat I used to be one of dem myself, but I left for a second chance at an honest life.\n\nI need to convince Mojambo and his henchmons to leave before dey start causing trouble for de rest of de outcasts here.", objectives = "" }
WordHunterWoW_QuestEN[51574] = { title = "Freshly Squeezed", description = "Is this troll a friend of yours? I'm so glad Kiro let me keep her. \n\nHe's a bit wary of outsiders, but he's a great healer. \n\nShe'll wake up, I promise. And when she does, she'll be thirsty.\n\nThe sands are short on water, but you're in luck. The grove that surrounds this camp is filled with pricklevines. \n\nYou wouldn't want to eat the flesh, but the liquid inside can quench any thirst.\n\nJust give them a good squeeze to collect their juice.", objectives = "" }
WordHunterWoW_QuestEN[51575] = { title = "Lost But Not Forgotten", description = "Hey, {name}, would you be interested in getting back a personal possession?\n\nDere is a raptor in Xibala dat took an ancient and valuable artifact from my people. My attempts to negotiate with de beast have not gone well, resulting mostly in mutual screaming and biting.\n\nFind de raptor Bonescreamer, kill it, and bring me de lost artifact.\n\nIn return, I will show you how to skin dese beasts of de land more effectively.", objectives = "" }
WordHunterWoW_QuestEN[51582] = { title = "Make it Mildenhall", description = "You've no doubt enjoyed a mug or three of world-famous Mildenhall Mead in your local tavern. Today is your day to become a part of the official meadery of Stormsong Valley!\n\nIdeal applicants have a hunger for craft mead, honey, and boundless innovation. Military experience recommended, but not required.\n\nMust not be allergic to bees.\n\nMildenhall Mead - Make it Mildenhall.", objectives = "" }
WordHunterWoW_QuestEN[51587] = { title = "Onward!", description = "I'm glad you came, {name}. With your help, we will show these Kul Tiran dogs what happens when you face a cornered beast!\n\nWarfang Hold is just up the path from here. Come, I'll fill you in on the details.", objectives = "" }
WordHunterWoW_QuestEN[51589] = { title = "Breaking Kul Tiran Will", description = "Our partnership with the Zandalari will soon be secured. Took a little longer than I expected... but such is the way of things.\n\nUnfortunately, the Alliance seems intent on securing a naval force of their own. That can't be allowed to happen.\n\nWe set sail for Tiragarde Sound when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[51590] = { title = "Into the Heart of Tiragarde", description = "Step one is to establish a more suitable base of operations. A pirate's den will do in a pinch, but I believe the warchief expects better of us.\n\nLet's split up and push farther inland, to the west. Be on the lookout for something defensible and inconspicuous.", objectives = "" }
WordHunterWoW_QuestEN[51591] = { title = "Our Mountain Now", description = "{name}, go take care of those \"roughnecks.\" They might fashion themselves as tough, but a bit of your unique brand of Horde savagery should have them running in no time.\n\nLilian, scout the area. We need to know about any nearby threats.\n\nRangers, secure the perimeter. We'll reconvene in the roughneck camp once {name}'s work is done.", objectives = "" }
WordHunterWoW_QuestEN[51592] = { title = "Making Ourselves at Home", description = "Log cabins will do in a pinch, but... if we're going to be spending any time here, we might as well make ourselves comfortable.\n\nThe roughnecks left us no shortage of lumber and food supplies, but we'll need canvas and chains to set up some proper Forsaken tents and banners. Bridgeport sounds rather lootable, doesn't it?", objectives = "" }
WordHunterWoW_QuestEN[51593] = { title = "Bridgeport Investigation", description = "While you're in Bridgeport, you might keep an ear out for any information that will be of aid to us.\n\nYou'd be surprised what you can learn by staying quiet and listening to people who think they're alone...", objectives = "" }
WordHunterWoW_QuestEN[51594] = { title = "Explosives in the Foundry", description = "I'm most interested in those explosives, though.\n\nMeet me in the foundry, east of here. You probably passed through it on your way from Plunder Harbor.", objectives = "" }
WordHunterWoW_QuestEN[51595] = { title = "Explosivity", description = "I don't want to waste your time. Let's make absolutely sure that these are what we're looking for.\n\nHere, take this torch and toss it over onto those crates. If they explode, then we'll know what to do next.", objectives = "" }
WordHunterWoW_QuestEN[51596] = { title = "Ammunition Acquisition", description = "First: we get as much of that gunpowder as we possibly can. Imagine the terror in the Kul Tirans' eyes when they realize the Horde has turned their own weapons against them.\n\nImagine it, {name}.\n\n<Lilian's eyes briefly glaze over, and the corner of her lips turns upward in a half-smile.>", objectives = "" }
WordHunterWoW_QuestEN[51597] = { title = "Gunpowder Research", description = "I suppose that, before we steal all the Kul Tirans' violently explosive gunpowder and use it against them, we should learn how they make the stuff.", objectives = "" }
WordHunterWoW_QuestEN[51598] = { title = "A Bit of Chaos", description = "This place seems fairly well-defended for a manufacturing facility, doesn't it?\n\n<Lilian shrugs.>\n\nI suppose we'll have to kill them, then.", objectives = "" }
WordHunterWoW_QuestEN[51599] = { title = "Death Trap", description = "We started this mission with a goal, but not much of a plan. I think I can see the pieces coming together, though.\n\n<Lilian surveys the horizon, thinking.>\n\nPlace these explosives over on the southwest edge of town. Somewhere inconspicuous.\n\nWe'll meet again over there. In the meantime... I need to find a horse.", objectives = "" }
WordHunterWoW_QuestEN[51601] = { title = "The Bridgeport Ride", description = "Pay attention, {name}, because this isn't going to be our standard assassination mission.\n\nYou and I are going to take this horse through Bridgeport and... cause a scene. I want every single guard on our tail, along with that Captain Stone character. Once we've rounded them up, it's over to those explosives, and...\n\n<Lilian's eyes grow wide with delight.>\n\nBoom.", objectives = "" }
WordHunterWoW_QuestEN[51602] = { title = "Bandit Blades", description = "We only have enough weapons to arm half of de tribe against Mojambo's gang.\n\nWe're going to need more weapons if we are going to survive de approaching battle.\n\nTongo's crew is sure to have a ready supply of weapons at their hideout.\n\nSearch de hideout for any weapons you can find and bring dem back to de arena.", objectives = "" }
WordHunterWoW_QuestEN[51643] = { title = "A Wall of Iron", description = "The enemy has pushed our men to the shore and sunk their ships. They have nowhere to run and nowhere to hide; it's up to us to save them!\n\nGet below deck, man a cannon, and start laying down some covering fire. They're depending on us!", objectives = "" }
WordHunterWoW_QuestEN[51663] = { title = "Preparing for the Fall", description = "<A large quantity of supplies are scattered throughout the temple grounds, much of it under heavy guard. The Jambani appear to be preparing for a siege or another significant event.\n\nZul would likely think it wise to stymie their efforts.>", objectives = "" }
WordHunterWoW_QuestEN[51668] = { title = "Mojambo", description = "Mojambo and his gang are attacking!\n\nWe must defend de arena. Mojambo must be defeated! De outcasts will take care of his gang. Mojambo is all yours...\n\nBring Tongo's head with you and use it to challenge Mojambo to a duel. His pride is too great to resist such a challenge!", objectives = "" }
WordHunterWoW_QuestEN[51674] = { title = "Douse the Flames", description = "Do you smell it, {name}? Smoke! They're burning down Warfang Hold!\n\nThere is little point to our battle if our base burns to the ground!\n\nTheir tidesages use wands to control their constructs of water. In our hands they may give us a chance to save the Hold! \n\nGet those wands and put out the fires before the camp burns to ash!", objectives = "" }
WordHunterWoW_QuestEN[51675] = { title = "Hunt Them Down", description = "These Kul Tirans, they don't seem normal. Humans can be a cruel bunch from what I've heard, but these ones seem to take pleasure in slaying the fallen. \n\nThe worst of them was a woman wearing a peculiar mask. She seemed to be shouting orders to the others, so I guess she's their leader.\n\nHonor the fallen and ensure they and their leader don't survive.", objectives = "" }
WordHunterWoW_QuestEN[51677] = { title = "Mending Body and Soul", description = "Good. You have brought me the last ingredients I will need to concoct a solution to close the king's wounds.\n\nYou are not a moment too soon. He is fading.\n\nI am not comfortable working at an elevated pace, but the situation requires it. You must be my hands, for I am very slow.\n\nBring me what I need, and let Jamil and I worry about the rest.\n\nSpeak to me when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[51678] = { title = "Rastakhan's Might", description = "Do you see de ship out in de bay, {name}?\n\nDat is my flagship, Rastakhan's Might. It is not here under my orders.\n\nWe will deal with de Prophet Zul in good time. For now, those who took my vessel must pay.\n\nYou are to bring me de head of Windcaller Ula'jan. De ship does not move without him, and it will not be moving again once he is dead!", objectives = "" }
WordHunterWoW_QuestEN[51679] = { title = "A Strange Port of Call", description = "I know Rastakhan is furious dat dey claimed his ship, of all de vessels in our navy.\n\nBut dere is a better question to ask. Why did dey bring it here?\n\nZeb'ahari is a small fishing village. Dere are no warriors here, no powerful supporters of de king. Dere must be another reason.\n\nBoard de ship and have a good look around. See if you can find out why dey brought dat beast of a boat way out here.", objectives = "" }
WordHunterWoW_QuestEN[51680] = { title = "In Bwonsamdi's Shadow", description = "Something is wrong, {name}.\n\nMy king is blessed by de loa in ways your kind cannot imagine. He has been given long life, swift healing, and strength beyond most trolls. But still, he lingers on death's door. I can practically hear Bwonsamdi laughing.\n\nTwo of his most trusted menders are with him. Go and find out what is taking so long.\n\nI will make sure dey are not interrupted.", objectives = "" }
WordHunterWoW_QuestEN[51691] = { title = "Almost Worth Saving", description = "We tried to evacuate as many of our people from the hold as we could, but some of the peons weren't so lucky. \n\nThey're worthless as fighters, but we'll need their labor in the times ahead.\n\nPlease, save them if you can.", objectives = "" }
WordHunterWoW_QuestEN[51696] = { title = "Reclaiming What's Ours", description = "I'm impressed. You not only saved our people, but you also managed to kill the leader of the attacking forces.\n\nAt the top of this tower is our warhorn. At the signal, our troops will come running and we'll get this hold back under our control.\n\n{name}, I think you've earned the honors.", objectives = "" }
WordHunterWoW_QuestEN[51711] = { title = "Having a Blast", description = "We're going to really hit 'em where it hurts, {name}.\n\nThey're carting tons of black powder right out of that mine. This could end very badly for all of us if we don't do something.\n\nThe mines are relatively undefended, I bet you can get in and wipe out their workers before they realize what's happening.\n\nKeep an eye out for some explosives, if we can use their own tools against them, even better!", objectives = "" }
WordHunterWoW_QuestEN[51712] = { title = "Eye for an Eye", description = "This is it, {name}. Now is the time to strike. \n\nTake this shredder and destroy their stronghold. Burn everything to the ground!\n\nShow no mercy. They certainly didn't offer any to all of the innocent civilians they slaughtered in Brennadam!", objectives = "" }
WordHunterWoW_QuestEN[51714] = { title = "Mission from the King", description = "Och, good ta see ya! Feels great ta stretch me gryphon's wings above the seas.\n\nI'm here ta assist with the war effort. Happy to help!\n\nLet's go meet with Master Shaw, matey.\n\nHa! Always wanted to say somethin' piratey. Did ya know they named a ship after me once? It was wild!", objectives = "" }
WordHunterWoW_QuestEN[51715] = { title = "War of Shadows", description = "Every war is fought on multiple fronts, {class}.\n\nKing Wrynn has tasked Halford Wyrmbane and his 7th Legion with securing our position in Kul Tiras as well as Zandalar.\n\nBut they cannot succeed without us. We are the unseen hand. The shadows in the darkness.\n\nI have been charged with establishing an elite strike force, and I need you to act as liaison between Wyrmbane's efforts and my own.\n\nYou will help direct our missions going forward. Let us begin.", objectives = "" }
WordHunterWoW_QuestEN[51717] = { title = "The Best Honey In Vol'dun", description = "If you can handle rescuin' de others by yourself, Zulsan and I will head back to de inn and start cleanin' up de place.\n\nDon't worry, I still be cookin' up a special batch of my famous scorpid blood drinks for you.\n\nIn fact, you gonna be runnin' right past my friend Rikati. He sells de best honey in all of Vol'dun!\n\nBring back a few bottles of it for me and let's add some sweetness to de drinks!", objectives = "" }
WordHunterWoW_QuestEN[51718] = { title = "Harvesting \"Honey\"", description = "I don't know what Rhan'ka's doing down in that oasis with all of the honey he's bought from me. Frankly, I suspect I don't even want to know.\n\nBut whatever his reasons, Rhan'ka is my best customer.\n\nSo even though my supply's getting low, because Rhan'ka sent you, I'll give you a special deal.\n\nThe wasps here keep all their honey stored in their stingers. Bring some to me, so I can drain them for honey and I'll give you a big batch of the sticky stuff to take back to Rhan'ka.", objectives = "" }
WordHunterWoW_QuestEN[51720] = { title = "Get Shredded", description = "I was scouting ahead while you were wreaking havoc in the mine.\n\nSpotted a hulking, armored shredder in their lumber yard. Bet we could do some real damage with that thing! \n\nI tried to start it up, but looks like it might be out of juice. Maybe they forgot to charge it?\n\nSee if you can grab a fresh power core from one of the other shredders nearby.", objectives = "" }
WordHunterWoW_QuestEN[51723] = { title = "Saw Dusted", description = "If we want to keep them from expanding into Stormsong, we need to cripple their lumber production!\n\nThey've only got so many lumberjacks running around. If we can cut some of them down, they'll be forced to reconsider their plans.", objectives = "" }
WordHunterWoW_QuestEN[51726] = { title = "Get Out of Here", description = "I can't believe you're here. Please, we need help!\n\nThey've been forcing us to mine nonstop. The weakest among us have been steadily dropping. At this rate, we'll all be dead soon.\n\nThe chains are weak. You may be able to pry the lock apart.\n\nI'll keep a lookout until the others are free. Don't worry about me!", objectives = "" }
WordHunterWoW_QuestEN[51728] = { title = "Burn It All Down", description = "Alright, the flamethrower is all patched up. Now we're going to get a little payback for Brennadam!\n\nIf it's flammable, it's a target. If not, well, it probably still needs to die anyway. And let's bring down those siege towers while we're at it.\n\nBurn it all to the ground!", objectives = "" }
WordHunterWoW_QuestEN[51752] = { title = "Grizzled", description = "I saw a particularly ugly and quite agitated goblin barking orders at the rest of the miners.\n\nI'm willing to bet he's crucial to their entire operation. If you can get into the mine and eliminate him, hopefully it will throw things into disarray.", objectives = "" }
WordHunterWoW_QuestEN[51753] = { title = "Champion: Rexxar", description = "", objectives = "" }
WordHunterWoW_QuestEN[51770] = { title = "Mission from the Warchief", description = "Lady Sylvanas issued orders for Garona Halforcen to take on a task of great import.\n\nShe will orchestrate missions from the Banshee's Wail, and is to assemble a strong force to execute on our plans.\n\nThis effort will be vital to our war against the Alliance, and your assistance will certainly be necessary.", objectives = "" }
WordHunterWoW_QuestEN[51771] = { title = "War of Shadows", description = "I have begun to assemble heroes for our cause. Perhaps you already know Arcanist Valtrois? We will need to recruit more in the future, but this is a promising beginning.\n\nOur missions will be those of subterfuge, reconnaissance, assassination, and other focused strikes against our enemies.\n\nLet us test the mettle of this nightborne, shall we?", objectives = "" }
WordHunterWoW_QuestEN[51772] = { title = "The Tortaka Tribe", description = "Have you ever met a tortollan before? Dey have all kinds of useful scrolls and artifacts for sale.\n\nWe used to trade often with de Tortaka tribe, but we haven't seen or heard from dem in weeks.\n\nDe tribe has a village in Darkwood Shoal. We need someone to make contact with dem and reestablish our trading partnership.", objectives = "" }
WordHunterWoW_QuestEN[51773] = { title = "The Ashvane Threat", description = "De Ashvane Trading Company has a mining operation in Redrock Harbor.\n\nDon't let de fancy name fool you, dey are as dangerous a band of pirates as I've ever seen.\n\nRecently, one of their crew members has been trying to make contact with us. I need someone to meet with him and see what he wants.\n\nIt might be a trap, but whatever information he has on de Ashvane Trading Company could prove useful to our survival.", objectives = "" }
WordHunterWoW_QuestEN[51775] = { title = "Camp Lastwind", description = "A vulpera caravan recently set up camp not far from here.\n\nDis could be a good opportunity to establish new trade partners with de tribe.\n\nDe desert is a dangerous place, {name}. Go see if dey need any assistance. I'm sure dey could use experienced hands like yours.\n\nIn exchange, perhaps dey'd be willing to offer de tribe a discount on goods and services.", objectives = "" }
WordHunterWoW_QuestEN[51784] = { title = "A Stroll Through a Cemetery", description = "Our next stop is in Drustvar.\n\nThere, along with some help, we shall identify and extract the body of a Kul Tiran war hero.\n\nWith his aid, we will learn much of the Kul Tiran fleet. Enough to break it with ease.\n\nWe shall meet you outside Barrowknoll Cemetery.\n\nDo try not to waste time, would you?", objectives = "" }
WordHunterWoW_QuestEN[51785] = { title = "Examining the Epitaphs", description = "Without Stone's knowledge, this mission shall require some extra legwork.\n\nRead the plaques in the cemetery. Find the corpse of the most import.\n\nThe rest should be quite simple.", objectives = "" }
WordHunterWoW_QuestEN[51786] = { title = "State of Unrest", description = "There is one thing you should know about ghosts, {name}.\n\nThey are a mockery of the dead. Spirits, holding on although they have no hope. In that form, they shall never truly live again. Not as long as they keep haunting our world.\n\nBut if they return to their bodies, perhaps they will become of specific use to us someday down the line.\n\nPut those spirits down.", objectives = "" }
WordHunterWoW_QuestEN[51787] = { title = "Our Lot in Life", description = "It seems that Amalia isn't taking to undeath well.\n\nI know an herb that may help.\n\nThis cemetery is crawling with gravebloom. For the living, it grants the ability to see spirits.\n\nAs for the undead...\n\nThis may tie her back to reality just enough to be... sane.", objectives = "" }
WordHunterWoW_QuestEN[51788] = { title = "The Crypt Keeper", description = "I've been keeping my sights on the cemetery.\n\nThere is one ghost that walks with a purpose, unlike the others.\n\nHe is the crypt keeper, the keeper of the keys.\n\nIf we want to get to Valentine's body, we will need to go through the ghost first.", objectives = "" }
WordHunterWoW_QuestEN[51789] = { title = "What Remains of Marshal M. Valentine", description = "We have the key. We found the crypt.\n\nNext, Valentine's body shall be ours.\n\nNo need to wait for Lilian and Stone. Let's finish this now.", objectives = "" }
WordHunterWoW_QuestEN[51795] = { title = "The Battle for Lordaeron", description = "King Wrynn has mustered our forces, {name}. We mean to launch a full-scale assault on Lordaeron.\n\nWe'll drive the Horde from the keep and reclaim it for the Alliance. It's been far too long since our flag flew in Tirisfal.\n\nReady to ship out? Captain Angelica here will see to your transport.", objectives = "" }
WordHunterWoW_QuestEN[51796] = { title = "The Battle for Lordaeron", description = "The Alliance has called its banners and marches on the Undercity.\n\nNow the war has truly begun.\n\nOur mage will send you on your way. Go.\n\nSee to our defenses, and get the civilians to safety. I will join you soon.\n\nLok-tar ogar, {name}.", objectives = "" }
WordHunterWoW_QuestEN[51797] = { title = "Tracking Tidesages", description = "Rexxar has been tracking a powerful tidesage to help us find the body of Marshal Valentine. He has sent word of a breakthrough.\n\nTravel to Stormsong. Help the half-ogre and Lilian find this tidesage, and bend him to the will of the Horde.\n\nDo not come back without a way to find Marshal Valentine.", objectives = "" }
WordHunterWoW_QuestEN[51798] = { title = "No Price Too High", description = "I have tracked a tidesage to a camp nearby. He has been staying there with his family.\n\nBe warned, tidesages are powerful foes. They have mastery over all the elements, and some even manipulate the Void.\n\nIf this man is with his family, it means he may not give up so easily. \n\nLet us hope he's smart enough to keep them out of this.\n\nCome.", objectives = "" }
WordHunterWoW_QuestEN[51800] = { title = "Foothold: Tiragarde Sound", description = "Tiragarde Sound has lotsa pirates on da coastline.\n\nI made contact wit' a first mate of a crew, and she tinks we can take on da captain and get a nice outpost in de process.\n\n          - Shadow Hunter Ty'jin", objectives = "" }
WordHunterWoW_QuestEN[51801] = { title = "Foothold: Drustvar", description = "It seems Drustvar has a big seam of Azerite underground.\n\nDo you like profit? I LOVE profit. This seems like a golden opportunity, if ya catch my meanin'. Time is money!\n\n          - Trade Prince Gallywix", objectives = "" }
WordHunterWoW_QuestEN[51802] = { title = "Foothold: Stormsong Valley", description = "We established and fortified an outpost in Stormsong Valley called Warfang Hold.\n\nThe Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay.\n\n                                 - Rexxar", objectives = "" }
WordHunterWoW_QuestEN[51803] = { title = "The Kul Tiras Campaign", description = "Our enemy spreads its influence throughout Kul Tiras, recruiting new allies to fight against the Horde.\n\nWe must establish footholds in these enemy lands if we are to win this war.\n\nThe Warchief requires your assistance in securing outposts in Stormsong Valley, Drustvar, and Tiragarde Sound.\n\nWhich location shall we secure first?", objectives = "" }
WordHunterWoW_QuestEN[51805] = { title = "They Will Know Fear", description = "Finally, a chance to strike at the Alliance AND Kul Tirans!\n\nSagehold is crawling with initiate tidesages studying magic and Kul Tirans trying to fortify the place against the Horde.\n\nLet's strike some fear into them. Make them rethink trying to help the Alliance fight the Horde.\n\nTake this horn. In my hands, it calls a val'kyr. In yours, it will sow terror amongst our enemies.\n\nI trust you above all others with this horn. Do not let me down.", objectives = "" }
WordHunterWoW_QuestEN[51810] = { title = "Captain Hartford", description = "I'm almost ready to leave Vol'dun once and for all. There's just one thing left to be done...\n\nWe need to murder the captain of the ship.\n\nIf Captain Hartford finds out I've deserted, I won't be safe in Boralus or anywhere else. He'll hunt me to the Eastern Kingdoms and back if he has to!\n\nThis will be dangerous. So you'll want to disguise yourself before boarding The Siren's Call.\n\nThis will be our last job together. Do it and I'll give you the code to the captain's lockbox. A pirate's bounty!", objectives = "" }
WordHunterWoW_QuestEN[51813] = { title = "Blackrock Depths", description = "Have you heard how the Dark Iron dwarves joined the Alliance? It was a most unusual turn of events.\n\nBrave heroes of the Alliance had been fighting the Dark Iron dwarves for years until a schism happened in their ranks.\n\nMoira Thaurissian, estranged daughter of the former dwarven king Magni Bronzebeard, was leading a faction of the Dark Iron dwarves.\n\nMoira wished to aid the Alliance. This began with an offer to help research Azerite and its potential uses within Blackrock Depths...", objectives = "" }
WordHunterWoW_QuestEN[51818] = { title = "Commander and Captain", description = "This brings me no joy, {name}, but I will do what I must to make sure my family is happy and safe.\n\nI would prefer we avoid violence, but if we must... there are two targets. Their leaders. Captain Malia and Commander Augustine.\n\nTheir loss should force the two groups to retreat from the area. \n\nAlso, Augustine confiscated a book of mine. Recover it and my powers are yours, for however long I have left.", objectives = "" }
WordHunterWoW_QuestEN[51819] = { title = "Scattering Our Enemies", description = "We've been scouting the area of Sagehold for some time now. It was recently retaken by a large force of Alliance and Kul Tirans.\n\nWe have been waiting for an opportunity to strike when their defenses were weakened. Now is that time.\n\nGo down to Sagehold and show the forces that remain what happens to those who take up arms against the Horde.", objectives = "" }
WordHunterWoW_QuestEN[51829] = { title = "Ranah's Wrench", description = "<The wrench is worn from repeated use, but otherwise appears to be in good shape. \n\nEngraved on the handle is the name: Ranah.>", objectives = "" }
WordHunterWoW_QuestEN[51830] = { title = "Zelling's Potential", description = "<cough> My body won't last much longer, but Miss Voss insists I display what my powers truly are.\n\nI can instill within you a <cough> <wheeze> magical font that will absorb void essence from slain creatures.\n\nWhen the font is full, you can unleash devastating wind magic.\n\nGo to <cough> Port Fogtide. There you will find those tainted by the Void.\n\nSlay them, fill the font, and you will <wheeze> see my magic at work.", objectives = "" }
WordHunterWoW_QuestEN[51837] = { title = "Whatever Will Be", description = "Well, here we are. Zelling seems like he'll be a powerful asset, as long as we ensure his family is taken care of.\n\nHe doesn't have much time left. Let's see if he can locate Marshal Valentine for us before he passes.", objectives = "" }
WordHunterWoW_QuestEN[51870] = { title = "Island Expedition", description = "Our spies have intercepted an Alliance message describing an outcropping of Azerite out in the Great Sea.\n\nThe Banshee's Wail isn't quick enough to get us there before they do. Lucky for us, I've arranged to have a Zandalari ship rigged and ready to go for opportunities like this.\n\nGo speak with Captain Rez'okun on the western side of the docks. He's been briefed, and should be waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[51881] = { title = "The Mine Sweeper", description = "<One of the goblin flamethrowers. Unfortunately the tank has been cracked. It would be a good idea to bring it back to Felecia, she might have something to fix it up.>", objectives = "" }
WordHunterWoW_QuestEN[51888] = { title = "Island Expedition", description = "We better be quick if we're gonna get to de island before de Alliance.\n\nYou ready?", objectives = "" }
WordHunterWoW_QuestEN[51889] = { title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI'm a little busy trying to see straight right now. Ugh... it feels like someone is swinging a pick at my skull. \n\nThe best cure for a hangover is pickle juice, a big greasy breakfast, and whatever I did not finish last night.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever ya want.", objectives = "" }
WordHunterWoW_QuestEN[51903] = { title = "Island Expedition", description = "Our spies have intercepted a Horde message describing an outcropping of Azerite out in the Great Sea.\n\nThe Wind's Redemption isn't quick enough to get us there before they do. Lucky for us, I've arranged to have a Kul Tiran ship rigged and ready to go for opportunities like this.\n\nGo speak with Captain Flynn Fairwind. He's been briefed, and should be waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[51904] = { title = "Island Expedition", description = "Alright! Let's snap to it! We've got to get to that island before the Horde does, don't we?\n\nYou ready?", objectives = "" }
WordHunterWoW_QuestEN[51916] = { title = "Uniting Zandalar", description = "The people of Zandalar are diverse and capable. If we can bring them all together under the banner of the Horde, the Alliance has no chance of stopping us.", objectives = "" }
WordHunterWoW_QuestEN[51918] = { title = "Uniting Kul Tiras", description = "The people of Kul Tiras are diverse and capable. If we can bring them all together under the banner of the Alliance, the Horde has no chance of stopping us.", objectives = "" }
WordHunterWoW_QuestEN[51926] = { title = "Pristine Akun'Jar Vase", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51929] = { title = "Pristine Urn of Passage", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51932] = { title = "Pristine Rezan Idol", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51934] = { title = "Pristine High Apothecary's Hood", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51936] = { title = "Pristine Bwonsamdi Voodoo Mask", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51937] = { title = "Pristine Blowgun of the Sethrak", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51950] = { title = "Pristine Ceremonial Bonesaw", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51951] = { title = "Pristine Ancient Runebound Tome", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51952] = { title = "Pristine Disembowling Sickle", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51953] = { title = "Pristine Jagged Blade of the Drust", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51954] = { title = "Pristine Ritual Fetish", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51955] = { title = "Pristine Soul Coffer", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.", objectives = "" }
WordHunterWoW_QuestEN[51961] = { title = "The Ongoing Campaign", description = "We have made excellent progress on Zandalar, {name}, but we must continue to expand our influence.\n\nIt is time for us to cross the sea once again to exert pressure on enemy lands, lest they fall fully into Horde hands.\n\nWhich location shall we secure next?", objectives = "" }
WordHunterWoW_QuestEN[51962] = { title = "Lumbering Away", description = "The hardwoods in dis jungle are dense enough dat dey rival coal in terms of how much heat a skilled miner can get out of dem.\n\nThe biggest problem using local timbers, however, is dat de jungle is always wet. If de wood is not stored properly, it takes weeks to dry out entirely.\n\nI bring dis up because my forge is starting to run low on fuel.\n\nBring me some dry firewood to keep it going, and in exchange I will teach you a trick for mining monelite.", objectives = "" }
WordHunterWoW_QuestEN[51964] = { title = "Insufferable Bloodsuckers", description = "{name}! I have some actual work that you could do for me.\n\nSince your mining skills are still not what Zandalari consider \"decent\", in exchange, I will show you how to mine monelite better.\n\nDe blood trolls of Nazmir have dese enormous ticks that they keep as pets and I have heard dat dey have managed to get within de borders of Zuldazar to de north. Dis does not sit well with me.\n\nThin their numbers for me, so I can happily die by being eaten by a pterrordax or something else respectable instead.", objectives = "" }
WordHunterWoW_QuestEN[51965] = { title = "Lending a Hand", description = "If you are looking for some work, I have something you can do.\n\nI went mining recently and a diemetradon managed to bite off my hand before I could get away from it.\n\nI do not care about the hand, I have already regenerated dat, but I did lose a couple rings dat I made.\n\nIf you go get them back, I will show you how to harvest more monelite from a seam. Or not. I do not care, but if you were looking for a chance to finally impress me, dis could be it.", objectives = "" }
WordHunterWoW_QuestEN[51967] = { title = "Return to Boralus", description = "I think that's enough excitement for today, lad!\n\nWhy don't ya get back ta Wyrmbane and tell the man we've got this place all under control.\n\nI'll make sure the blood trolls don't get any more of our folk! Ha!", objectives = "" }
WordHunterWoW_QuestEN[51968] = { title = "Return to Boralus", description = "You know, a lot has happened since you arrived in Zuldazar! I'm sure Mr. Wyrmbane would appreciate a report.\n\nOh, not from me. Maybe somebody a bit more serious... like you!\n\nI bet Daria over here could get you back pretty quick!", objectives = "" }
WordHunterWoW_QuestEN[51969] = { title = "Return to Boralus", description = "Shatterstone Harbor is an expansive foothold, and one that we will use to great advantage against the Horde.\n\nI will leave Umbric and the others in charge here. Let's get back to the Wind's Redemption and return to Boralus.", objectives = "" }
WordHunterWoW_QuestEN[51971] = { title = "An Exquisite Brooch", description = "You find a bloody brooch that features impeccable craftsmanship.\n\nThe design and quality of work reminds you of rings you previously recovered for Secott.\n\nPerhaps this is another item he lost and would like to see returned.", objectives = "" }
WordHunterWoW_QuestEN[51975] = { title = "Champion: Shadow Hunter Ty'jin", description = "", objectives = "" }
WordHunterWoW_QuestEN[51979] = { title = "The Ongoing Campaign", description = "The Warchief wishes for us to continue spreading our influence throughout Kul Tiras.\n\nWith our grip on Zandalar on the rise, now is the time to move forward with this objective in the lands of the enemy.\n\nWhich location shall we secure next, {class}?", objectives = "" }
WordHunterWoW_QuestEN[51980] = { title = "WANTED: Jabra'kan", description = "To any hunters worthy of the challenge:\n\nFind and defeat the troll known as Jabra'kan. His poaching ways have robbed Warbeast Kraal of valuable eggs, hides, and beasts for their pens.\n\nSeek out Wingrider Nivek for your reward.", objectives = "" }
WordHunterWoW_QuestEN[51982] = { title = "Storm's Rage", description = "Horde forces are pushing deeper into Stormsong Valley. We can not allow this aggression to go unchecked!", objectives = "" }
WordHunterWoW_QuestEN[51984] = { title = "Return to Zuldazar", description = "Look at dis place, boss-mon! We got da pirates, a location close to da Kul Tiran capital...\n\nI tink we should be bein' pretty proud of dis one.\n\nWe should get goin' back and tell Nathanos about our success. Maybe we can even get him to crack a smile.", objectives = "" }
WordHunterWoW_QuestEN[51985] = { title = "Return to Zuldazar", description = "You know kid, I think I've got it all covered here. My guys will find all the Azerite they can here and make me rich!\n\nI mean, you know, make the Horde rich. With power!\n\nAnyway, you can go tell Nathanos we're done here. This base is the best place to launch any attacks against the Kul Tirans here in Drustvar -- that's a Gallywix guarantee!", objectives = "" }
WordHunterWoW_QuestEN[51986] = { title = "Return to Zuldazar", description = "Warfang Hold is our most secured of the footholds we hold in Kul Tiras.\n\nKaga and her forces will be able to keep fortifications running, thanks to you. The Alliance will never see us coming!\n\nTell Nathanos that we have succeeded in our mission. I will help here until I am needed.", objectives = "" }
WordHunterWoW_QuestEN[51987] = { title = "Champion: Hobart Grapplehammer", description = "", objectives = "" }
WordHunterWoW_QuestEN[51990] = { title = "Wings for the Kraal", description = "It seems your little one needs a moment to rest after dat adventure. I will look after it.\n\nIf you want to make yourself useful while you wait, I heard de pterrordaxes to de north have been laying lots of eggs recently. Go collect de ones dat are wiggling and making noises. Dey are about to hatch.\n\nOur beasts breed well, but we always need more wings for de kraal.", objectives = "" }
WordHunterWoW_QuestEN[51991] = { title = "Charging the Batteries", description = "These little fellas are ravenous whirlwinds of devouring destruction. When they get going, they consume anything in their path, without even stopping! When sated, they discharge power from them little 'lectric zingers on their heads! \n\nThen they nap.\n\nLucky for us, we found just the right frequency to control their tiny bug brains. Hit that device, and you can take your own little zapper out for a spin... literally!\n\nMake sure ya bring it back full, so we can keep our rigs charged!", objectives = "" }
WordHunterWoW_QuestEN[51998] = { title = "DGH: Now With Real Direhorn", description = "...Listen, {name}. I need one more thing to finish making this supplement of mine.\n\nDirehorn Growth Hormone can't exactly be made without, you know, actual direhorn. But I floated the idea of harvesting a few of their beasts and all of a sudden I got a bunch of spears pointed at me.\n\nSo I came up with another plan.\n\nThose flying beasts eat direhorns, right? The big green flappy ones. I'm sure if you kill a few of them you'll find all the direhorn bits I need.", objectives = "" }
WordHunterWoW_QuestEN[52003] = { title = "Champion: Kelsey Steelspark", description = "", objectives = "" }
WordHunterWoW_QuestEN[52005] = { title = "Mission Report: The Wolf's Den", description = "<Your followers have sent a report regarding the assault on Wolf's Den.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.>", objectives = "" }
WordHunterWoW_QuestEN[52008] = { title = "Champion: Magister Umbric", description = "", objectives = "" }
WordHunterWoW_QuestEN[52012] = { title = "Wolves For The Den", description = "Our scouts have spotted a large pack of dire wolves not far from here. This is a good omen!\n\nWe should send a beast master to capture the wolf pack and bring them to the outpost to be tamed.\n\nThe dire wolves will make fine hunting companions and sniff out any Alliance spies that come poking around!", objectives = "" }
WordHunterWoW_QuestEN[52013] = { title = "Champion: John J. Keeshan", description = "", objectives = "" }
WordHunterWoW_QuestEN[52014] = { title = "Ritualistic Preparations", description = "I have received a request for a shipment of storm silver. It is a fine metal, lightweight and resistant to corrosion. We use it althroughout our ships. It is so strong even de naga use it in some of their weapons!\n\nHowever, any parts that go into de ship have to be blessed by a wavesinger. I can not be bothered with dat nonsense. I do not believe it needs these extra blessings, but what do I know?\n\nHarvest a bucketful of ore and get it blessed for me, and I will teach you how to mine it easier.", objectives = "" }
WordHunterWoW_QuestEN[52015] = { title = "Brined Justice", description = "{name}, I just got word dat one of our ships was attacked and a large amount of storm silver stolen!\n\nDe sacred materials can not be replaced. Once it is blessed by de wavesinger, it is buried underwater for a year. While I do not care for such nonsense, others do, and will not sail on dat ship.\n\nFrom what I heard, a group of naga followed de ship to see where the metal was buried on de sea floor before killing de crew and taking her cargo.\n\nKill de naga, and get me dat metal!", objectives = "" }
WordHunterWoW_QuestEN[52016] = { title = "Three Sheets to the Wind", description = "You want to know more about storm silver?\n\nFine, if you are mining from a seam and make a mistake, you can make a deadly cloud of powderized metal. Now go.\n\n<After a moment Secott's face softens.>\n\nI am very busy, but if you insist on not dying, you should talk to my former apprentice, Biru. He is a drunk at Spirits Be With You, but he has some knowledge.\n\nTalk to Ximo, de Innkeeper, and buy him a drink. If he likes it, he'll talk, if not... well, I hope you have enough coin for more drinks.", objectives = "" }
WordHunterWoW_QuestEN[52017] = { title = "Back to Biru", description = "Oh, you are still here?\n\nWell, I wish I could help you but being de only goldsmith in de city of gold, I am unsurprisingly busy.\n\nI heard you had built a rapport with Biru. I'm sure he remembers more, if you're still looking for more information.\n\nAsk him if he can show you anything else. Tell him if he keeps you from bothering me for the rest of de day, I will stop sending fool hardy miners to him.", objectives = "" }
WordHunterWoW_QuestEN[52023] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "" }
WordHunterWoW_QuestEN[52024] = { title = "Informing the Horde", description = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts.\n\nWere it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive.\n\nWe must inform our allies of what has transpired in Vol'dun.\n\nI'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now.\n\nI'm sure our paths will cross again, {name}. It was an honor fighting with you.", objectives = "" }
WordHunterWoW_QuestEN[52026] = { title = "Overseas Assassination", description = "Ready to go to war, {name}?\n\nMathias Shaw has assembled a list of priority Horde targets, and the first is an influential blood elf by the name of Arlethal Sunwatcher. Intelligence shows that he's the highest ranking member of the Reliquary, an elite blood elf excavation force.\n\nHe's just standing out in the middle of the desert in Vol'dun, practically begging to be assassinated. Shall we?", objectives = "" }
WordHunterWoW_QuestEN[52027] = { title = "The Vol'dun Plan", description = "Our target: Arlethal Sunwatcher, High Examiner of the Reliquary.\n\nBefore we charge off blindly into the dunes, however, I'd like to hold a quick strategy meeting with you and the others.", objectives = "" }
WordHunterWoW_QuestEN[52028] = { title = "Comb the Desert", description = "It's time to mobilize, then.\n\nI'll stick with you, {name}. Keep an eye out for Horde activity.", objectives = "" }
WordHunterWoW_QuestEN[52029] = { title = "Dirty Work", description = "That surveyor is wearing a Reliquary tabard. Sunwatcher must be hiring goblins to do his dirty work while he lounges somewhere in the shade.\n\n<Shandris nocks an arrow in her bow.>\n\nLet's find out what she knows.", objectives = "" }
WordHunterWoW_QuestEN[52030] = { title = "Keep Combing", description = "Guzbert will be busy planting explosives for a while. We should continue south, looking for more signs of the Horde.", objectives = "" }
WordHunterWoW_QuestEN[52031] = { title = "Classic Reliquary", description = "Another goblin surveyor, and this one's reporting to a blood elf overseer of some sort. We're closing in on them, {name}.\n\nYou know the drill.", objectives = "" }
WordHunterWoW_QuestEN[52032] = { title = "Never Stop Combing", description = "<Halford eyes the map one last time before folding it up.>\n\nOnward to the south, then.", objectives = "" }
WordHunterWoW_QuestEN[52033] = { title = "WANTED: The Rime Huntress", description = "The Waycrest Guard is offering a reward for any hunter who can track down and eliminate the Rime Huntress from the vicinity of Highroad Pass.\n\nTrack her with caution. She is a ferocious beast, and has been known to ambush even seasoned hunters.", objectives = "" }
WordHunterWoW_QuestEN[52034] = { title = "A Message to the Zandalari", description = "I know we're here to hunt the Horde, but this is an opportunity.\n\nExiles or not, these are Zandalari trolls, and the Zandalari have all but put in their lot with the Horde.\n\nLet's show them what we do to friends of the Horde.", objectives = "" }
WordHunterWoW_QuestEN[52035] = { title = "Improvised Survival", description = "The entirety of our copter's hold was reserved for bombs. There's actually still a lot of bombs left inside. Unfortunately, that meant that we weren't able to pack sufficient water and rations for our survival.\n\nDesert natives hoard supplies efficiently. I'm certain the Zandalari trolls up ahead wouldn't miss a few lost supplies.", objectives = "" }
WordHunterWoW_QuestEN[52036] = { title = "They Have Alpacas Here", description = "Did you see? Did you see them? The floofy alpacas?!\n\nI'VE ALWAYS WANTED A... I mean, ahh, ahem! I would like to acquire an alpaca. To study. For scientific reasons. Nothing to do with floofiness at all.\n\nHere, this should help you wrangle one back here.", objectives = "" }
WordHunterWoW_QuestEN[52038] = { title = "Splitting Up", description = "<Halford looks over the map again.>\n\nThe final Reliquary digsite is southwest of here.\n\n{name}, you and Shandris are responsible for laying the explosives at the digsite. I'll work with Zoidfuse to establish a safe position to detonate from.", objectives = "" }
WordHunterWoW_QuestEN[52039] = { title = "Delayed Deathification", description = "While we can handle the assassination portion on our own, I suppose there's no harm in distributing these gnomish bombs around the enemy's digsite.\n\nThey're designed to be detonated remotely, so try to bury them in the sand where they won't be noticed.", objectives = "" }
WordHunterWoW_QuestEN[52040] = { title = "Full of Arrows", description = "There's no need for Halford's overly-complicated desert explosion operation. We can take care of Arlethal Sunwatcher right here and now.\n\nHe's right over there. We can just... kill him.\n\nYou engage him. I'll join in when he least expects it. You ready?", objectives = "" }
WordHunterWoW_QuestEN[52041] = { title = "Report to Wyrmbane", description = "Our work here is done. Halford and Zoidfuse should be further down the coast, to the east.\n\nIf you don't mind, I'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[52042] = { title = "The Big Boom", description = "Still, we've placed all those explosives, and there's nothing stopping us from detonating them and laying waste to the Horde's excavations.\n\nSpeak with Zoidfuse when you're ready, and we'll get this explosive gnome tech going!", objectives = "" }
WordHunterWoW_QuestEN[52043] = { title = "The Wrath of Grapes", description = "You look familiar. Do you owe me money? Wait... no, that's not it.\n\nIf you are here to learn, I could show you my secret mining technique, bu- Ugh...\n\nI am currently busy trying to see straight right now, amongst other things. Ugh... it feels like someone is swinging a pick at my skull. \n\nDe best cure for a hangover is pickle juice and a big greasy breakfast.\n\nTell you what, get me those things, preferably quickly and quietly, and I will teach you whatever want.", objectives = "" }
WordHunterWoW_QuestEN[52044] = { title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Myra could teach you to harvest this much every time.", objectives = "" }
WordHunterWoW_QuestEN[52046] = { title = "An Exceptional Platinum Shard", description = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks.\n\nYou wonder to yourself if Secott could teach you to harvest this much every time.", objectives = "" }
WordHunterWoW_QuestEN[52049] = { title = "X Marks the Plat!", description = "You find a folded piece of aged paper next to the deposit\n\nOpening it up, you find a map of Drustvar with an X along the western coast.\n\nSeveral crude poems adorn the paper, with one in particular drawing your attention.\n\n\"Once I were a pirate,\nlivin' for rum and pleasure.\nSince the mutiny, I've retired,\nan' now I mine for treasure.\"\n\nWhoever left this appears to have spent a significant time mining in these lands. They may have some insights you could benefit from.", objectives = "" }
WordHunterWoW_QuestEN[52050] = { title = "A More Challenging Career", description = "As ye can imagine, piratin' be in me blood. Spent many of the best years of me life lootin' and plunderin'.\n\nMe favorite part was when takin' a chest filled ta the brim with gold and jewels, and buryin' it where only ye know.\n\nAlas, that life be too chaotic for me nowadays. Swashbucklin' makes me tired, and grog makes me sick. But... I can still bury me treasure.\n\nBring me some booty worth buryin', and I'll teach ya everythin' I've learned about minin' over the years.\n\nSo, wanna be me scallywag?", objectives = "" }
WordHunterWoW_QuestEN[52052] = { title = "LFGDungeons - BFA - Raid Finder - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[52053] = { title = "The Platinum Map", description = "Nestled within the fissures of the deposit, you find a small disc of pure platinum.\n\nDusting it off, you see etchings in its surface and recognize it as a map of Vol'dun. You also notice what appears to be a small cave in the south west that has been circled.\n\nWhoever left this apparently has a wealth of knowledge of the metal and wants to be found.", objectives = "" }
WordHunterWoW_QuestEN[52055] = { title = "An Ore for an Eye", description = "I have one last request before I can go.\n\nI wish to see de sunset one last time. I have an enchantment in mind, and I have all the materials I need except de metal.\n\nI need you to bring me twenty platinum nuggets.\n\nI have asked de spirits to bring me de ore, but dey do not listen to me anymore. Dat is why I hid de map where only someone who could be of help would find it.\n\nIf you help me out, I will teach you what I can about mining platinum.", objectives = "" }
WordHunterWoW_QuestEN[52058] = { title = "A Short-Lived Peace", description = "{name},\n\nAs the Legion's presence wanes from our world, a new threat has risen. It is with a heavy heart that I must ask you to put your life on the line for the Alliance once more. \n\nI have received a disturbing message from our operatives stationed in Orgrimmar.\n\nI await your arrival at Stormwind Keep to discuss matters further.", objectives = "" }
WordHunterWoW_QuestEN[52060] = { title = "The Horde Uprising", description = "Given the potential of Azerite to change the face of warfare, it comes as no surprise that the Warchief seeks to lay claim to it. Reports indicate that she is mobilizing an army to march on Silithus--the site of the great wound.\n\nHeroes of the Horde and the Alliance fought side-by-side during the Argus campaign. To think that Sylvanas is ready to cast that unity aside...\n\nSpeak with Mathias Shaw. I want you to oversee our presence in Silithus.", objectives = "" }
WordHunterWoW_QuestEN[52061] = { title = "Taptaf the Pig!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52062] = { title = "A Disturbance in Ashenvale", description = "The damned Horde! Clever bastards, I'll give them that. They diverted at the north fork of the Barrens and are now marching on Ashenvale.\n\nThe kaldorei forces already set sail for Silithus--must be halfway there by now. The only defenders still in the area are the Darnassian City Guard. They are en route to Astranaar, but they won't last long against an army. Their commander goes by the name of Delaryn Summermoon.\n\nFind her, {name}, and buy us time. We will get our fleet there as soon as we can.", objectives = "" }
WordHunterWoW_QuestEN[52065] = { title = "Worse Than It Looks", description = "As bad as things are here we're managing to hold on.\n\nThings are actually a lot worse at Beacon Hill.  They're closer to the main attack, and will need all the help they can get.\n\nHead there and see if you can help.", objectives = "" }
WordHunterWoW_QuestEN[52067] = { title = "Survivors", description = "Patrick and Daryl Eckhart have a place north of town. If I know them, they'll be taking in survivors from Brennadam.\n\nCheck in with Patrick and see if they need any help.", objectives = "" }
WordHunterWoW_QuestEN[52068] = { title = "Helping Out, Somewhere Else", description = "You've been a big help and now we've got a lot of gold to divvy up!   \n\nYou should go west to Seabreeze Village. Treat it like a vacation, keep your mind off the gold. We'll be fine here. When you come back later, we'll have your share all ready for you.\n\nYou'd just be getting in the way here.", objectives = "" }
WordHunterWoW_QuestEN[52069] = { title = "More Fodder", description = "Leo Shealds at Deadwash is a crook, but he recognizes the threat the naga pose. He'll send men to help us if we ask, even if most are just fodder.\n\nTravel to Deadwash and ask for help.", objectives = "" }
WordHunterWoW_QuestEN[52070] = { title = "Bauer Backup", description = "We've not heard anything from the coast since the Horde attack started. I need you to check in on Lieutenant Bauer at Seabreeze Village and see that they're safe.", objectives = "" }
WordHunterWoW_QuestEN[52072] = { title = "The Light of Elune", description = "My sisters lie slain on the soft earth of Ashenvale.\n\nWe are trained to expect losses. Soldiers die in battle. But this... this was a despicable attack, even for the Horde.\n\nWe have little time to grieve, but we are not savages like our enemy.\n\nPlease, {name}. Help me say a prayer to Elune in honor of the fallen. Their wisps deserve the light of her blessing.", objectives = "" }
WordHunterWoW_QuestEN[52073] = { title = "Petitioning Krag'wa", description = "Nothing! I cannot believe de weapon had no effect!\n\nDamn Ateena and her dark magic! We must get up there somehow, kill her for good, and remove dat barrier!\n\nBut how can we get to de top of dat building... ah, of course! Krag'wa! \n\nDe loa of frogs hates de blood trolls. I am sure he will lend us his aid. Then, finally, we will be able to put an end to Ateena's madness.", objectives = "" }
WordHunterWoW_QuestEN[52074] = { title = "Deliverance", description = "Mainlander! Stop a moment, I could really use a hand!\n\nMy team and I were hunting in the ruins of Gol Koval when the stones began to attack us! I've never seen anything like that before. Ranger Wons sent Duke and I to get some medical supplies for our injured.\n\nDuke didn't get hit by those possessed stone monsters but he wasn't as fortunate with the spiders nearby. He'll be okay if he rests here for awhile, but my team needs these medical supplies!\n\nPlease take these to Ranger Wons!", objectives = "" }
WordHunterWoW_QuestEN[52075] = { title = "Boned", description = "If the living rocks weren't bad enough, it seems the undead are hauling themselves out of the ground, too!\n\nThis used to be a Drust settlement, so those are probably Drust bones. They hated us and the feeling is definitely mutual right now.\n\nI don't know what has them stirred up, but they're a danger to us and everyone else. Take them out and I'll reward you for the work.", objectives = "" }
WordHunterWoW_QuestEN[52113] = { title = "Vol'jin, Son of Sen'jin", description = "Even in da Echo Isles we have heard of da traditions of da Golden Road.\n\nWe must walk in da presence of royalty and hail da accomplishments of Vol'jin so dat his spirit be welcome here amongst da ancient kings.\n\nI shall carry da ashes, if you light da fires.\n\nKnow that any member of any other tribe may contest us. As our champion, we will need you to fend them off if they do.", objectives = "" }
WordHunterWoW_QuestEN[52114] = { title = "Honoring a True Leader", description = "Vol'jin. I have often felt our old chieftain's spirit whisperin' to me. His strength was da lifeblood of da Darkspear tribe. Some would even say he was da spirit of da true Horde.\n\nPrincess Talanji's offer is a great one. I shall travel with Vol'jin's ashes to Atal'Dazar.\n\nIf ya be wishin' to join us for dis procession, meet us upon da famed Golden Road.", objectives = "" }
WordHunterWoW_QuestEN[52116] = { title = "A Soft Glow", description = "The wisps... they sing with sorrow, but also with purpose. The forest stirs, aglow with their light.\n\nThat sound... in the distance. Could it be our Shan'do?\n\nQuickly, {name}! Malfurion beckons!", objectives = "" }
WordHunterWoW_QuestEN[52118] = { title = "Cutting Out the Competition", description = "I've never cared much for battle, but I'll be damned if those fiends think they're gettin' this mill.\n\nBest if we clear the area quickly. Grab an axe and show me what you got.", objectives = "" }
WordHunterWoW_QuestEN[52122] = { title = "To Be Forsaken", description = "Let's move. Zelling is probably with his family now.\n\nEither they're happily reunited and he helps us find Valentine... or he just helps us find Valentine.\n\nLet's go.", objectives = "" }
WordHunterWoW_QuestEN[52127] = { title = "The Wolf's Den", description = "The raid you planned on Wolf's Den in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Wolf's Den in Tiragarde Sound and establish fortifications there.\n\nWolf's Den will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52128] = { title = "Ferry Pass", description = "<Cyrus takes an official looking document from his jacket, signs it, then offers it to you.>\n\nHere, this will give you access to the ferry system.", objectives = "" }
WordHunterWoW_QuestEN[52129] = { title = "Power Problems", description = "Rozzy, part of the extraction crew, headed out with some gear to work on a plan to keep these reconfigulators all charged up.\n\nGo see see if she could use some help!", objectives = "" }
WordHunterWoW_QuestEN[52130] = { title = "Deadliest Cache: Carpe Diem", description = "Bah, don't listen to these landlubbers. They haven't fished an honest day in their lives!\n\nBefore they met me they were as dry as the sands o' the shoreline at low tide.\n\nI'll spin ye the tale o' the day we met. 'Twas also the day I saved the wharf from the biggest, meanest, largest monster o' the briny deep ye could imagine!", objectives = "" }
WordHunterWoW_QuestEN[52131] = { title = "We Need Each Other", description = "My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor.\n\nI have seen too much to believe dat.\n\nSo since my father and his advisors would not help, I turned to someone who would.\n\nYour warchief needs our fleet, and I need her champions. So here is what we need to do.", objectives = "" }
WordHunterWoW_QuestEN[52132] = { title = "The Proof of Piracy", description = "One thing pirates love more than gold is rum. So we're going to find their rum stashes and blow them up. With the rum all gone, a lot of the pirates should move on.\n\nUse my special barrel busting bombs to destroy the pirates' hidden rum stashes.", objectives = "" }
WordHunterWoW_QuestEN[52146] = { title = "Blood on the Sand", description = "And with that, our mission is done.\n\nLet's verify that Guzbert and Kelsey return safely from their demo sites, and then we can head back to friendlier shores.", objectives = "" }
WordHunterWoW_QuestEN[52147] = { title = "Crippling the Horde", description = "Our scouts report that one of Sylvanas's dark ranger captains is in Nazmir. \n\nThe dark rangers are Sylvanas's deadliest fighters and scouts. Killing one of their leaders will cripple Horde operations.\n\nShandris Feathermoon will be leading the operation in Nazmir. Head there now and strike before we lose this chance.", objectives = "" }
WordHunterWoW_QuestEN[52148] = { title = "Freehold: A Pirate's End", description = "Hey, uh, I don't usually ask for help with personal business, but I know when I'm outmatched.\n\nSomeone's gotta take down Harlan.\n\nHe's a maniac. The things I saw him do back in the day... that's why I left Freehold in the first place.\n\nH-hey don't think of it as a favor for me--even though it would be a HUGE favor--think of it as making the seas safer for everyone, or something noble like that.\n\n<Flynn leans in and whispers.>\n\nPlus there's a big fat bounty on his head!", objectives = "" }
WordHunterWoW_QuestEN[52149] = { title = "Everburning", description = "My people have suffered loss and pain, struggling in the darkness that covered Drustvar. But now we have some light back. We have the means and the will to reclaim our lands from the lingering evils. Your help has brought much of that about.\n\nI will miss my parents. Though their end was dark, they were family. But my duty as the head of House Waycrest is clear. The dead can handle themselves. I must attend to the living and lead.\n\nThere is a short ceremony I need to conduct. Would you assist me?", objectives = "" }
WordHunterWoW_QuestEN[52150] = { title = "How to Kill a Dark Ranger", description = "Let's go over the plan. We don't get many chances to kill a captain of Sylvanas's dark rangers.", objectives = "" }
WordHunterWoW_QuestEN[52151] = { title = "A Nation United", description = "You've done a fine job here, {name}.\n\nWith the city secure and Jaina in command of the fleet, the time has come for Kul Tiras to formally join the Alliance.\n\nKing Anduin has already departed for Unity Square to meet with Jaina, Katherine and the heads of the major Kul Tiran houses.\n\nThey are waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[52153] = { title = "Siege of Boralus: Lady Ashvane's Return", description = "If Ashvane thinks we will sit idly by as she attempts a coup, she is sorely mistaken.  The citizens of Boralus will fight her to a man.\n\nI'll need you on the front lines to aid them, {class}. Go with Taelia to the docks and engage the enemy. \n\nWith a little luck, we may just make it out of this alive.", objectives = "" }
WordHunterWoW_QuestEN[52154] = { title = "Our Next Target", description = "Welcome back, {name}.\n\nWe're ready to set sail on our next mission.... Now we just need to reach an agreement on where we're headed.\n\nGeneral Feathermoon and I disagree on which Horde target we should prioritize next. But if you'll give me just a moment, I'm confident I can convince her the value of my strategy and we'll be swiftly on our way.\n\nI've considered every reasonable alternative. This is the best course of action.", objectives = "" }
WordHunterWoW_QuestEN[52156] = { title = "Tortollans in Distress", description = "Our first task is to rescue the tortollans captured by the blood trolls. \n\nKeeshan's report indicates the tortollans are familiar with all things Nazmir. They should know about the Horde's operations here.\n\nThe tortollans tend to stay neutral in most matters. They'll give us details on the Horde's plans if we make a fair trade.\n\nWe'll meet afterwards at our other outpost, Redfield's Watch, north of Torga's Rest.", objectives = "" }
WordHunterWoW_QuestEN[52158] = { title = "The Savage Hunt", description = "The blood trolls in Nazmir are monsters, pure and simple. No culture, no empathy, they only exist to destroy.\n\nLet's kill 'em and let whatever dark god they worship sort them out.", objectives = "" }
WordHunterWoW_QuestEN[52170] = { title = "Ending Areiel", description = "The tortollans have given us Captain Areiel's location, as well as new information. She carries a missive from the Horde.\n\nAny missive the Horde would send to Areiel must be extremely important. We must recover it and deliver the information to Halford.\n\nAreiel and I once fought side by side. She's incredibly powerful, Keeshan and I will be there to help you bring her down.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[52171] = { title = "One Option: Fire", description = "Here I thought things couldn't get worse, but now we have the Horde making camp around the home of some death god.\n\nI've got a good idea of what they've brought, thanks to my time in the first three wars. Medicine, armor, food...\n\nAnd probably offerings for this Bwonsamdi fella. Destroy all of these supplies to let the Horde know we won't let them stay here.", objectives = "" }
WordHunterWoW_QuestEN[52172] = { title = "They Can't Stay Here", description = "Can't believe the Horde already have a foothold in the Necropolis. We have to stop them.\n\nThis one's simple. Kill as many Horde as you find in that cursed place, but keep your eye out for a fella named Bwonsamdi.\n\nSeems like he's some sort of death god. He's way beyond anything we can handle, but why not send a few of his followers his way?\n\nBetter they rot in his necropolis than bother the living.", objectives = "" }
WordHunterWoW_QuestEN[52173] = { title = "The Void Elves Stand Ready", description = "Bal'a dash, {name}. Alleria and the others have informed me of your many accomplishments here in Kul Tiras.\n\nI'm honored to join you on this mission. As a representative for the void elves, I am eager to prove to King Anduin that his trust in us was well-placed.\n\nForgive me, do not allow me to delay you.\n\nAlleria and the others can brief me on the mission as we travel. You may tell the Grand Admiral that we are ready to set sail whenever you like.", objectives = "" }
WordHunterWoW_QuestEN[52183] = { title = "When a Plan Comes Together", description = "Having Derek Proudmoore's body in our possession is a greater boon than we had planned for.\n\nValentine is risen, but I think it best to allow Derek to lay dead for a bit longer.\n\nIt's time to use our new allies to our advantage.", objectives = "" }
WordHunterWoW_QuestEN[52184] = { title = "Relics of Ritual", description = "There is a reason why I am accompanying you on this mission, and it's more than familiarity. The Abyssal Scepter is locked behind a ritual, the components for which are held by three separate lieutenants spread across the compound.\n\nYou get the relics, I perform the ritual, we grab the Scepter and we get out.", objectives = "" }
WordHunterWoW_QuestEN[52185] = { title = "A Well Placed Portal", description = "We have the front here under control. I am sending you and Zelling into Boralus to acquire the Abyssal Scepter.\n\nOculeth has managed to pinpoint a safe location for a portal. Get moving.", objectives = "" }
WordHunterWoW_QuestEN[52186] = { title = "The Bulk of the Guard", description = "If all has gone according to plan, Proudmoore has sent her elite forces to recapture her son's body.\n\nLet's make sure they stay out of the way of our real mission, hmm?", objectives = "" }
WordHunterWoW_QuestEN[52187] = { title = "Old Colleagues", description = "The people in charge of those two ships are old colleagues of mine, {name}.\n\nThey did not achieve their rank through hard work as I did, but rather through deception and blackmail.\n\nI think they deserve the hammer of karma. Or whatever weapon you prefer.", objectives = "" }
WordHunterWoW_QuestEN[52188] = { title = "Tidesage Teachings", description = "These people are not tidesages anymore. They do not deserve to bear our title, our prestige, or our knowledge.\n\nSo many of our teachings lay scattered around this monastery, potentially lost to those of us that remain.\n\nWe must reclaim these writings. Better in my hands than theirs.", objectives = "" }
WordHunterWoW_QuestEN[52189] = { title = "Forfeit Souls", description = "The tidesages here have given in to dark magics. They have submitted themselves to powers they do not understand, and my people have suffered for it.\n\nI knew them once, my brothers and sisters in the tides. But now they are lost.\n\nI guess I am too.\n\nRedeem the name of the tidesages! Kill these betrayers!", objectives = "" }
WordHunterWoW_QuestEN[52190] = { title = "Gaining the Upper Hand", description = "We need to retrieve the Abyssal Scepter and get out of here before the Kul Tirans break our line in Plunder Harbor.\n\nI did some research while you were gone. I believe I uncovered the location where the ritual must take place.\n\nWhen you are ready to go, we can make our way over.", objectives = "" }
WordHunterWoW_QuestEN[52191] = { title = "Life Held Hostage", description = "As Lilian has pointed out, it seems we have a final visitor.\n\nShall we go pay him a visit?", objectives = "" }
WordHunterWoW_QuestEN[52192] = { title = "The Aid of the Tides", description = "With Derek's body and the Abyssal Scepter in stow, our undertaking here today is complete. Let us escape under their noses.\n\nWhen you are ready, let us return to Zuldazar. Sylvanas will want to hear of our victories.", objectives = "" }
WordHunterWoW_QuestEN[52194] = { title = "What You May Regret", description = "{name}, Genn Greymane left this letter for you. He indicated it was urgent. I was just about to send for you.\n\n<Upon opening it, the letter reads as follows.>\n\"{name},\n\nYou have helped to unite the Kul Tirans and gained their support for the Alliance. Perhaps now you might be able to help reunite a mother with her daughter.\n\nMeet me at the family memorial by Proudmoore Keep. With luck we can convince Lord Admiral Proudmoore to grant her daughter a stay of execution.\n\n- Genn Greymane \"", objectives = "" }
WordHunterWoW_QuestEN[52197] = { title = "Long Away", description = "For every foe we slay, two more take their place.\n\nWe are too few in number to stand toe to toe. We must fall back, {name}. Strategy can yet overcome numbers. \n\nWe will regroup at Darnassus. I will send for Delaryn.", objectives = "" }
WordHunterWoW_QuestEN[52203] = { title = "Find the Paper Trail", description = "The High Commander's intelligence was confident that Trade Prince Gallywix is currently in Zuldazar, but my trackers could not locate him within the Bilgewater camp. He's most likely somewhere nearby.\n\nGoblins do not work for free. Someone is bound to be bossing around the rest of those miners. Locate whoever is in charge, eliminate them, and search for anything that might tell us where Gallywix is.", objectives = "" }
WordHunterWoW_QuestEN[52204] = { title = "The Void Solution", description = "The Bilgewater Cartel are serious about protecting their investment at the mining site. My trackers have reported a heavy presence of large mech suits used for breaking rocks and suppressing attackers.\n\nI am certain that you could deal with the mechs yourself, but you need not waste your time doing so.\n\nTake this void shard and use it to cast the large mechs into the Void, where they won't be able to bother anyone again.", objectives = "" }
WordHunterWoW_QuestEN[52205] = { title = "Bilgewater Bonanza Go Boom", description = "I have met very few goblins that I respect, but I must give them universal credit for one thing: they are persistent.\n\nThe Bilgewater Cartel, Trade Prince Gallywix's gang, has already sent a full set of replacement miners to extract Azerite from the beach site nearby.\n\nI am certain the Alliance will be pleased if you interrupt their mining operations again.\n\nMy regiment is available to aid you, but our combat tactics are unconventional. When you wish our help, call into the Void and we will answer.", objectives = "" }
WordHunterWoW_QuestEN[52208] = { title = "Meeting of the Minds", description = "We're in luck. The missive details a meeting in Zo'bal Ruins between Talanji, Rokhan, Areiel, and Blood Prince Dreven.\n\nThis is our chance to gain more intel on Dreven and his next move. He killed our soldiers in Vol'dun, it's time for him to pay.\n\nMeet me outside of Zo'bal Ruins. We're going to sneak into the ruins, listen to their plans, and decide what to do next.", objectives = "" }
WordHunterWoW_QuestEN[52210] = { title = "Sending Out An SOS", description = "I noticed an exodus from the fleet, far out in the harbor.\n\nFlyers were sent out, they seek something, or someone.\n\nThose ships made a great journey, and they have much work ahead.\n\nPlease check in with Captain Grez'ko. I am sure he could use a hand!", objectives = "" }
WordHunterWoW_QuestEN[52213] = { title = "Ancient Skinning Knife", description = "Within the scarred flesh of the beast, you find a notched golden blade embedded under its skin.\n\nCarefully extracting the blade, you can't help but feel like this is an old Zandalari skinning knife.\n\nYou should show this to Rana the Cutta.", objectives = "" }
WordHunterWoW_QuestEN[52214] = { title = "Ceremonial Vestments", description = "Xanjo asked dat I gather de materials for him to make some ceremonial armor.\n\nHe requested several pieces of crocolisk hide, but all de hides I have are flawed or scarred.\n\nI need you to bring me a handful of fresh crocolisk hides dat are pristine.\n\nDe best source dat I know of are de primal snapjaws in Nazmir, as their hide is usually thick enough to avoid getting scarred when dey fight.\n\nIf you do dat for me, I will show you how to better harvest scales from, well... scaly creatures.", objectives = "" }
WordHunterWoW_QuestEN[52215] = { title = "A Thicker Thread", description = "{name}! I was hoping you would show up!\n\nXanjo is nearly finished with de suit of ceremonial armor he has been working on, but dere is a problem.\n\nHe says dat de thread he used is too thin, and dat de weight of de leather is ripping out de stitching.\n\nHe asked me to get something dat will hold, and de best thing I can think of is de thick webbing of jungleweb crawlers.\n\nYou can find dem in northern Vol'dun. Bring me back some strands of their thick webbing, and my knowledge of scales is yours.", objectives = "" }
WordHunterWoW_QuestEN[52216] = { title = "Hexoskeleton", description = "I have a bet going with Xanjo over what leather is de best for armor in regards to resisting piercing and slashing attacks.\n\nHe says scales are the best, but I have something better in mind.\n\nI feel de makrura's exoskeleton could be treated to act as a natural plate armor.\n\nBring me de carapace of a bittertide makrura, and I will teach you how to harvest bones more effectively from creatures you're skinning.", objectives = "" }
WordHunterWoW_QuestEN[52217] = { title = "Loa Fit For A King", description = "Hey, {name}! Come here. Shh. Closer.\n\n<Rana's voice drops to a whisper.>\n\nI have something I want you to do for me. It may be just a touch sacreligous, but... well...\n\nRezan was once de loa of kings, but he has been taken to Atal'Dazar, and it grieves me what has happened to him.\n\nI want you to go dere, and bring me back a bone of his. Not even a whole bone. A splinter. I don't care how small.\n\nPlease do dis for me, and I will teach you everything I know about gathering bones while skinning.", objectives = "" }
WordHunterWoW_QuestEN[52219] = { title = "Target: Blood Prince Dreven", description = "We must kill Blood Prince Dreven and his followers. I know of the place where they intend to go. Here is the plan.\n\nYou and Keeshan will make your way to the tunnels and act as bait, lure Dreven into a false sense of security.\n\nMyself and the sentinels will seal the entrance to trap him and his allies shortly thereafter.\n\nThen we kill them all. I'll send word to the others to get moving.\n\nLet's go.", objectives = "" }
WordHunterWoW_QuestEN[52221] = { title = "Mission Report: Stonefist Watch", description = "Your followers have sent a report regarding the assault on Stonefist Watch.\n\nIt details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52222] = { title = "Stonefist Watch", description = "The raid you planned for Stonefist Watch in Tiragarde Sound was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Stonefist Watch in Tiragarde Sound and establish fortifications there.\n\nStonefist Watch will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52223] = { title = "Brinepinch", description = "You! {name}! I have a business proposition for you.\n\nThere is a monstrous crab nesting in some of my favorite hunting grounds.\n\nI've already been forced out of some areas because of the sirens, I'm not about to lose more to a CRAB!\n\nBring me the head of Brinepinch! In return I'll teach you how to get more leather when skinning.\n\n<Camilla pauses for a second before clarifying her thought.>\n\nSorry, most creatures that wrong me have heads. Just bring me some part of it as proof of its death.", objectives = "" }
WordHunterWoW_QuestEN[52224] = { title = "Ivory Handled Dagger", description = "While skinning the beast, you feel a lump within the beast's stomach.\n\nInvestigating further, you find what appears to be a dagger with a beautifully etched ivory handle.\n\nCarefully extracting it, you wonder if Camilla Darksky might know something about this.", objectives = "" }
WordHunterWoW_QuestEN[52225] = { title = "In Pursuit of Fashion", description = "Despite me REPEATEDLY stating that I'm not a leatherworker, one of the fat nobles of this city has commissioned me to make him a belt of 'the finest saurolisk' hide.\n\nSo... I'm just going to get the materials together, give them and some of the gold to Cassandra to make the actual belt, and pocket the difference.\n\nThat said, I need you to bring me saurolisk leather, enough to circle a very wide lord.\n\nFor your efforts, I'll look at the skins and see if I can give you pointers on how to harvest more.", objectives = "" }
WordHunterWoW_QuestEN[52226] = { title = "Turtle Soup", description = "I cannot believe that I'm constantly stuck in this city!\n\nYou'd help me out, right?\n\nYou see, I've heard about these turtles that have been living in hot springs.\n\nWhat makes it interesting is that some of the sulphur from the water has soaked into their scales to give them interesting patterns.\n\nI'm too busy to go check myself, but if you could go get me some of their skins, I'd be more than willing to teach you everything else I know about skinning anything with scales in exchange.", objectives = "" }
WordHunterWoW_QuestEN[52227] = { title = "Bone Needle", description = "<You see Camilla sucking blood from a wound on her hand.>\n\nHey, can you do me a favor? I was sewing shut a battle wound in this skin, when my last bone needle broke, and now I need to get a new one.\n\nI've seen quilrats on the coast of Drustvar, one of their spines should do the trick.\n\nBring me one in perfect condition, and I'll teach you how to harvest more bones when skinning.\n\n<Camilla looks at her hand.>\n\nNow, if you'll excuse me, I need to go see a healer before this gets infected.", objectives = "" }
WordHunterWoW_QuestEN[52228] = { title = "Atal'Dazar: An Unbreakable Bone Needle", description = "Hey, {name}, lookin' for work?\n\nI've heard through Alliance Intelligence that the trolls have a dead god or something similar. 'Rezan' I think was the name, over in Atal'Dazar.\n\nAfter the last time I broke a bone needle, I can't help but think that one made from the bone of a god has got to be indestructible, right?\n\nI want you to retrieve one of his bones. Or at least something big enough that I can carve an eye in and use.\n\nIn return, I'll show you everything that I know about harvesting bones.", objectives = "" }
WordHunterWoW_QuestEN[52234] = { title = "Hidden Amongst the Leaves", description = "When the Horde invaded, I did my best to thwart them but it is unknown how many forces have made passage already. This wall will slow them down, but it will not halt their attack entirely. \n\n<Malfurion's ears perk.>\n\nDo you hear that, hero? The Ancients call to us!\n\nWe must protect them at all costs, {name}! They see what our eyes cannot see, and hear what our ears cannot perceive.\n\nI have druids in the Twilight Vale. Find them. Send them to the Grove of the Ancients. I will reinforce the wall.", objectives = "" }
WordHunterWoW_QuestEN[52240] = { title = "Garden Grove", description = "Curse those goblins and their infernal machines!\n\nThey are using a shredder to desecrate our sacred grove. \n\nWe need that monstrosity taken down!", objectives = "" }
WordHunterWoW_QuestEN[52241] = { title = "A Greedy Goblin's Paradise", description = "The Zandalari have many powerful and ancient artifacts tucked away on this island, hidden from view.\n\nBut some of their treasures are more... conspicuous.\n\nIt is no surprise that Trade Prince Gallywix was unable to resist the allure of Atal'Dazar, a massive city made entirely of gold.\n\nCome with me and we will hunt him down together.", objectives = "" }
WordHunterWoW_QuestEN[52242] = { title = "The Wake of Something New", description = "<Onu bellows in pain.>\n\nThe disturbance has become more severe. I am sensing a powerful force in our midst. It is unlike anything I have felt before. It comes from the earth itself.\n\nYou and Delaryn Summermoon must seek it out, {name}. Go to the water's edge, to the place you call Nazj'vel.", objectives = "" }
WordHunterWoW_QuestEN[52245] = { title = "Enraged Furbolgs", description = "The ancients of the forest are all connected to one another. We can sense a disturbance from deep within our roots. \n\nI can feel it now, {name}... the rumble of their footsteps in the distance, the thundering clamor of war. With every branch they break, they awaken the ancients.\n\nSoon my brethren will answer in kind, for nothing shall disrupt the balance of nature. \n\nA disturbance is near. Our kindred spirits cry for help. Seek it out and restore balance.", objectives = "" }
WordHunterWoW_QuestEN[52246] = { title = "Lost Shipment", description = "I let grief cloud my judgment and Jaina may have already paid the ultimate price for my mistake. Yet, I hold out hope she lives.\n\nI do not know where Jaina was taken after Ashvane's people took her from the Keep. The records in their offices here in Boralus will surely tell you where they took her.\n\n{name}, you helped my people when I thought I did not need it. I ask for your help again now. Save my daughter's life!", objectives = "" }
WordHunterWoW_QuestEN[52247] = { title = "Chasing Gallywix", description = "Look at this... The goblins are looting ancient ornamentation like they're hoarding food at a buffet. What a disgrace.\n\nBut we do not have time to get bogged down in everything happening here. Gallywix will soon know that we have arrived.\n\nWe should not hesitate in ascending these stairs and locating Gallywix. I am certain that he will be wherever the thieves are carrying their treasure.\n\nOh, and please do take care. The Zandalari do not typically leave places like this unguarded.", objectives = "" }
WordHunterWoW_QuestEN[52252] = { title = "An Explosive Entrance", description = "A hat and some smooth talking won't get us in to Freehold this time, so I'm thinking explosives. And I'm thinking we steal them from Ashvane. Fair's fair, right? She takes something from Lady Katherine, we take some Azerite empowered grenades from Ashvane.\n\nOkay, so it's not really the same, but you get where I'm going with this.\n\nHead over to Ashvane's Foundry. Grab the biggest Azerite Grenades you can get your hands on.\n\nWhile you do that I'm going to get us some air support.", objectives = "" }
WordHunterWoW_QuestEN[52253] = { title = "The Keys to Success in Freehold", description = "I've been known to be a betting man, and I'd place good odds on the information we need being in Harlan Sweete's Strongbox. This would be far too valuable to put anywhere else. I bet they haven't even moved the chest. The problem is the security features.\n\nSee, the chest is locked by three keys and he gave each one to a different lieutenant. We'll need to get those.\n\nBut between your skills, my finesse and Taelia's air support this will be easy.", objectives = "" }
WordHunterWoW_QuestEN[52256] = { title = "Malfurion Returns", description = "Do you hear his voice?\n\nMalfurion seeks our aid! Keep your head high, {name}. The ancients stand with you this day.", objectives = "" }
WordHunterWoW_QuestEN[52257] = { title = "\"Rock\" The World", description = "We do not fight alone, {name}.\n\nThis day, the ancients will bear you in their branches. Hold back nothing in your defense of our forests!", objectives = "" }
WordHunterWoW_QuestEN[52258] = { title = "She Sells Seashells", description = "Papa wanted to go fishing, and mum is working, so he brought me along.\n\nBut I'm bored! I'm trying to sell some of the shells I found washed up on the beach, but nobody seems to be stopping. I don't think my shells are pretty enough...\n\nYou don't seem like you're afraid of those big snakes on the beach. Can you bring me back some prettier shells? Only the shiniest please!", objectives = "" }
WordHunterWoW_QuestEN[52259] = { title = "I Take No Pleasure In This", description = "I knew that Gallywix was selfish and wasteful, but this... this is too much.\n\nHis bloated pride has blacked out the sun of good leadership. He hoards the wealth of his people to satiate his gluttony, greed, and lust while his people toil under his calloused heel.\n\nAnd, maybe worse, opportunistic socialites from all across the Horde revel in the depravity.\n\nAll people of Azeroth deserve better than this. We must teach these spoiled cowards a lesson.", objectives = "" }
WordHunterWoW_QuestEN[52260] = { title = "We Have Him Cornered", description = "Did you hear Gallywix barking orders to his servants and thugs? Still concerned with frivolities as we edge ever closer.\n\nHe feels safe in his petulant palace of profits. He should not.\n\nEven here, we will strike down Trade Prince Gallywix. For the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52261] = { title = "Gallywix Got Away", description = "I must confess my disappointment that we were not able to bring an end to Gallywix's greedy reign today.\n\nBut I blame no one but myself, and will report the same to the High Commander. Your performance was exemplary, just as I expected.\n\nI hope the Alliance will not lose faith in the void elves because of this. We have much to offer.\n\nWhen you're ready, I will open a final Void portal to take us back to Boralus.", objectives = "" }
WordHunterWoW_QuestEN[52275] = { title = "Mission Report: Swiftwind Post", description = "Your followers have sent a report regarding the assault on Swiftwind Post.\n\nIt details that victory was hard-fought, but all of the wicker beasts previously infesting the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52276] = { title = "Swiftwind Post", description = "The raid you planned for Swiftwind Post in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Swiftwind Post in Drustvar and establish fortifications there.\n\nSwiftwind Post will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52279] = { title = "A Looming Threat", description = "If we hope to push the Horde out of our lands, we must call upon all the strength our people have to offer.\n\nGo, seek out the druids, the priestesses, our sentinels! Make the call to arms, and watch as the kaldorei rise to action. Only together can we hope to end the stalemate at the Wildbend River.\n\nWhen you are finished, report to Malfurion Stormrage. He awaits our fleet in Rut'theran Village.", objectives = "" }
WordHunterWoW_QuestEN[52281] = { title = "Under the Cover of Swiftwing", description = "Aye! So we be the first in this crazy operation. We'll be hitchin' a ride on Swiftwing to tha Isle of Fangs.\n\nThe Zandalari got one of their main ships there, called the Breath of Pa'ku, whatever that is.\n\nHop on ta Swiftwing when yer ready te go. It's gonna get real cozy on there with all of ye comin' aboard.", objectives = "" }
WordHunterWoW_QuestEN[52282] = { title = "How to Sink a Zandalari Battleship", description = "Let's go over our plan of attack, but remember above all things, the Zandalari cannot know our full forces are here.\n\nIf they were to discover an Alliance base within the shadow of their empire... we would be wiped out in an instant.", objectives = "" }
WordHunterWoW_QuestEN[52283] = { title = "Sabotaging the Pa'ku", description = "Our first job is to plant some bombs along these ships. I'll take care of the smaller ships, you deal with the Breath of Pa'ku.\n\nWhatever that means.\n\nKelsey says these bombs are the latest in gnome technology. We plant 'em and she can detonate them at any time.\n\nLet's get moving, and remember, this whole plan works as long as they don't see us plantin' these bombs.", objectives = "" }
WordHunterWoW_QuestEN[52284] = { title = "Ship Logs", description = "We've got mogu and Zandalari working together on the Breath of Pa'ku. They've got records on the Zandalari fleet's ships.\n\nWe've been making educated guesses regarding the Zandalari fleet. It's time to upgrade our intel.\n\nGo in there and get the naval records from anyone on board that ship.\n\nOh, and take these jet boots. You'll need them to reach the boat if you're planting bombs on the hull.", objectives = "" }
WordHunterWoW_QuestEN[52285] = { title = "The Enlarged Miniaturized Submarine", description = "Our next target is a ship docked in a place across from here, the Warport Rastari.\n\nLucky for you, I can get us all there in my enlarged miniaturized submarine.\n\nShandris Feathermoon and Magister Umbric should be waiting for you on the coast of Warport Rastari.\n\nLet's get going!", objectives = "" }
WordHunterWoW_QuestEN[52286] = { title = "Right Beneath Their Nose", description = "We must continue with our primary goal, plant bombs on major Zandalari ships. There is one docked within the Warport.\n\nYou know what to do. Get beneath the boat, plant the bombs, and ensure no one sees... a blood troll using bombs.\n\nMy invisibility flask will give you the stealth you need, and Umbric believes the ritual will give you some other power to tap into.", objectives = "" }
WordHunterWoW_QuestEN[52287] = { title = "Intelligence Denial", description = "There are three Horde spymasters stationed within Warport Rastari. They are giving the Zandalari information on the Alliance fleet.\n\nWe need these targets killed. We cannot allow the Zandalari to get any advantageous information on our fleet.\n\nLuckily for us, your blood troll disguise means any witnesses will believe this to be a bold attack by the blood trolls.", objectives = "" }
WordHunterWoW_QuestEN[52288] = { title = "Void Vacation", description = "The Horde have sent emissaries to help with their potential alliance with the Zandalari. \n\nThese emissaries are also sharing secrets that the Horde have regarding the Alliance. We need to put a stop to this.\n\nTake this orb. It will create a void portal above the target and pull them... somewhere else.", objectives = "" }
WordHunterWoW_QuestEN[52289] = { title = "Victory is Assured", description = "Our task is finished. You've planted the bombs on two of the Zandalari's major flagships, and Keeshan has helped with the remainder.\n\nLet's return to Halford, the sooner we're done here, the better. It's far too risky for us to be at the Zandalari's doorstep.", objectives = "" }
WordHunterWoW_QuestEN[52290] = { title = "My Enemy's Enemy is My Disguise", description = "We need you to kill several targets within Warport Rastari, but we also cannot reveal that the Alliance is here.\n\nUmbric has uncovered a ritual from Nazmir that will grant you a blood troll disguise. It is grim, but it must be done.\n\nYou will go through with the ritual, then use my invisibility flask to sneak into the Warport. \n\nIf discovered, the Zandalari and Horde will think it's a bold attack from the blood trolls... and not from the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[52291] = { title = "Victory Was Assured", description = "Kelsey brought back the records you retrieved on the Isle of Fangs, but it was too late.\n\nWhat you see before you is Gral's Call, the missing Zandalari flagship, and they've spotted us.\n\nIf they make it back to port, we will have the full fury of the Zandalari empire brought down upon us.\n\nWe must board the ship and eliminate every Zandalari on board.\n\nFalstad will get us there. Let's move.", objectives = "" }
WordHunterWoW_QuestEN[52294] = { title = "Fallen Idols", description = "Little creature, please... listen to me. \n\nI am Krag'wa. \n\nOnce, my worshipers were many and my powers great. Now, my followers are all but gone. What little power I have left was placed within several idols, but the idols have been stolen by the heretical blood trolls.\n\nI ask you, please recover my idols so that I can become whole once more!", objectives = "" }
WordHunterWoW_QuestEN[52305] = { title = "Nature Versus Nurture", description = "Greetings, {name}. I am Wingminder Goja.\n\nI overheard the ordeal that Pa'ku has laid at your feet. I can help you.\n\nI oversee this roost at my loa's pleasure. I have seen many eggs become glorious beasts of war. It will be a long road ahead, with many trials to overcome, but de companionship of a pterrordax be a worthy reward.\n\nFor now, de little one is young. Simply tend to his needs while he stays in de nest. When he is ready to take on de world he will let you know.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[52308] = { title = "Intercepted Orders", description = "Good to see you again, {name}.\n\nMathias and I are discussing what to do with new intel that his SI:7 agents procured for us.\n\nThe intercepted letter contains orders from Warchief Sylvanas for an operation the Horde is undertaking at sea.\n\nThis could be a rare opportunity, or a distraction. The letter is purposefully light on details, and it's unclear if we should make this a top priority or focus on our other missions.\n\nDo you have a moment to talk through this with Mathias and me?", objectives = "" }
WordHunterWoW_QuestEN[52311] = { title = "Sweete's Strongbox", description = "You've got the keys, and Taelia's still watching our backs. So let's head up to Sweete's, ah, \"office\" and liberate the documents in that strongbox.\n\nCome on, it's across the bridge with the rest of his treasure.", objectives = "" }
WordHunterWoW_QuestEN[52313] = { title = "Mission Report: Mudfisher Cove", description = "Your followers have sent a report regarding the assault on Mudfisher Cove.\n\nIt details that victory was hard-fought, but all of the guards previously defending the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52314] = { title = "Mudfisher Cove", description = "The raid you planned for Mudfisher Cove in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mudfisher Cove in Drustvar and establish fortifications there.\n\nThe cove will be an essential outpost in our campaign against the Alliance.\n\nMove quickly!", objectives = "" }
WordHunterWoW_QuestEN[52317] = { title = "No Ptake, Only Throw", description = "<Kua'fon places a troll skull into your palm. It is covered in teeth marks and rather slimy.>\n\nSkree!\n\n<Kua'fon peers at you expectantly.>", objectives = "" }
WordHunterWoW_QuestEN[52319] = { title = "Mission Report: Windfall Cavern", description = "Your followers have sent a report regarding the assault on Windfall Cavern.\n\nIt details that victory was hard-fought, but Gravemaul has been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52320] = { title = "Windfall Cavern", description = "The raid you planned for Windfall Cavern in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Windfall Cavern in Stormsong Valley and establish fortifications there.\n\nWindfall Cavern will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52428] = { title = "Infusing the Heart", description = "Azeroth's voice is growin' fainter and fainter. If the seal on this chamber shatters, her soul will be lost!\n\nWe've got one chance tae save us all.\n\nAbsorb the Azerite around the chamber into the Heart of Azeroth. Then unleash the amulet's power tae seal that crack in the center of the seal.\n\nAzerite can be a destructive force, but if it's channeled through yer amulet, it can heal the world!", objectives = "" }
WordHunterWoW_QuestEN[52431] = { title = "No-Landing Zone", description = "These pirates are ruthless - they're bringing in landing boats to cut off our escape!\n\nThe guards are down at the riverside holding them off, but I'm afraid they'll be overrun before my family and I can get away!", objectives = "" }
WordHunterWoW_QuestEN[52436] = { title = "The Blackwood Den", description = "We have not moved all of our troops into Darkshore yet, but I think we have enough to justify establishing a foothold somewhere. I know just the place.\n\nJust south of here is the Blackwood Den. Its inhabitants, the Furbolgs, have been driven in to a hysteria. With our enemies pouring from the North, the Furbolg threat is a nuisance we cannot afford. \n\nI will lead another squad past the wall while you... negotiate with the Furbolgs.", objectives = "" }
WordHunterWoW_QuestEN[52437] = { title = "The Start of Something Good", description = "While the rest of our army sets up camp -- you should follow me. I spotted something... interesting... on my way back from Zoram'gar.\n\nI'll admit, not even I could have predicted such fortuitous happenstance.\n\nCome with me, {name}. And bring a pickaxe.", objectives = "" }
WordHunterWoW_QuestEN[52438] = { title = "A Wild Ride", description = "Let me tell ya, kid... this may be some of the best work I've ever done!\n\nNow that the upgrades are in place, there's no time to waste.\n\nThe battle is raging over at Wildbend River. Take the modified hellion into battle and give 'em hell!", objectives = "" }
WordHunterWoW_QuestEN[52439] = { title = "Iron Stores", description = "While the mine is under Alliance banners our workers ensure the iron supply never runs dry.\n\nThis key will provide access to the stores. Take what you need.", objectives = "" }
WordHunterWoW_QuestEN[52440] = { title = "Resource Recruitment", description = "If we're to maintain our iron supply we'll need a bit of help.\n\nSee if you can wrangle us up a few fresh recruits for the mine.", objectives = "" }
WordHunterWoW_QuestEN[52443] = { title = "The Final Foothold", description = "We have established two critical footholds in Zandalar. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[52444] = { title = "The Final Foothold", description = "We have established two critical footholds in Kul Tiras. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[52445] = { title = "Tol Dagor: The Fourth Key", description = "Hey, wait a second. I know the type of key our fourth lock needs. This is the same sort of lock the Ashvane company uses. Resists lockpicks like nothing else, but they have a standard skeleton key. There was a set hanging on the wall in the Tol Dagor Armory. Given the state we left it in, it'd be easy to grab it.\n\nTaelia and I will take the chest back to the Harbormaster's office for safe keeping. \n\nYou go in to Tol Dagor and get that last key!", objectives = "" }
WordHunterWoW_QuestEN[52447] = { title = "Room To Grow", description = "Ah, I would not worry too much about de little one.\n\nSome beasts take longer than others to find their way, and Kua'fon is no exception.\n\nFor now, continue to help him grow. Keep him fed, keep him out of danger, and strengthen your bond. He will let you know when he is ready to try again.", objectives = "" }
WordHunterWoW_QuestEN[52449] = { title = "The Mysterious Island", description = "Fate's End is just that. It's where the very worst criminals are sent. No one ever comes back.\n\nI'm sorry Lady Katherine will have to hear this, but I'm glad it isn't my job to tell her.\n\n<Flynn hands you the document solemnly.>\n\nI'm certain she'll want an update, even if the news is as bad as this.", objectives = "" }
WordHunterWoW_QuestEN[52450] = { title = "Uniting Kul Tiras", description = "", objectives = "" }
WordHunterWoW_QuestEN[52451] = { title = "Uniting Zandalar", description = "", objectives = "" }
WordHunterWoW_QuestEN[52453] = { title = "A Forlorn Hope", description = "<Lady Katherine's jaw sets.>\n\nI refuse to believe I am too late.\n\nNo one has ever come back from Fate's End, but if anyone could survive I have to believe it would be my Jaina.\n\nGo to Stormsong Valley and secure transit to Fate's End from the tidesages. Brother Pike is a good place to start.\n\nHurry, {name}.", objectives = "" }
WordHunterWoW_QuestEN[52462] = { title = "A Load of Scrap", description = "Hello, friend. Would you like the scoop on the latest invention of the century?\n\nIt's called the Scrap-O-Matic 1000 and this device can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other gizmos you adventurers wander around with.\n\nHere, take these pants and use the Scrap-O-Matic on 'em. You'll get the hang of it.", objectives = "" }
WordHunterWoW_QuestEN[52467] = { title = "Battlefield Scavenging", description = "Our efforts to reclaim the keep have left our supplies a bit lighter than we anticipated. If our forces are to continue, we'll need to restock.\n\nCheck the enemy camps for anything of value. We'll make use of what you find.", objectives = "" }
WordHunterWoW_QuestEN[52468] = { title = "Raiding Their Stores", description = "Our rations are low. We need to keep our forces fed if we're to continue our efforts.\n\nBefore it was overrun, Newstead had plenty of food in their stores. I only hope there's something left.", objectives = "" }
WordHunterWoW_QuestEN[52472] = { title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", objectives = "" }
WordHunterWoW_QuestEN[52473] = { title = "Bringing Down the Fleet", description = "This is it, {name}. We've weakened the Horde enough to make a daring strike on Zuldazar itself.\n\nOur forces in Zuldazar still remain hidden, thanks to the help of the Dark Iron dwarves. That gives us our chance to strike.\n\nSet sail to Zuldazar. We will be gathering our forces there for a coordinated strike to weaken their harbor defenses.", objectives = "" }
WordHunterWoW_QuestEN[52477] = { title = "WANTED: Ayame", description = "Wanted: For the death of twelve pilgrims and their escort to Torga's Rest. A reward is offered to anyone who brings in the head of the great serpent, Ayame. \n\n-Korkush", objectives = "" }
WordHunterWoW_QuestEN[52478] = { title = "Mission Report: Hillcrest Pasture", description = "Your followers have sent a report regarding the assault on Hillcrest Pasture.\n\nIt details that victory was hard-fought, but the Stormsong defenders have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52479] = { title = "Hillcrest Pasture", description = "The raid you planned for Hillcrest Pasture in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Hillcrest Pasture in Stormsong Valley and establish fortifications there.\n\nHillcrest Pasture will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52480] = { title = "WANTED: Ayame", description = "Well equipped exterminator wanted.\n\nHuge snake seen lurking north of Fort Victory. \n\nReward offered for anyone who brings in the head of the pest.\n\n-Garrick Blacksteel", objectives = "" }
WordHunterWoW_QuestEN[52481] = { title = "Of Myth and Fable", description = "If Jaina is truly trapped in the Blighted Lands, that could mean we're not too late! We just need to find a way inside...\n\nWe will need to enlist the help of Lucille Waycrest. The legends of that place are deeply rooted in Drustvar's culture. If anyone would know more about it, it would be she.\n\nI will send a raven ahead for her to prepare what knowledge she can gather. Make haste to Arom's Stand!", objectives = "" }
WordHunterWoW_QuestEN[52482] = { title = "The Old Bear", description = "I cannot change your mind, can I? Very well, I may know where you can find your answers. \n\nHigh in the mountains, there is a hidden alcove of impossibly verdant growth. It is there that the druids of Kul Tiras train in the old ways of the Drust - from before the time of Gorak Tul.\n\nTheir leader is a great bear named Ulfar. I know little about him, but few are more qualified to parse the magic of the Drust.\n\nYou will find a path to his den along Highroad Pass. Good luck, Inquisitor.", objectives = "" }
WordHunterWoW_QuestEN[52483] = { title = "Nightmare Catcher", description = "The effigies crafted by the followers of Gorak Tul were made not of wood, but of the bones and sinew of their enemies. This will be your first task.\n\nTravel to Gol Osigr where the ancient Drust have awoken from their slumber. The bones here belong to Gorak Tul's greatest soldiers who stood with him at the final battle against the first Lord Waycrest.\n\nTheir bones seethe with hatred and anger. This will serve your needs well.", objectives = "" }
WordHunterWoW_QuestEN[52484] = { title = "Buried Power", description = "Since time immemorial, the Drust have used runes to shape their magics. This remains true of the spells woven by Gorak Tul and his ilk. You will need some of these runes for your effigy to be effective.\n\nIt is likely that some still exist at the site of his final battle, buried under years of soot and snow. \n\nTake this stone. It is empowered with the magic of the Thornspeakers and will react to Tul's spells. With it, you should be able to locate the runes, no matter how deep the ages have buried them.", objectives = "" }
WordHunterWoW_QuestEN[52485] = { title = "Hatred's Focus", description = "An effigy requires a central focus. The coven are fond of using animal skulls for this purpose, but for your task you will need something much more potent.\n\nKorvash was a trusted lieutenant to Gorak Tul, as well as a powerful sorcerer, until he was defeated at the battle of Arom's Stand. His bones remain at the site of his demise, now buried by the years.\n\nFind them, and take his skull.", objectives = "" }
WordHunterWoW_QuestEN[52486] = { title = "Waycrest Manor: Draining the Heartsbane", description = "The skull you have taken from Korvash needs to be steeped in Gorak Tul's magic to grant the power needed to bridge the gap to Thros. You must take it to a font of his power, and let it absorb his magic.\n\nYou will find one such font in Waycrest Manor - the epicenter of the coven's power. Here, their leader has tapped so freely into Tul's power that it emanates from the very walls.\n\nBring Korvash's skull to the heart of the manor and let it feast. Then, the effigy will be complete.", objectives = "" }
WordHunterWoW_QuestEN[52487] = { title = "Into Darkness", description = "I didn't think you would find a way. Though at this point, I guess I shouldn't be surprised when you accomplish what seems impossible.\n\nI guess all that is left is to brave the Crimson Forest and see if this thing works.\n\nFirst, however, Katherine has ordered me to send word when you have found a way to Jaina. You can use one of our falcons to take a message to her.", objectives = "" }
WordHunterWoW_QuestEN[52488] = { title = "Runic Resistance", description = "Whatever is going on with this effigy, I don't think it's going to open the gateway without our help.\n\nThese runes must be the key. There must be some way we can use them to activate the effigy.", objectives = "" }
WordHunterWoW_QuestEN[52489] = { title = "Hunting Blood Prince Dreven", description = "Between the information I gathered from my scouting mission and Mathias Shaw's intel, we know exactly where Blood Prince Dreven is going to be.\n\nWe will have our revenge, {name}. For ourselves, for my sisters, for the Alliance.\n\nWe won't underestimate the san'layn this time. We will keep the Horde off-balance and distracted with swift, targeted, ruthless attacks.\n\nThankfully, the Wildhammer are masters of those combat tactics. I'm glad they'll be joining us.\n\nAre you ready to leave?", objectives = "" }
WordHunterWoW_QuestEN[52490] = { title = "Behind Enemy Boats", description = "This is where our information ends, {name}.\n\nBlood Prince Dreven is lurking in one of those Forsaken boats, but we don't know which boat or which section of that boat he's in.\n\nWe'll split up and hit the boats simultaneously, so the Horde has less time to react.\n\nIf Dreven isn't on the boat you scout, abandon it and join me on the other one. If he's not on my boat, I'll do the same. \n\nWe'll take down Dreven together.\n\nDon't get distracted. Our resources are limited. Dreven is our only target today.", objectives = "" }
WordHunterWoW_QuestEN[52491] = { title = "Broadside Bedlam", description = "<The ship's cannons are currently pointed at the other Forsaken ship across the water.\n\nHowever, it appears the crew hasn't loaded them with gunpowder or cannonballs yet... Probably to avoid any accidental firings while they're anchored here.\n\nYes, it'd be a real shame if \"accidental\" cannon fire damaged the other ship.>", objectives = "" }
WordHunterWoW_QuestEN[52492] = { title = "The Wildhammer Specialty", description = "Well, if ye didn't find Blood Prince Dreven on yer ship, he must be hiding on the other one.\n\nI can take ye down to it, but the Horde knows we're here now. What do ye say we create some distractions to hold their attention while we hunt down Dreven?\n\nMe Wildhammers are itchin' tae let the hammers fly. Ye want to join us for the first round?", objectives = "" }
WordHunterWoW_QuestEN[52493] = { title = "An Unnatural Crew", description = "Blood Prince Dreven is here, and the situation's even worse than we thought.\n\nThat monster's training other san'layn. Every neophyte you see on this ship is another future Blood Prince Dreven.\n\nHis vile practices cannot be allowed to spread within the Horde. We're going to tear the san'layn out, right now, root and all.", objectives = "" }
WordHunterWoW_QuestEN[52494] = { title = "Foul Crystals for Foul People", description = "Blood Prince Dreven and his followers are siphoning power from blood-infused crystals to bolster their unholy abilities.\n\nDestroying those crystals will weaken Dreven before we fight him. Take out as many as you can find.", objectives = "" }
WordHunterWoW_QuestEN[52495] = { title = "Ending the San'layn Threat", description = "Blood Prince Dreven has barricaded himself in the lowest deck of this ship. He's trapped down there.\n\nDon't think that makes this easy for us. A cornered beast is more dangerous than a free one. But, if we have the will and wisdom, he can be slain.\n\nFollow me. I will break the barrier blocking his lair and we will face him together.", objectives = "" }
WordHunterWoW_QuestEN[52496] = { title = "A Clean Escape", description = "Our victory here will echo through the Horde like a warning shot.\n\nGrunts will whisper around the campfire that nowhere is safe from {name} and the Alliance.\n\nSoldiers will doubt, even for a moment, the strength of their commanders.\n\nSylvanas herself will hear the story of what we did here today, and it will infuriate her. The thought of her outraged roar when she hears the news will keep me warm tonight.\n\nLet's return to Boralus and inform the High Commander of the good news.", objectives = "" }
WordHunterWoW_QuestEN[52497] = { title = "Raiding the Boulderfist", description = "The Boulderfist have been rather active ever since the battle began. One of our scouts reported their recent raid on Galson's Lode proved rather lucrative.\n\nScout the cave to the northeast, find the iron ore they stole and steal it back.\n\nWe can't afford to let anyone else control our resources.", objectives = "" }
WordHunterWoW_QuestEN[52508] = { title = "Ritual Effects", description = "I will need some assistance in conducting the ritual to allow us to gain passage to Fate's End. To help me with that, you will require the proper items and attire.\n\nNormally I have free access to these things, but the recent upheaval has blocked myself and many of my brothers and sisters from obtaining them easily. However, the fallen tidesages across the span have all you will need.\n\nCollect a ritual knife, lantern and robes from the fallen and these so-called prophets.", objectives = "" }
WordHunterWoW_QuestEN[52509] = { title = "The Strength of the Storm", description = "The ritual I must conduct is written on a scroll. To gain access to it, you'll have to break through the dark energies the fallen tidesages have placed around it, with the power of the storm.\n\nThis relic can be used to pull purified power from the enslaved elementals. Not only will you be gaining the means to our end, you will ultimately be freeing these spirits from corruption.\n\nDefeat the enslaved elementals and then call their power into the relic.", objectives = "" }
WordHunterWoW_QuestEN[52510] = { title = "Shrine of the Storm: The Missing Ritual", description = "The ritual which allows safe passage to Fate's End is a closely guarded secret to keep the curious from venturing there and suffering the same fate as the condemned. I have never conducted it before, but there is a scroll with instructions.\n\nIt is held in the Shrine of the Storms. To access the scroll, use the staff you have empowered to break the dark energy surrounding it.\n\nCollect the Ritual of Safe Passage and bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[52511] = { title = "Opening the Way", description = "Hmm. This ritual is a bit... tricky. No matter, together we will be able to complete it.\n\nI shall begin to channel. You will need to activate the runes in the proper order. I shall leave the scroll here so you may consult it.", objectives = "" }
WordHunterWoW_QuestEN[52512] = { title = "Fate's End", description = "Fate's End is a place in turmoil. The seas froth, the air cracks with thunder. We tried to settle there once, but each settlement disappeared into the mists, every soul never to be seen again. The island did not want inhabitants.\n\nNow we send our most vile exiles there. They never return and no one knows why.\n\nShould we find and recover Jaina, she will be the first. I hope we are not too late.", objectives = "" }
WordHunterWoW_QuestEN[52513] = { title = "Lost in Darkness", description = "If people are being pulled somewhere else, it would explain why no one has ever returned. I also choose to believe it means Lady Jaina might be able to be saved as well.\n\nGo back to Lady Katherine with all speed! She will want to know of this development.", objectives = "" }
WordHunterWoW_QuestEN[52544] = { title = "The War Cache", description = "{name}. Let's talk.\n\nThis war won't be won simply by adding the Kul Tirans to our ranks. We eventually need to crush the Horde.\n\nYou and I will be leading an expedition to... disrupt the Horde operations in Zandalar. But first, we need resources.", objectives = "" }
WordHunterWoW_QuestEN[52654] = { title = "The War Campaign", description = "{name}, a moment of your time.\n\nBefore you leave Boralus, speak with Halford Wyrmbane, High Commander of the 7th Legion. He specifically requested you by name.\n\nYou can find him aboard the Wind's Redemption, which should be parked in the first slip right outside.", objectives = "" }
WordHunterWoW_QuestEN[52746] = { title = "The War Cache", description = "First things first. Remember... this is a war.\n\nWe accomplish nothing by simply adding the Zandalari to our ranks. We eventually need to crush the Alliance.\n\nYou and I will be leading operations in Kul Tiras. But first, we need resources.", objectives = "" }
WordHunterWoW_QuestEN[52748] = { title = "Eyes on the Skies", description = "You have made a great deal of progress with Kua'fon. He may not yet possess de power of flight, but he is healthy and growing.\n\nTake de success you have made and build upon it, {name}. Do not let Pa'ku's lesson dishearten you.\n\nContinue to do as you have been. Nurture Kua'fon, build his confidence in his wings. Show him de way forward and he will reward you with a bond stronger than any you have ever known.\n\nWhen his wings are large enough to shade you, we will try again.", objectives = "" }
WordHunterWoW_QuestEN[52749] = { title = "The War Campaign", description = "{name}, a moment of your time.\n\nBefore you leave the city, speak with me out on the Banshee's Wail, on the docks. I have information to discuss with you about the war against the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[52750] = { title = "Farmers Who Fight", description = "I was hoping for a squad of Proudmoore Academy's finest, but I guess you'll have to do.\n\nWhat we lack in manpower we make up for in courage! Even the farmers here won't give up their land without a fight.\n\nSend the bravest of them to me. They will fight better alongside our marines than by themselves out in the fields!", objectives = "" }
WordHunterWoW_QuestEN[52762] = { title = "A Local Guide", description = "I've spent a lot of time as a guest of the Harbormaster and I've come to understand a few things about Flynn Fairwind. If anyone can quickly help you to sort out any clues in Freehold, it will be him.\n\nFlynn's been doing work for Cyrus and can be found in the Harbormaster's office. Show him the contract and recruit him to our cause. Hurry, {name}.", objectives = "" }
WordHunterWoW_QuestEN[52764] = { title = "Journey to the Middle of Nowhere", description = "Our tidesage, Thomas Zelling, claims to have found the wreckage of Marshal Valentine's ship.\n\nTook him long enough.\n\nMarshal Valentine's body is the final piece of our plan, and it lies within that shipwreck. When you're ready, let us depart for his resting place.", objectives = "" }
WordHunterWoW_QuestEN[52765] = { title = "Deep Dive", description = "We need you to retrieve Marshal M. Valentine's body at the ocean floor below.\n\nI should warn you: this part of the ocean is going to be very deep, and very dark, and very cold.\n\nSpeak with Hobart at the starboard side of the ship. He's brought all the machinery you'll need to get to the ocean floor.", objectives = "" }
WordHunterWoW_QuestEN[52766] = { title = "Seafloor Shipwreck", description = "<static>\n\n... look for shipwreck ...\n\n<static>\n\n... east ...\n\n<static>", objectives = "" }
WordHunterWoW_QuestEN[52767] = { title = "Checking Dog Tags", description = "You are no longer able to hear Hobart's voice over the static.\n\nYou can make out the outlines of several floating bodies nearby. They have significantly decomposed, but their dog tags should still be intact.\n\nHopefully the dog tags can help identify Marshal Valentine.", objectives = "" }
WordHunterWoW_QuestEN[52768] = { title = "The Sunken Graveyard", description = "<static>\n\n...wait ... more shipwrecks ...\n\n<static>\n\n... lots of 'em ... northeast ...\n\n<static>", objectives = "" }
WordHunterWoW_QuestEN[52769] = { title = "Captain By Captain", description = "Seems like you're on your own.\n\nMore shipwrecks lie along the bottom of the sea. This must have been the location of a major battle.\n\nTime to start checking dog tags to find Marshal Valentine.", objectives = "" }
WordHunterWoW_QuestEN[52770] = { title = "Biolumi-Nuisance", description = "<static>\n\n... having trouble hearing you ...\n\n<static>\n\n... electrical interference ... bioluminescent creatures ...\n\n<static>\n\n... getting annoying ...\n\n<static>", objectives = "" }
WordHunterWoW_QuestEN[52772] = { title = "The Undersea Ledge", description = "So, now that we can hear each other again, lemme tell you what's been goin' on up here.\n\nApparently we were off by like, a league. Somethin' about undersea currents, somethin' about the tides of time, yadda yadda. I think Zelling is getting rusty.\n\nPoint is, you're not far off now. We're SURE that Marshal Valentine is right to the east of ya, in a shipwreck up on a ledge. Zelling says there's something else big up there too, but he can't tell what it is.", objectives = "" }
WordHunterWoW_QuestEN[52773] = { title = "Water-Breathing Dragon", description = "Huh. A dragon, you say? I suppose that makes sense. I mean, the Horde did utilize red dragons as part of their army during the second war, but... well, we don't talk about that very much anymore.\n\nStill, Valentine is on that ship. You're gonna have to get past that dragon one way or another.", objectives = "" }
WordHunterWoW_QuestEN[52774] = { title = "Grab and Go", description = "Nothin' left to do but grab that Marshal and bring him back up to the surface, then.\n\nThough I guess you might as well search the shipwreck for anything else of value. You spent all that time gettin' down there, and time is money.", objectives = "" }
WordHunterWoW_QuestEN[52776] = { title = "Mission Report: Stonetusk Watch", description = "Your followers have sent a report regarding the assault on Stonetusk Watch.\n\nIt details that victory was hard-fought, but the outpost has been secured.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[52777] = { title = "Stonetusk Watch", description = "The raid you planned for Stonetusk Watch in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Stonetusk Watch in Stormsong Valley and establish fortifications there.\n\nThe outpost will be essential in our campaign against the Alliance.\n\nGo with honor!", objectives = "" }
WordHunterWoW_QuestEN[52782] = { title = "Call to Arms: Stormsong Valley", description = "We've discovered a spike of Horde activity within Stormsong Valley. We cannot allow them to get the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[52784] = { title = "The Horde Slayer", description = "Wow! Keep it up, soldier! \n\nSlay a bit more Horde and you will go down in the record books among the Alliance. \n\nBut it won't be easy, the Horde have put a bounty on your head, so watch it!\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52786] = { title = "The Alliance Slayer", description = "Yes! Keep going, keep slaying those Alliance dogs!\n\nSlay a bit more Alliance and you may set a new record, {class}.\n\nBut it won't be easy, the Alliance have put a bounty on your head, so watch it!\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[52787] = { title = "Numbing the Pain", description = "The medics here are doing their best, but they've suffered heavy casualties and are strapped for healing supplies.\n\nWith a few clumps of evermoss I could mix a painkilling tincture to ease the suffering of the injured. Can you forage some from the nearby trees?\n\nI'll help get Flynn stabilized. The last thing these people need is another wounded man howling in pain.", objectives = "" }
WordHunterWoW_QuestEN[52788] = { title = "Leave None Alive", description = "Our initial assault was a success. The Dark Iron dwarves are holding the line. Now it's our turn.\n\nYou and I must cleave a path through these Zandalari and eliminate them. Our forces will handle any that remain.\n\nOur goal is to weaken their forces and find two important targets: the ship's captain and its advisor.\n\nLet's go, {name}. If we fail here, all of our efforts will be thwarted.", objectives = "" }
WordHunterWoW_QuestEN[52789] = { title = "Silencing the Advisor", description = "The ship's captain is nowhere to be found. Shandris and Falstad will handle locating him.\n\nWe must go after the ship's advisor. Kelsey's logs indicate her name is Ko'jan. \n\nShe may have methods to reach out to the mainland. We have to move before she tries to use any of them.", objectives = "" }
WordHunterWoW_QuestEN[52790] = { title = "An End to the Killing", description = "Let's return to the upper decks and see what our current status is. Shandris should be there by now.\n\nI know Shandris and Falstad well enough that they will be there with the captain of this ship, dead or alive.", objectives = "" }
WordHunterWoW_QuestEN[52793] = { title = "Circle the Wagons", description = "Darion and the girls should have been back by now.  \n\nMaybe they had trouble on the road, that old wagon is always breaking down.  I need to be sure they are safe!\n\nCan you check on them for me?", objectives = "" }
WordHunterWoW_QuestEN[52795] = { title = "A Saur Point", description = "That saurolisk has been a folktale in these hills for years. \"Sourtooth, you can smell his breath from miles away\".  \n\nToday that folktale attacked my family, almost killed my father and sister. It's time for it to die.", objectives = "" }
WordHunterWoW_QuestEN[52796] = { title = "Sometimes Less Is More", description = "I don't really hate saurolisk, but there seem to be a lot more around lately. \n\nStormsong's military used to thin out the population, but they didn't show up this year.\n\nMaybe you could do the job they didn't!", objectives = "" }
WordHunterWoW_QuestEN[52800] = { title = "Tol Dagor: The Ashvane Overseer", description = "Tol Dagor stands as a well fortified thorn in this nation's side.\n\nAs you are no doubt aware, Ashvane has taken every opportunity she could to throw any opposition into those cells. Among those in the jail are members of the Alliance that arrived alongside you and Jaina.\n\nWe now have permission and the needed muscle to free them. Meet up with Taelia on the eastern shore of the island, find the overseer, and take his key. With it, we will have access to the weapon vault and cells.", objectives = "" }
WordHunterWoW_QuestEN[52801] = { title = "Mission Report: Veiled Grotto", description = "Your followers have sent a report regarding the assault on Veiled Grotto.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[52802] = { title = "Veiled Grotto", description = "The raid you planned for Veiled Grotto in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Veiled Grotto in Zuldazar and establish fortifications there.\n\nVeiled Grotto will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52806] = { title = "A Looming Threat", description = "This stalemate is unwise to pursue. Let's regroup at the Blackwood Den.", objectives = "" }
WordHunterWoW_QuestEN[52834] = { title = "Seal of Wartorn Fate: Gold", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52835] = { title = "Seal of Wartorn Fate: Marks of Honor", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52837] = { title = "Seal of Wartorn Fate: War Resources", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52838] = { title = "Seal of Wartorn Fate: Piles of Gold", description = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52839] = { title = "Seal of Wartorn Fate: Additional Marks of Honor", description = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52840] = { title = "Seal of Wartorn Fate: Stashed War Resources", description = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "" }
WordHunterWoW_QuestEN[52851] = { title = "Mission Report: Mugamba Overlook", description = "Your followers have sent a report regarding the assault on Mugamba Overlook.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[52852] = { title = "Mugamba Overlook", description = "The raid you planned for Mugamba Overlook in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mugamba Overlook in Zuldazar and establish fortifications there.\n\nMugamba Overlook will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52855] = { title = "Alchemy is an Inexact Science", description = "Hey, look.\n\nIt worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before?\n\nOkay, okay, okay!\n\nI have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this.\n\n<Alexxi hastily pens a list of ingredients and hands it to you.>\n\nDo me a solid, eh?", objectives = "" }
WordHunterWoW_QuestEN[52857] = { title = "Held For Observation", description = "<Trader Alexxi hurriedly combines the ingredients.>\n\nThat should do it. Go on and get this down your direhorn's gullet.\n\nDon't worry, nothing could possibly go wrong with a concoction made under any kind of duress. Also, do I seem like the kind of goblin who would give you something dangerous?\n\nOn purpose?\n\n... Don't answer that. Hurry, before they stab me.", objectives = "" }
WordHunterWoW_QuestEN[52861] = { title = "Champion: Lilian Voss", description = "", objectives = "" }
WordHunterWoW_QuestEN[52876] = { title = "WANTED: War Gore", description = "By the decree of the Storm's Wake.\n\nScouts have reported that forsaken scientists have created a monster, sewn together from the bodies of our own fallen soldiers.  \n\nThis monstrosity is called, War Gore.\n\nThe individual that destroys this abomination will earn a fitting reward.", objectives = "" }
WordHunterWoW_QuestEN[52886] = { title = "Mission Report: Verdant Hollow", description = "Your followers have sent a report regarding the assault on Verdant Hollow.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[52888] = { title = "Verdant Hollow", description = "The raid you planned for Verdant Hollow in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Verdant Hollow in Zuldazar and establish fortifications there.\n\nVerdant Hollow will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52942] = { title = "Restoring Old Bonds", description = "We must speak to Grommash Hellscream and remind him of his debt to us. Everything rests on this mission, {name}.\n\nI hope your skills in diplomacy are greater than mine.\n\nBe on your guard; we do not know what to expect on the other side.", objectives = "" }
WordHunterWoW_QuestEN[52943] = { title = "Calling Out the Clans", description = "This Overlord Geya'rah has a fire inside her. I may come to like her... if she doesn't kill us.\n\nWe have but one chance. You pay homage to the symbol of each clan, and I will speak of it.\n\nShow respect--or they will show us the executioner's blade.", objectives = "" }
WordHunterWoW_QuestEN[52944] = { title = "Call to Arms: Drustvar", description = "We've discovered a spike of Horde activity within Drustvar. We cannot allow them to get the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[52945] = { title = "Bonds Forged Through Battle", description = "Geya'rah has a fiery spirit... like her mother. Perhaps facing a common foe will ease her wariness.\n\nWe subdued the ogre clans long ago. But every so often, one of their bravest--and stupidest--stirs the embers of rebellion. Today is such a day.\n\nYou and Eitrigg will join Geya'rah in putting down the ogre uprising. Prove yourself in battle and you may earn her respect.", objectives = "" }
WordHunterWoW_QuestEN[52948] = { title = "Call to Arms: Tiragarde Sound", description = "We've discovered a spike of Horde activity within Tiragarde Sound. We cannot allow them to get the upper hand.", objectives = "" }
WordHunterWoW_QuestEN[52949] = { title = "Call to Arms: Nazmir", description = "It's time to press the attack within Horde territory, {class}! Travel to Nazmir and slay as many Horde as you find.", objectives = "" }
WordHunterWoW_QuestEN[52950] = { title = "Call to Arms: Vol'dun", description = "It's time to press the attack within Horde territory, {class}! Travel to Vol'dun and slay as many Horde as you find.", objectives = "" }
WordHunterWoW_QuestEN[52951] = { title = "Call to Arms: Zuldazar", description = "It's time to press the attack within Horde territory, {class}! Travel to Zuldazar and slay as many Horde as you find.", objectives = "" }
WordHunterWoW_QuestEN[52952] = { title = "Call to Arms: Zuldazar", description = "We're getting reports of increased Alliance activity within Zuldazar. Head over there and clear them out.", objectives = "" }
WordHunterWoW_QuestEN[52953] = { title = "Call to Arms: Vol'dun", description = "We're getting reports of increased Alliance activity within Vol'dun. Head over there and clear them out.", objectives = "" }
WordHunterWoW_QuestEN[52954] = { title = "Call to Arms: Nazmir", description = "We're getting reports of increased Alliance activity within Nazmir. Head over there and clear them out.", objectives = "" }
WordHunterWoW_QuestEN[52955] = { title = "Tyranny of the Light", description = "If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound.\n\nShould the reports prove true, this is the closest they have dared approach our stronghold in quite some time.\n\nCome or stay, but make your decision quickly.", objectives = "" }
WordHunterWoW_QuestEN[52956] = { title = "Call to Arms: Tiragarde Sound", description = "Its time to hit the Alliance at the source. Travel to Tiragarde Sound and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "" }
WordHunterWoW_QuestEN[52957] = { title = "Call to Arms: Stormsong Valley", description = "Its time to hit the Alliance at the source. Travel to Stormsong Valley and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "" }
WordHunterWoW_QuestEN[52958] = { title = "Call to Arms: Drustvar", description = "Its time to hit the Alliance at the source. Travel to Drustvar and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "" }
WordHunterWoW_QuestEN[52962] = { title = "Mission Report: Mistvine Ledge", description = "Your followers have sent a report regarding the assault on Mistvine Ledge.\n\nIt details that victory was hard-fought, but the enemies surrounding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[52963] = { title = "Mistvine Ledge", description = "The raid you planned for Mistvine Ledge in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mistvine Ledge in Zuldazar and establish fortifications there.\n\nMistvine Ledge will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[52965] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[52967] = { title = "Saurfang Returns", description = "Saurfang! It's about time.\n\nLook around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. \n\nNow is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[52970] = { title = "No Small Mercy", description = "I will not slay innocents. If they do not raise arms against us, we shall spare them.\n\nEnter Lor'danel and capture any civilians you find there. They shall be questioned and then released.", objectives = "" }
WordHunterWoW_QuestEN[52971] = { title = "Seaside Rendezvous", description = "Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back.\n\nOne swift strike and we can end this threat!\n\nYou will break through their lines and slay the two commanders. Without leadership this force will crumble.", objectives = "" }
WordHunterWoW_QuestEN[52973] = { title = "A Threat from the North", description = "The Horde must have scaled the mountains of Felwood in the North. \n\nThe wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. \n\nWe must weather this attack together.", objectives = "" }
WordHunterWoW_QuestEN[52974] = { title = "Rescue Effort", description = "The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. \n\nLocate these civilians and send them to safety. We're counting on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[52975] = { title = "Action This Day", description = "Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, {name}.\n\nIf they take our ships, they will use them to sail to Darnassus!\n\nSlay the two warriors leading the attack, and the rest of them will give up the fight.", objectives = "" }
WordHunterWoW_QuestEN[52977] = { title = "The Guidance of Our Shan'do", description = "Lor'danel is overrun. The Horde... they -- they just don't relent.\n\nThere is nothing we can do, {name}. We must find our Shan'do and ask for his guidance. \n\nHe is the only one who can save us.", objectives = "" }
WordHunterWoW_QuestEN[52978] = { title = "With Prince in Tow", description = "Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.", objectives = "" }
WordHunterWoW_QuestEN[52981] = { title = "Killer Queen", description = "Lor'danel is now secure, but something is amiss... there has been no sign of Stormrage. \n\nMalfurion would have never let Lor'danel fall without a fight. He must have gone after her.\n\nMy army has approached from the North, and our reinforcements have arrived from the South -- which means that they are not along any of the roads.\n\nSearch the forest with me, {name}. We will find them and be done with this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[52990] = { title = "Return to the Harbor", description = "With the scepter in hand, let us return to the portal.\n\nI believe Stone would agree with me when I say that it is best for us to get away from Kul Tiras for a while.", objectives = "" }
WordHunterWoW_QuestEN[52991] = { title = "[REMOVED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[53003] = { title = "A Cycle of Hatred", description = "We have raised new champions for the Horde, established footholds on Kul Tiran soil, and stolen one of their precious artifacts.\n\nWe hold greater power and sway over our enemies than we have before.\n\nSylvanas has great plans for our Horde, {name}. I will allow you the pleasure of reporting our victories to her personally.", objectives = "" }
WordHunterWoW_QuestEN[53006] = { title = "Mission Report: Grimwatt's Crash", description = "Your followers have sent a report regarding the rescue mission to Grimwatt's Crash.\n\nIt details that the supplies were recovered and the enemies surrounding the crash site have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53007] = { title = "Grimwatt's Crash", description = "The rescue that you planned for Grimwatt's Crash in Nazmir was successful. Well done.\n\nI believe we should fortify the crash site and turn it into an outpost.\n\nMake your way to Grimwatt's Crash and establish fortifications there.\n\nGrimwatt's Crash will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[53011] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[53028] = { title = "A Dying World", description = "Champion. Magni Bronzebeard needs your help.\n\nAzeroth is dying. Before this war, a massive demon called Sargeras stabbed the planet with a sword.\n\nOur planet cries out in pain while the Horde and Alliance fight amongst each other.\n\nMagni Bronzebeard believes you can help heal the planet's wounds.\n\nMeet him in Silithus. He has set up camp where Sargeras's sword impacted our world.", objectives = "" }
WordHunterWoW_QuestEN[53041] = { title = "Sampling the Goods", description = "Bridgeport is a major trade hub for this area. Naturally, Ashvane has offices and workshops here.\n\nCheck around town and see if you can learn anything about this new material and how they're using it.\n\nIf you can lift a sample for us to send back to Boralus, even better.\n\nI gotta stay here and keep an eye on someone.", objectives = "" }
WordHunterWoW_QuestEN[53043] = { title = "Mission Report: Vulture's Nest", description = "Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun.\n\nIt details that the mission was a success and that the troops holding the outpost have requested reinforcements.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53044] = { title = "Vulture's Nest", description = "The mission to take Vulture's Nest in Vol'dun was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Vulture's Nest and establish fortifications there.\n\nIt will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[53045] = { title = "Surveying the Wharf", description = "Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. \n\nIt was also in the direct war path of the naga -- who knows what remains now.\n\nIf you could stop in and check in on its leader, Coxswain Hook, you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.", objectives = "" }
WordHunterWoW_QuestEN[53050] = { title = "Deeper Into Kul Tiras", description = "It is time for us to further our hold on Kul Tiras.\n\nReturn to the Banshee's Wail. From there we shall plan our next course of action.", objectives = "" }
WordHunterWoW_QuestEN[53052] = { title = "Deeper Into Zandalar", description = "Our advisors have decided that now is the correct time to further our hold on Zandalar.\n\nReturn to the Wind's Redemption posthaste. We shall leave for new lands immediately.", objectives = "" }
WordHunterWoW_QuestEN[53053] = { title = "To The Mugambala!", description = "The Rastari have proven to be formidable allies in combat, and reports are coming in that help explain how they've honed their battle prowess. \n\nJe'stry the Untamed has a fighting ring setup at the base of Mount Mugambala that could prove useful for getting ready for war.  We've dispatched our troops to take advantage of these training grounds, go and see what High Warlord Volrath has uncovered.", objectives = "" }
WordHunterWoW_QuestEN[53054] = { title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would find benefit in this Dueler's Guild.  Speak with a nearby Rastari Guard to participate in the carnage.", objectives = "" }
WordHunterWoW_QuestEN[53055] = { title = "Pushing Our Influence", description = "Our scouts have identified a location for a final major foothold in Zandalar.\n\nReturn to the Wind's Redemption so we can ship out.", objectives = "" }
WordHunterWoW_QuestEN[53056] = { title = "Pushing Our Influence", description = "We have identified a location for a final major foothold in Kul Tiras.\n\nReturn to the Banshee's Wail to discuss our new mission.", objectives = "" }
WordHunterWoW_QuestEN[53061] = { title = "The Azerite Advantage", description = "{name}, we have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must acquire this precious resource before our enemies in the Horde.\n\nReport to the Wind's Redemption as soon as possible to aid in extraction.", objectives = "" }
WordHunterWoW_QuestEN[53062] = { title = "The Azerite Advantage", description = "We have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must move quickly to acquire these resources for the Horde.\n\nReport to the Banshee's Wail to aid in this urgent mission.", objectives = "" }
WordHunterWoW_QuestEN[53063] = { title = "A Mission of Unity", description = "You have done much for the Alliance during your time here in Kul Tiras, {name}.\n\nToday we must ask more of you. Return to the Wind's Redemption when you have the chance so that we can discuss.", objectives = "" }
WordHunterWoW_QuestEN[53064] = { title = "A Mission of Unity", description = "You have undertaken great journeys during your time here in Zandalar.\n\nIt is time for your next mission. Report to the Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53065] = { title = "Operation: Grave Digger", description = "Sylvanas has issued us a mission in Drustvar, where we will find our next target.\n\nReport to the Banshee's Wail immediately.", objectives = "" }
WordHunterWoW_QuestEN[53066] = { title = "Operation: Water Wise", description = "Rexxar has reported back with news of a new... ally.\n\nReport to the Banshee's Wail for your briefing.", objectives = "" }
WordHunterWoW_QuestEN[53067] = { title = "Operation: Bottom Feeder", description = "It is time for Zelling to prove his worth to the Horde.\n\nReturn to the Banshee's Wail. Today, we sail out to open waters.", objectives = "" }
WordHunterWoW_QuestEN[53068] = { title = "Operation: Hook and Line", description = "Thanks to the help of our new allies, we have devised a plan to extract a powerful tidesage artifact from Boralus.\n\nI have already sent Valentine to get us started.\n\nReport to the Banshee's Wail posthaste.", objectives = "" }
WordHunterWoW_QuestEN[53069] = { title = "Operation: Blood Arrow", description = "We have uncovered the location of a high priority target in Nazmir.\n\nReturn to the Wind's Redemption for your briefing.", objectives = "" }
WordHunterWoW_QuestEN[53070] = { title = "Operation: Cutpurse", description = "It is time to reconvene for our next mission, though Shandris and I disagree on what exactly that should entail.\n\nMeet us on the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53071] = { title = "Operation: Gryphon's Claw", description = "SI:7 has procured some interesting intel.\n\nI request your presence on the Wind's Redemption immediately to help decide our next course of action.", objectives = "" }
WordHunterWoW_QuestEN[53072] = { title = "Operation: Heartstrike", description = "We've taken out quite a number of high priority targets, {name}. All thanks to your help.\n\nIt is time to strike directly at the heart of the Zandalari empire.\n\nReport to the Wind's Redemption as soon as you are able. We will get started from there.", objectives = "" }
WordHunterWoW_QuestEN[53073] = { title = "Hook Point Investigation", description = "I'm sure you've heard the constant sound of battle coming from Hook Point.\n\nWe sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground.\n\nDaniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.", objectives = "" }
WordHunterWoW_QuestEN[53074] = { title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", objectives = "" }
WordHunterWoW_QuestEN[53075] = { title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would benefit from training in the Dueler's Guild.  Speak with a nearby bouncer to participate in the carnage.", objectives = "" }
WordHunterWoW_QuestEN[53079] = { title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", objectives = "" }
WordHunterWoW_QuestEN[53080] = { title = "Bumps in the Road", description = "There's been a disruption in ore deliveries from the mine. A small team of our engineers managed to disable a few of the devices causing all this trouble. \n\nIf you can salvage a few of the parts for me to examine I'm sure I'll be able to craft us a few countermeasures.", objectives = "" }
WordHunterWoW_QuestEN[53081] = { title = "Mission Report: Spare Parts", description = "Your followers have sent a report regarding the mission to collect salvage for Stonefist Watch.\n\nIt details that the mission was a success and the necessary materials have been collected.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53082] = { title = "Spare Parts", description = "An engineer has been assigned to Stonefist Watch to build a scrapping machine.\n\nThe mission to salvage materials for the machine was a success thanks to your leadership.\n\nMake your way to Stonefist Watch in Tiragarde Sound and meet with Grizvek Gearsnap. He has been overseeing the upgrades for the outpost.", objectives = "" }
WordHunterWoW_QuestEN[53095] = { title = "A Flicker of Hope", description = "Champion, I need your help!\n\nWe must evacuate Darnassus before it burns to ash! Many of the city's structures have already caught fire. Douse the flames and rescue the trapped civilians within!\n\nPlease, do all that you can... we must save as many lives as possible.", objectives = "" }
WordHunterWoW_QuestEN[53097] = { title = "Despondent Ablutions", description = "You return. A surprise. Perhaps there is still hope.\n\nIn victory or defeat, you bear the weight of this place. It hangs on you like a mantle. I see your struggle to bear it.\n\nThere is, perhaps, a way to shrug off this burden. An altar, to the northwest. Built by the tidesages, seeking to wash away the corruption.\n\nOffer yourself to the idol. It will exact a price, as do all things. But in communion you may claw back from the brink.", objectives = "" }
WordHunterWoW_QuestEN[53098] = { title = "Champion: Shandris Feathermoon", description = "", objectives = "" }
WordHunterWoW_QuestEN[53099] = { title = "A Mote of Cosmic Truth", description = "We stand on the brink, you and I. The final act looms over us, casting a terrible shadow.\n\nDeep we plumbed, seeking knowledge of the world. Deeper still we delved, until our fate was inevitable. Minds were shattered, my comrades ran screaming into the night. We are all lost, to that terrible Thing...\n\nNow, the malformed syzygy beckons. Complete the ritual and bring about the end.", objectives = "" }
WordHunterWoW_QuestEN[53100] = { title = "Mission Report: Giant Slaying", description = "Your followers have sent a report regarding the mission at Stonetusk Watch.\n\nIt details that the mission was a success and that one of the ettins is being held captive.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53101] = { title = "Nettin' Ettin", description = "An ettin has been captured by our troops at Stonetusk Watch.\n\nApparently, the creature is being trained to work for the Horde as a beast of burden.\n\nMake your way to Stonetusk Watch in Stormsong Valley and meet with Wyna Breezehorn. She has been training the ettin to do her bidding.", objectives = "" }
WordHunterWoW_QuestEN[53102] = { title = "Mission Report: Nature Calls", description = "Your followers have sent a report regarding the mission at Swiftwind Post.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53103] = { title = "Wicker Magic", description = "It seems that the druids at Swiftwind Post have learned much from the ancient Drust rituals you recovered.\n\nThe druids are now able to offer improved services at the outpost.\n\nMake your way to Swiftwind Post in Drustvar and see what they have to offer.", objectives = "" }
WordHunterWoW_QuestEN[53105] = { title = "Misplaced Faith", description = "The air is foul with corruption. It must be dealt with.\n\nThe tidesages were fools, and I a fool to trust them. Belief in their god to perform miracles and deliver us from our folly. Nevertheless, their methods did serve to drive back the foul presence from these cliffs.\n\nA simple censer, loaded with select powders and oils. The vapors produce an effect that expels the miasma, if only for a time.\n\nPerhaps their ineffectual gesticulation will finally serve a purpose.", objectives = "" }
WordHunterWoW_QuestEN[53109] = { title = "House Waycrest", description = "You have done much for my home and the people of Drustvar,\n\nTell your allies that House Waycrest will return to Boralus shortly.", objectives = "" }
WordHunterWoW_QuestEN[53110] = { title = "The High Thornspeaker", description = "My teacher, Ulfar, the High Thornspeaker, must be informed of what's been going on here.\n\nI can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs.\n\nYou have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. \n\nArthur will meet you at the head of the path to Ulfar's den.", objectives = "" }
WordHunterWoW_QuestEN[53121] = { title = "Siege of Boralus", description = "", objectives = "" }
WordHunterWoW_QuestEN[53122] = { title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron and speak to Darkcaller Yanka. She can tell you more about the Wickerman ceremony.", objectives = "" }
WordHunterWoW_QuestEN[53125] = { title = "Mission Report: Into The Wicker", description = "Your followers have sent a report regarding the mission at Mudfisher Cove.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53126] = { title = "The Wicker Totem", description = "The defense of Mudfisher Cove was successful. Well done, {name}.\n\nA mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar.\n\nTravel to Mudfisher Cove in Drustvar and see what power this totem contains.", objectives = "" }
WordHunterWoW_QuestEN[53127] = { title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", objectives = "" }
WordHunterWoW_QuestEN[53128] = { title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", objectives = "" }
WordHunterWoW_QuestEN[53129] = { title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Orgrimmar can tell you what happened here.", objectives = "" }
WordHunterWoW_QuestEN[53130] = { title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Stormwind can tell you what happened here.", objectives = "" }
WordHunterWoW_QuestEN[53131] = { title = "Kings' Rest", description = "", objectives = "" }
WordHunterWoW_QuestEN[53146] = { title = "Boulderfist Beatdown", description = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain.\n\nYou know what must be done.", objectives = "" }
WordHunterWoW_QuestEN[53148] = { title = "Boulderfist Beatdown", description = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi.\n\nYou know what must be done.", objectives = "" }
WordHunterWoW_QuestEN[53149] = { title = "Wiping Out the Witherbark", description = "The Witherbark tribe has a long and bloody history in the highlands of Arathi.\n\nShow them how much bloodier it can get.", objectives = "" }
WordHunterWoW_QuestEN[53150] = { title = "Wiping Out the Witherbark", description = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed.\n\nDrive the forest trolls from the Highlands.", objectives = "" }
WordHunterWoW_QuestEN[53151] = { title = "Mission Report: Wolves For The Den", description = "Your followers have sent a report regarding the mission at Wolf's Den.\n\nIt details that the mission was a success and that a pack of direwolves now guard the outpost.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "" }
WordHunterWoW_QuestEN[53152] = { title = "Wolves for the Den", description = "The mission at Wolf's Den in Tiragarde Sound was a success. Well done, {name}.\n\nA pack of direwolves now patrols the area surrounding the outpost.\n\nTravel to Wolf's Den and see that the training of the wolves is up to our standard.", objectives = "" }
WordHunterWoW_QuestEN[53153] = { title = "Death to The Defilers", description = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands.\n\nThe farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.", objectives = "" }
WordHunterWoW_QuestEN[53154] = { title = "The League Will Lose", description = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands.\n\nThe northern farmland will belong to the Horde. Go, and defeat the humans.", objectives = "" }
WordHunterWoW_QuestEN[53155] = { title = "Notched Coin", description = "<This old, worn coin has clearly changed hands many times. The edges are rusty from years in the salty air of the Great Sea, and it features an unusual design.\n\nYou saw a number of these coins scattered around the island, they appear to be quite commonly used.>", objectives = "" }
WordHunterWoW_QuestEN[53160] = { title = "Ancient Crypt Key", description = "<A magical device found on the mogu island invaders, it contains no more power.\n\nYou are aware of similar devices that were used to activate ancient titan machinery in the mogu vaults of Pandaria.\n\nThis particular one teems with a foreboding presence.\n\nThe Lorewalkers may know more about this device.>", objectives = "" }
WordHunterWoW_QuestEN[53161] = { title = "Ring of the Reefs", description = "<A light mist twists and curls around this ring as if caressing it.\n\nHolding this object makes you uneasy, deep within your soul. It feels as if invisible, icy hands from the lands of the dead are pulling at you.\n\nThere is no mistaking Helya's power.\n\nThe Valarjar will want to hear about this.>", objectives = "" }
WordHunterWoW_QuestEN[53162] = { title = "Sins of the Syndicate", description = "As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers.\n\nPunish them.", objectives = "" }
WordHunterWoW_QuestEN[53163] = { title = "Bloodwake Drinking Horn", description = "<A large drinking horn taken from one of the Bloodwake vrykul.\n\nThe sturdy craftsmanship has allowed it to survive many years of hard travel on the Great Sea.\n\nAs you hold the horn, you remember how fervently the vrykul you encountered were after the Azerite, but to what end?\n\nOther vrykul tribes may know more about the Bloodwake and their motivations.>", objectives = "" }
WordHunterWoW_QuestEN[53164] = { title = "Sonic Stone", description = "<The stone vibrates to your touch. The frequency resonates throughout your body, and you feel refreshed.\n\nThe mantid likely use these stones to allow them to fly great distances across the sea.\n\nTo see them on the island was strange, the mantid took a heavy blow when Shek'zeer was destroyed, they should not be swarming now.\n\nThe denizens of Pandaria may have more information.>", objectives = "" }
WordHunterWoW_QuestEN[53167] = { title = "Icetusk Fur Cloak", description = "<The fur on this cloak is worn and tattered, but it is still warm. It has seen many years in the harsh, unforgiving blizzards of the north.\n\nThe icetusk tribe has not been seen on Azeroth until now, someone in Northrend might know more about them.>", objectives = "" }
WordHunterWoW_QuestEN[53168] = { title = "Magical Spyglass", description = "<This spyglass allows you to see far off into the distance, but looking through it for too long gives you a headache.\n\nThe lens appears to have been specifically crafted for someone else's eyes.\n\nGiven the intricate detail on the spyglass, they'd likely provide a hefty reward for its return.>", objectives = "" }
WordHunterWoW_QuestEN[53169] = { title = "Elemental Core", description = "<A burned-out core from the elementals you encountered.\n\nWhen you concentrate, you can sense that some elemental energy still exists, deep within the core.\n\nThey were clearly after the Azerite, but why?\n\nIt might be time to call in an old favor.>", objectives = "" }
WordHunterWoW_QuestEN[53170] = { title = "Unscarred Black Scale", description = "<An utterly pristine black dragon scale taken from the dragons you recently encountered.\n\nThe black dragonflight was completely decimated following Deathwing's demise and Wrathion's rise to power.\n\nYet the size indicates a younger dragon.\n\nThere is one person, one dragon, that you know will want to hear of this, but where IS Wrathion?\n\nYou surmise he may be some place familiar, fortified, and abandoned.>", objectives = "" }
WordHunterWoW_QuestEN[53171] = { title = "Battered Twilight Scale", description = "<The worn scale of a twilight dragon, it has seen many years of fighting.\n\nThe twilight dragons were thought to have been defeated with the fall of Sinestra, how were there so many on the island?\n\nAnd who is leading the flight?>", objectives = "" }
WordHunterWoW_QuestEN[53172] = { title = "Venture Co. Business Plan", description = "<An enormous volume, and printed in very small print. You can't make it through even a few sentences before the words begin to swim before your eyes.\n\nThe Venture Company's long-term plan appears to be quite complex and nearly impossible to understand.\n\nOne thing is for certain: a competing enterprise would likely pay well to get their hands on this tome.>", objectives = "" }
WordHunterWoW_QuestEN[53173] = { title = "Sins of the Syndicate", description = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers.\n\nPunish them.", objectives = "" }
WordHunterWoW_QuestEN[53174] = { title = "Murloc Eye", description = "<The murloc eye appears to have no magical properties of its own, but is still quite damp to the touch.\n\nYou have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose.\n\nThis is unsettling, even for the naga.>", objectives = "" }
WordHunterWoW_QuestEN[53175] = { title = "The Warfront Looms", description = "We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe.\n\nOne particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory.\n\nSpeak with Ralston Karn, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", objectives = "" }
WordHunterWoW_QuestEN[53176] = { title = "Glittering Scarab", description = "<A magical trinket found on a tol'vir spellcaster, it appears to augment their casting abilities.\n\nIt seems to be very old, but is nearly pristine in form. \n\nThe tol'vir of Uldum may know more about the sudden appearance of the Amathet.>", objectives = "" }
WordHunterWoW_QuestEN[53177] = { title = "Broken Compass", description = "<A compass found on a stranded pirate, it no longer functions. \n\nThe metal and craftsmanship indicate an origin in Stormwind.>", objectives = "" }
WordHunterWoW_QuestEN[53178] = { title = "Razorfin Hunting Spear", description = "<This spear is razor sharp, though it has clearly seen many years of hunting in the open sea.\n\nThe shaft has been broken in several places and repaired with what materials were available at the time. From the variety of repair materials, you surmise that the jinyu tribe you recently faced must travel extensively.\n\nThe friendly jinyu of Pandaria might know more about this strange tribe.>", objectives = "" }
WordHunterWoW_QuestEN[53179] = { title = "Executing Exorcisms", description = "Even in death, the Horde foolishly clings to Alliance territory.\n\nDrive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.", objectives = "" }
WordHunterWoW_QuestEN[53180] = { title = "Vorus'arak's Carapace", description = "<The carapace from the nerubian lord Vorus'arak, it looks ancient.\n\nIt appears that Vorus'arak did not want to shed his shell, and instead wore the same scarred carapace for a very long time.\n\nAll across the carapace, strange markings have been carved. It seems to be a language of some kind.>", objectives = "" }
WordHunterWoW_QuestEN[53181] = { title = "Druidic Fur", description = "<This fur teems with natural magic. The beasts you fought on the island were clearly not beasts at all, but druids.\n\nAt least they were before.\n\nWhat could have caused them to become feral?\n\nYou did not want to slay them, but they gave you no choice, didn't they?>", objectives = "" }
WordHunterWoW_QuestEN[53182] = { title = "Strangling Root", description = "<The root twists and struggles in your grip, attempting to wrap itself around your arm.\n\nThe keepers you encountered must be powerfully attuned to nature to imbue their creations with such longetivity.\n\nRemembering the ferocity with which they fought against you makes you suddenly uneasy.\n\nWhy would these guardians of nature behave this way?\n\nSurely, someone must have the answers.>", objectives = "" }
WordHunterWoW_QuestEN[53183] = { title = "Wriggling Mass", description = "<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts.\n\nOne vision in particular surfaces in your mind again and again.\n\nIn your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle.\n\nAs you sink into the icy darkness, everything goes black.\n\nYou pocket the mass and shake the thoughts from your head.", objectives = "" }
WordHunterWoW_QuestEN[53184] = { title = "Weathered Pamphlet", description = "<This pamphlet appears to be a mass-produced flier advertising an Azerite-buying service.\n\nYou can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" \n\nThere is no mention of any of the dangers involved.\n\nThere is some information about who to contact at the bottom, however.>", objectives = "" }
WordHunterWoW_QuestEN[53185] = { title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nAlliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[53186] = { title = "Mission Report: Ambush at Grimwatt's Crash", description = "Your followers have sent a report regarding the mission at Grimwatt''s Crash.\n\nIt details that the mission was a success and the attacking blood trolls were defeated.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53187] = { title = "An Unexpected Guest", description = "The mission to defend Grimwatt's Crash was a success. Well done, {name}.\n\nIn addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training.\n\nMake your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.", objectives = "" }
WordHunterWoW_QuestEN[53190] = { title = "Executing Exorcisms", description = "Even in death, the Alliance foolishly clings to Horde territory.\n\nDrive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", objectives = "" }
WordHunterWoW_QuestEN[53192] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", objectives = "" }
WordHunterWoW_QuestEN[53193] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", objectives = "" }
WordHunterWoW_QuestEN[53194] = { title = "To the Front", description = "I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nYvera Dawnwing maintains a portal directly to Stromgarde. She can help you.", objectives = "" }
WordHunterWoW_QuestEN[53197] = { title = "Touring the Front", description = "The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Grayson Bell, the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.", objectives = "" }
WordHunterWoW_QuestEN[53198] = { title = "Back to Boralus", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.", objectives = "" }
WordHunterWoW_QuestEN[53199] = { title = "The Torcanata", description = "", objectives = "" }
WordHunterWoW_QuestEN[53207] = { title = "The Warfront Looms", description = "Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe.\n\nWe are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde.\n\nSpeak with Throk, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", objectives = "" }
WordHunterWoW_QuestEN[53208] = { title = "To the Front", description = "We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nDruza Netherfang maintains a portal directly to Ar'gorok. She can help you.", objectives = "" }
WordHunterWoW_QuestEN[53209] = { title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nShow some pride and give what you can. For the Horde!", objectives = "" }
WordHunterWoW_QuestEN[53210] = { title = "Touring the Front", description = "The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Flightgineer Krazzle. He can give you a quick look at Stromgarde, so you can see what we're up against.", objectives = "" }
WordHunterWoW_QuestEN[53212] = { title = "Back to Zuldazar", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.", objectives = "" }
WordHunterWoW_QuestEN[53221] = { title = "Mission Report: Missing Supplies", description = "Your followers have sent a report regarding the mission at Vulture's Nest.\n\nIt details that the mission was a success and the lost supply shipment has been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53222] = { title = "Necessary Supplies", description = "The mission to recover the supplies was a success. Well done, {name}.\n\nThe supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for.\n\nMake your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug.", objectives = "" }
WordHunterWoW_QuestEN[53267] = { title = "Mission Report: Dino Research", description = "Your followers have sent a report regarding the mission at Verdant Hollow.\n\nIt details that the mission was a success and a variety of dinasaur specimens have been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53268] = { title = "Dino Research", description = "The mission to gather research specimens was a success. Well done, {name}.\n\nYou should check in with the outpost commander and inspect the specimens yourself.\n\nMake your way to Verdant Hollow in Zuldazar and speak with Argrim Stonedeep.", objectives = "" }
WordHunterWoW_QuestEN[53275] = { title = "Mission Report: Spare Parts", description = "Your followers have sent a report regarding the mission to collect salvage for Mugamba Overlook.\n\nIt details that the mission was a success and the necessary materials have been collected.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53276] = { title = "Spare Parts", description = "An engineer has been assigned to Mugamba Overlook to build a scrapping machine.\n\nThe mission to salvage materials for the machine was a success thanks to your leadership.\n\nMake your way to Mugamba Overlook in Zuldazar and meet with Gilblin Clockspark. He has been overseeing the upgrades for the outpost.", objectives = "" }
WordHunterWoW_QuestEN[53295] = { title = "Do Your Part", description = "The b-b-barber shop? I'm sorry, what? You want to know where the barber shop is?\n\nI'm sorry {race}, do you know there is a W-A-R going on right now?\n\nSpeaking of which, what have you done for the Alliance lately? Get out there and slay some Horde, or I'll shave your head myself.", objectives = "" }
WordHunterWoW_QuestEN[53306] = { title = "Mission Report: Jungle Escort", description = "Your followers have sent a report regarding the escort mission to Mistvine Ledge.\n\nIt details that the mission was a success and the reinforcements arrived safely at their destination.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "" }
WordHunterWoW_QuestEN[53307] = { title = "Jungle Escort", description = "There are now healers stationed at Mistvine Ledge.\n\nThe mission to escort the reinforcements through the jungle was a success thanks to your leadership.\n\nMake your way to Mistvine Ledge in Zuldazar and meet with the outpost commander there to ensure she has everything she needs.", objectives = "" }
WordHunterWoW_QuestEN[53310] = { title = "From the Ashes...", description = "We must return to Stormwind, quickly!", objectives = "" }
WordHunterWoW_QuestEN[53330] = { title = "WANTED: Razorclaw Alpha", description = "The Horde requires your contributions!\n\nWe are in need of materials to craft and repair our arms and armor.\n\nThere are bountiful resources in this land and they are but ours for the taking.\n\nSeek out the largest wolf you can find, slay it, and secure it's pelt so that we may craft a cloak befitting Rexxar!\n\n- Centurion Kaga Warmstone", objectives = "" }
WordHunterWoW_QuestEN[53332] = { title = "Time for War", description = "You should return to Commander Wyrmbane to begin working with the 7th Legion.", objectives = "" }
WordHunterWoW_QuestEN[53333] = { title = "Time for War", description = "You should return to Nathanos Blightcaller to begin working with The Honorbound.", objectives = "" }
WordHunterWoW_QuestEN[53336] = { title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "" }
WordHunterWoW_QuestEN[53337] = { title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "" }
WordHunterWoW_QuestEN[53338] = { title = "Prove your Worth", description = "See many Alliance out there, {race}? We're getting reports of more and more Alliance showing up here on Zandalar.\n\nDon't forget that this is a W-A-R. Prove your worth, and get out there and slay as many of them as you can.\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[53342] = { title = "Molten Core", description = "We'll need a fragment o' the core tae repair the Black Anvil an' who knows how much dark iron tae achieve the necessary purity. Thaelin can figure that part out.\n\nIn fact, I think he oughta go with ye tae get yerself a Fragment o' the Molten Core.\n\nIt's too dangerous tae go deep via mole machine, but he's got a hardy tank that can get ye the rest o' the way from the top.\n\nTalk tae me when yer ready.", objectives = "" }
WordHunterWoW_QuestEN[53347] = { title = "Bumbles the Bee", description = "Hey {name}, thanks for delivering Mom's letter. I was really starting to worry about her!\n\nDad and I have been having a few problems running the farm after she left on her trip. If you didn't show up when you did, we'd still be in real trouble!\n\nI was hoping you would be willing to help Bumbles out too. He was hurt when his hive was destoyed.\n\nIf we feed him some of Dad's special formula, hopefully he will heal up faster. First we need to find the secret ingredient, try looking around at his other lab.", objectives = "" }
WordHunterWoW_QuestEN[53348] = { title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She poses a serious threat to our troop movements in the south.\n\nAs such, Centurion Kaga Warmstone has issued a bounty for proof of her demise.\n\nThundersnout's location is near the Briarback kraul, so beware the local quilboar!", objectives = "" }
WordHunterWoW_QuestEN[53351] = { title = "The MOTHERLODE!!: Ironfoe", description = "Mogul Razdunk has always been a jealous sort, wishin' he was Gallywix or better.\n\nBut he's the worst sort o' greedy. He won't stop at anythin' tae achieve his ends, nae matter the cost.\n\nIt was a bold move even fer him tae strike at us in Blackrock Depths.\n\nHe should've knaewn he was goin' too far. Kill that covetous wretch an' bring the hammer back where it belongs.\n\nYou'll find him in Kezan. Somewhere he calls \"The Motherlode,\" likely with too many exclamation points.", objectives = "" }
WordHunterWoW_QuestEN[53352] = { title = "Firelands", description = "Alright, the hard part should be behind us, {name}.\n\nNow, we just need tae take that Molten Core fragment ye recovered into Firelands an' charge it up by Ragnaros' old swimmin' pool.\n\nDinna worry! I'm sendin' Anvil-Thane Thurgaden with ye.\n\nJust give me a nudge when ye're ready.", objectives = "" }
WordHunterWoW_QuestEN[53353] = { title = "Echo of Warlord Zaela", description = "Warlord Zaela... another name that stains the tongue just to speak it...\n\nShe was instrumental in freeing Garrosh during his trial when she and her Dragonmaw clan attacked the Temple of the White Tiger.\n\nI am ashamed to say that the dragon Kairozdormu was also involved. We will speak of this no more.\n\nThe temple in Kun Lai Summit is our next destination.", objectives = "" }
WordHunterWoW_QuestEN[53354] = { title = "Echo of Gul'dan", description = "To attune this shard to the place you wish to go, we must follow some of its history.\n\nThe first location we will visit is the Dark Portal in the Blasted Lands.\n\nIt was there that Gul'dan used a piece of the Vision of Time to travel between realities.\n\nJoin me there when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[53355] = { title = "Echo of Garrosh Hellscream", description = "Our final destination will take us to the depths beneath your city of Orgrimmar.\n\nThe way there is barred, but I can get us inside.\n\nMeet me outside the gates of Orgrimmar and we will descend together.", objectives = "" }
WordHunterWoW_QuestEN[53358] = { title = "Test of Hyphen Tech", description = "This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN'T a--dreadlord, really?", objectives = "" }
WordHunterWoW_QuestEN[53369] = { title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", objectives = "" }
WordHunterWoW_QuestEN[53370] = { title = "Battle for Azeroth: Hour of Reckoning", description = "Champions of the Alliance, \n\nAt last the time has come for us to reclaim what is rightfully ours! Our final push to retake Lordaeron Keep shall commence at dawn. \n\nThe Horde and their Warchief must answer for their crimes!", objectives = "" }
WordHunterWoW_QuestEN[53371] = { title = "Let's Bee Friends", description = "We just need to collect some slime from the animated honey creatures that are still roaming around the farm.\n\nIf you can bring back a few vials of that, we can put all our ingredients together and give the mixture to Bumbles.\n\nWe should only feed him once a day, or he might get sick like some of the other bees.\n\nWe're gonna have him all healed up in no time!", objectives = "" }
WordHunterWoW_QuestEN[53377] = { title = "BFA 111-119 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53382] = { title = "BFA 120 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53390] = { title = "BFA 111-119 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53393] = { title = "BFA 120 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53401] = { title = "BFA 120 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53402] = { title = "BFA 120 E", description = "", objectives = "" }
WordHunterWoW_QuestEN[53413] = { title = "A Greater Effort", description = "Champion, I write this letter with a steady hand on parchment laid atop the latest shipment of supplies from our recent efforts.\n\nOur allies continue to gather as our soldiers, weapons, and provisions arrive from lands far and wide. \n\nPlease join me at the docks at once. We have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[53414] = { title = "Warfront: The Battle for Stromgarde", description = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall!\n\nPrepare yourself for battle.", objectives = "" }
WordHunterWoW_QuestEN[53415] = { title = "A Greater Effort", description = "Warrior of the Horde, the time has come.\n\nOur forces gather with strength and steel to prepare for the battle to come. Join us in our effort to remove the Alliance from Arathi once and for all.\n\nI await your arrival at the docks.", objectives = "" }
WordHunterWoW_QuestEN[53416] = { title = "Warfront: The Battle for Stromgarde", description = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt!\n\nTake up arms. The Alliance is upon us.", objectives = "" }
WordHunterWoW_QuestEN[53430] = { title = "Order of Embers Crossbow", description = "<Old and worn, this crossbow resembles those depicted in artwork of the Order of Embers.>", objectives = "" }
WordHunterWoW_QuestEN[53431] = { title = "Order of Embers Flask", description = "<Old and worn, this flask resembles those depicted in artwork of the Order of Embers.>", objectives = "" }
WordHunterWoW_QuestEN[53432] = { title = "Order of Embers Knife", description = "<Old and worn, this knife resembles those depicted in artwork of the Order of Embers.>", objectives = "" }
WordHunterWoW_QuestEN[53433] = { title = "Order of Embers Hat", description = "<Old and worn, this hat resembles those depicted in artwork of the Order of Embers.>", objectives = "" }
WordHunterWoW_QuestEN[53434] = { title = "The Vanishing Lord", description = "Whoa there! What business do you have in Drustvar?\n\nLookin' for someone from House Waycrest? Best of luck to ye.  Even us in their guard haven't heard a word from them of late. Why, if it weren't for Marshal Reade takin' command, I doubt there'd even be a Waycrest Guard anymore.\n\nI think ye'd be better off on yer way, but if yer bent on stayin' I'd head over to Fallhaven. The mayor there is probably the only welcomin' soul left around here.\n\nWatch yer back, mainlander. There's dark workings about.", objectives = "" }
WordHunterWoW_QuestEN[53437] = { title = "The MOTHERLODE!!: Raw Deal", description = "Nobody, and I mean NOBODY double-crosses me and gets away with it!\n\nThe Venture Co. betrayed us in a deal for Azerite refining techniques. We need pay 'em what we owe 'em.\n\nIf you're not pickin' up what I'm puttin' down, I mean we need to kill that backstabbin' upstart Mogul Razdunk.\n\nYou take care of him; I'll take care of gettin' what we're owed.\n\nI s'pose we oughta tell Blightcaller about this, huh? When he tells us what to do, just smile and nod. We'll handle it our way.", objectives = "" }
WordHunterWoW_QuestEN[53438] = { title = "WANTED: Wyvern Poachers", description = "Soldiers of the Horde!\n\nA few nights ago some foolish human soundrels snuck off with one of our strongest wyverns.\n\nIf anybody can track down and stop these thieves, a reward awaits!", objectives = "" }
WordHunterWoW_QuestEN[53439] = { title = "Blood in the Tides", description = "We do not have sirens in Zandalar, but our sailors know of dem. In Zandalari, we call dem bwon'tulak - de death singers.\n\nMy ship was run aground and my fellow sailors all murdered by de death singers.\n\nJane saved my life, so now I help to protect dese people.\n\nSirens are a plague on da seas, no matter who ya serve. Run the tides red wit dere blood!", objectives = "" }
WordHunterWoW_QuestEN[53440] = { title = "WANTED: The Hornet", description = "That's it, I'm putting a bounty on that blasted hornet.\n\nSomebody take that bug down!", objectives = "" }
WordHunterWoW_QuestEN[53442] = { title = "The Castaways", description = "You don't look like you're from around here. You're lucky the sirens haven't stripped your bones yet.\n\nIf you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me.\n\nEveryone there washed up in the tides. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive.\n\nTalk to Stabby Jane. Don't worry about her nickname, she's actually real nice.", objectives = "" }
WordHunterWoW_QuestEN[53443] = { title = "My Favorite Things", description = "It's tough out here.\n\nPirates. Deadly monsters. \n\nHungry Sam's seemingly endless battle with indigestion.\n\nNothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going.\n\nAsk around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture.\n\nMe? Oh... I had a locket... \n\nNever mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", objectives = "" }
WordHunterWoW_QuestEN[53444] = { title = "Glimmering Locket", description = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design.\n\nOpening the locket reveals a hand-drawn picture of a woman with fiery red bangs. \n\nHer arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", objectives = "" }
WordHunterWoW_QuestEN[53445] = { title = "Silencing the Sisters", description = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk.\n\nBut you can't very well kill all of them. Only a fool would try that.\n\nThe real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\"\n\nI managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", objectives = "" }
WordHunterWoW_QuestEN[53446] = { title = "Local Flavor", description = "I'm STARVING.\n\nNot actually starving, like when I first got here, but you know... Emotionally starving.\n\nHaven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks.\n\nHow about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice.\n\nCan you get me some? I'm not much of a hunter. But I'll share it with you!", objectives = "" }
WordHunterWoW_QuestEN[53449] = { title = "Apes of Wrath", description = "Alliance, just what I need. Down for performing a deed?\n\nZandalari are afraid, of new gorillas that raid.\n\nThese gorillas are mocking, these gorillas are talking.\n\nGorillas are dookering, I hear they follow bad king. \n\nIt is important to lead, but this guy fails to succeed.\n\nI shall send Flap-Flap ahead. Make ookin' wikket King dead.", objectives = "" }
WordHunterWoW_QuestEN[53450] = { title = "King Da'ka", description = "King Da'ka? More like King Dooker.\n\nMy king sent me to talk to this new king. This new king took my things and tried to take my wings.\n\nNegotiations are ooked. Go, sticket to that angry wikket.", objectives = "" }
WordHunterWoW_QuestEN[53451] = { title = "WANTED: Raging Earthguard", description = "I have been receiving formal complaints about some big earth elemental in the middle of our scouting path.\n\nNormally I'd elect to ignore these, but the sooner we get done here, the better. Nobody wants to be stuck in this frozen hill any longer than we need to.\n\nPayment goes to the person who brings it down!", objectives = "" }
WordHunterWoW_QuestEN[53452] = { title = "Gorilla Warfare", description = "Your timing is most fortuitous, stranger. I thank you for your assistance.\n\nThings are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. \n\nMy brethren are those who do not wish to fight. But for our passivity we have been persecuted.\n\nPlease free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", objectives = "" }
